import React, { useMemo } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Worker, Incident } from '../types';
import { AlertTriangle, TrendingUp, Users, Activity } from 'lucide-react';

interface DashboardProps {
  workers: Worker[];
  incidents: Incident[];
}

const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8'];

const Dashboard: React.FC<DashboardProps> = ({ workers, incidents }) => {

  const stats = useMemo(() => {
    const avgProd = workers.reduce((acc, w) => acc + w.productivityScore, 0) / workers.length;
    const avgFatigue = workers.reduce((acc, w) => acc + w.fatigueLevel, 0) / workers.length;
    const openRisks = incidents.filter(i => i.severity === 'High' || i.severity === 'Critical').length;

    return {
      avgProd: Math.round(avgProd),
      avgFatigue: Math.round(avgFatigue),
      openRisks,
      totalWorkers: workers.length
    };
  }, [workers, incidents]);

  const incidentData = useMemo(() => {
    const counts: Record<string, number> = {};
    incidents.forEach(i => {
      counts[i.type] = (counts[i.type] || 0) + 1;
    });
    return Object.keys(counts).map(key => ({ name: key, value: counts[key] }));
  }, [incidents]);

  const productivityData = useMemo(() => {
    return workers.map(w => ({
      name: w.name.split(' ')[0], // First name for chart
      productivity: w.productivityScore,
      fatigue: w.fatigueLevel
    }));
  }, [workers]);

  return (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-slate-800">Operational Overview</h2>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-center space-x-4">
          <div className="p-3 bg-blue-100 rounded-lg text-blue-600">
            <TrendingUp size={24} />
          </div>
          <div>
            <p className="text-sm text-slate-500">Avg Productivity</p>
            <p className="text-2xl font-bold text-slate-800">{stats.avgProd}%</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-center space-x-4">
          <div className="p-3 bg-orange-100 rounded-lg text-orange-600">
            <Activity size={24} />
          </div>
          <div>
            <p className="text-sm text-slate-500">Avg Fatigue Level</p>
            <p className={`text-2xl font-bold ${stats.avgFatigue > 40 ? 'text-orange-600' : 'text-green-600'}`}>
              {stats.avgFatigue}%
            </p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-center space-x-4">
          <div className="p-3 bg-red-100 rounded-lg text-red-600">
            <AlertTriangle size={24} />
          </div>
          <div>
            <p className="text-sm text-slate-500">High Severity Incidents</p>
            <p className="text-2xl font-bold text-slate-800">{stats.openRisks}</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-center space-x-4">
          <div className="p-3 bg-indigo-100 rounded-lg text-indigo-600">
            <Users size={24} />
          </div>
          <div>
            <p className="text-sm text-slate-500">Active Workforce</p>
            <p className="text-2xl font-bold text-slate-800">{stats.totalWorkers}</p>
          </div>
        </div>
      </div>

      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">Workforce Metrics</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={productivityData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" stroke="#64748b" />
                <YAxis stroke="#64748b" />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0' }}
                />
                <Bar dataKey="productivity" fill="#3b82f6" name="Productivity" radius={[4, 4, 0, 0]} />
                <Bar dataKey="fatigue" fill="#f97316" name="Fatigue" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">Incident Distribution</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={incidentData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  fill="#8884d8"
                  paddingAngle={5}
                  dataKey="value"
                >
                  {incidentData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
            <div className="flex flex-wrap gap-2 justify-center mt-4">
              {incidentData.map((entry, index) => (
                <div key={entry.name} className="flex items-center text-xs text-slate-600">
                  <span className="w-3 h-3 rounded-full mr-1" style={{ backgroundColor: COLORS[index % COLORS.length] }}></span>
                  {entry.name}
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Worker, Shift, OptimizationResult } from '../types';
import { optimizeSchedule } from '../services/gemini';
import { Calendar, UserCheck, Zap, BrainCircuit, Loader2 } from 'lucide-react';

interface Props {
  workers: Worker[];
  shifts: Partial<Shift>[];
}

const ScheduleOptimizer: React.FC<Props> = ({ workers, shifts }) => {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<OptimizationResult | null>(null);

  const handleOptimize = async () => {
    setLoading(true);
    try {
      const data = await optimizeSchedule(shifts, workers);
      setResult(data);
    } catch (e) {
      alert("Failed to optimize schedule. Check API Key.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Smart Schedule Optimizer</h2>
          <p className="text-slate-500">AI-driven deployment based on skills, fatigue, and productivity.</p>
        </div>
        <button
          onClick={handleOptimize}
          disabled={loading}
          className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-6 py-3 rounded-lg shadow-md transition-all disabled:opacity-50"
        >
          {loading ? <Loader2 className="animate-spin" size={20} /> : <BrainCircuit size={20} />}
          {loading ? 'Optimizing...' : 'Generate AI Schedule'}
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left: Input Requirements */}
        <div className="lg:col-span-1 space-y-4">
          <h3 className="text-lg font-semibold text-slate-700 flex items-center gap-2">
            <Calendar size={18} /> Shift Requirements
          </h3>
          <div className="space-y-3">
            {shifts.map((shift, idx) => (
              <div key={idx} className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
                <h4 className="font-medium text-slate-800">{shift.name}</h4>
                <div className="mt-2 flex flex-wrap gap-1">
                  {shift.requiredRoles?.map((role, rIdx) => (
                    <span key={rIdx} className="text-xs bg-slate-100 text-slate-600 px-2 py-1 rounded-full border border-slate-200">
                      {role}
                    </span>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Right: AI Output */}
        <div className="lg:col-span-2">
          {!result && !loading && (
            <div className="h-64 flex flex-col items-center justify-center bg-slate-50 rounded-xl border-2 border-dashed border-slate-200 text-slate-400">
              <BrainCircuit size={48} className="mb-4 opacity-50" />
              <p>Click "Generate AI Schedule" to start optimization</p>
            </div>
          )}

          {result && (
            <div className="space-y-6 animate-fade-in">
              <div className="bg-green-50 p-4 rounded-lg border border-green-200 text-green-800">
                <div className="flex items-start gap-3">
                  <Zap className="mt-1 flex-shrink-0" size={18} />
                  <div>
                    <p className="font-semibold">Optimization Summary</p>
                    <p className="text-sm mt-1 opacity-90">{result.improvementSummary}</p>
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 gap-4">
                {result.schedules.map((sched, idx) => (
                  <div key={idx} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                    <div className="bg-slate-50 px-4 py-3 border-b border-slate-200 flex justify-between items-center">
                      <h4 className="font-bold text-slate-700">{sched.shiftName}</h4>
                      <span className="text-xs font-mono bg-blue-100 text-blue-700 px-2 py-1 rounded">
                        {sched.assignments.length} Workers
                      </span>
                    </div>
                    <div className="divide-y divide-slate-100">
                      {sched.assignments.map((assign, aIdx) => (
                        <div key={aIdx} className="p-4 hover:bg-slate-50 transition-colors flex items-start justify-between gap-4">
                          <div className="flex items-center gap-3">
                             <div className="h-10 w-10 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 font-bold text-sm">
                                {assign.workerName.charAt(0)}
                             </div>
                             <div>
                               <p className="font-medium text-slate-800">{assign.workerName}</p>
                               <p className="text-xs text-slate-500 uppercase tracking-wider">{assign.role}</p>
                             </div>
                          </div>
                          <div className="text-right flex-1">
                             <span className="inline-block text-xs text-slate-600 bg-slate-100 px-2 py-1 rounded-md max-w-xs">
                               {assign.reason}
                             </span>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ScheduleOptimizer;

import React, { useState } from 'react';
import { predictOperationalRisk } from '../services/gemini';
import { Worker, RiskPrediction } from '../types';
import { ShieldAlert, CheckCircle, AlertTriangle, Wind, Droplets, Clock } from 'lucide-react';

interface Props {
  workers: Worker[];
}

const RiskAssessment: React.FC<Props> = ({ workers }) => {
  const [context, setContext] = useState('');
  const [loading, setLoading] = useState(false);
  const [prediction, setPrediction] = useState<RiskPrediction | null>(null);

  const predefinedScenarios = [
    "Heavy rain forecast, outdoor crane operation, 2 workers on double shift.",
    "Assembly line speed increased by 15%, 3 junior workers on site.",
    "Night shift, power outage in Zone B, backup generators active."
  ];

  const handlePredict = async () => {
    if (!context) return;
    setLoading(true);
    try {
      const data = await predictOperationalRisk(context, workers);
      setPrediction(data);
    } catch (error) {
      alert("Prediction failed. Check API Key.");
    } finally {
      setLoading(false);
    }
  };

  const getRiskColor = (level: string) => {
    switch (level) {
      case 'Low': return 'text-green-600 bg-green-50 border-green-200';
      case 'Medium': return 'text-yellow-600 bg-yellow-50 border-yellow-200';
      case 'High': return 'text-orange-600 bg-orange-50 border-orange-200';
      case 'Critical': return 'text-red-600 bg-red-50 border-red-200';
      default: return 'text-slate-600 bg-slate-50 border-slate-200';
    }
  };

  return (
    <div className="space-y-8">
      <div>
        <h2 className="text-2xl font-bold text-slate-800">Predictive Risk Assessment</h2>
        <p className="text-slate-500">Analyze current conditions to identify potential accidents before they happen.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="space-y-6">
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
            <label className="block text-sm font-medium text-slate-700 mb-2">Operational Context</label>
            <textarea
              value={context}
              onChange={(e) => setContext(e.target.value)}
              placeholder="Describe weather, shift conditions, machinery status, etc..."
              className="w-full h-32 p-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none resize-none text-slate-700"
            />

            <div className="mt-4">
              <p className="text-xs text-slate-500 mb-2">Quick Scenarios:</p>
              <div className="flex flex-wrap gap-2">
                {predefinedScenarios.map((scen, i) => (
                  <button 
                    key={i} 
                    onClick={() => setContext(scen)}
                    className="text-xs bg-slate-100 hover:bg-slate-200 text-slate-700 px-3 py-1.5 rounded-full transition-colors border border-slate-200"
                  >
                    {scen.substring(0, 30)}...
                  </button>
                ))}
              </div>
            </div>

            <button
              onClick={handlePredict}
              disabled={loading || !context}
              className="mt-6 w-full bg-blue-600 hover:bg-blue-700 text-white font-medium py-2.5 rounded-lg transition-all disabled:opacity-50 flex justify-center items-center gap-2"
            >
              {loading ? 'Analyzing...' : 'Assess Risk'}
            </button>
          </div>
        </div>

        <div className="space-y-6">
          {!prediction && !loading && (
             <div className="h-full min-h-[300px] flex flex-col items-center justify-center bg-slate-50 rounded-xl border-2 border-dashed border-slate-200 text-slate-400">
                <ShieldAlert size={48} className="mb-4 opacity-50" />
                <p>Enter context to generate risk prediction</p>
             </div>
          )}

          {prediction && (
            <div className="bg-white rounded-xl shadow-lg overflow-hidden border border-slate-100 animate-fade-in">
              <div className={`p-6 border-b ${getRiskColor(prediction.riskLevel)}`}>
                <div className="flex justify-between items-start">
                  <div>
                    <h3 className="text-lg font-bold uppercase tracking-wide opacity-80">Risk Level</h3>
                    <p className="text-3xl font-extrabold mt-1">{prediction.riskLevel}</p>
                  </div>
                  <div className="text-right">
