import { GoogleGenAI, Type, Schema } from "@google/genai";
import { Worker, Incident, Shift } from "../types";

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// --- Schemas ---

const riskPredictionSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    riskLevel: { type: Type.STRING, enum: ['Low', 'Medium', 'High', 'Critical'] },
    probability: { type: Type.NUMBER, description: "Probability percentage 0-100" },
    factors: { 
      type: Type.ARRAY, 
      items: { type: Type.STRING },
      description: "List of factors contributing to the risk"
    },
    mitigationStrategies: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "Actionable steps to reduce risk"
    }
  },
  required: ["riskLevel", "probability", "factors", "mitigationStrategies"]
};

const scheduleOptimizationSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    schedules: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          shiftName: { type: Type.STRING },
          assignments: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                role: { type: Type.STRING },
                workerName: { type: Type.STRING },
                reason: { type: Type.STRING, description: "Why this worker fits this slot (skills/productivity)" }
              },
              required: ["role", "workerName", "reason"]
            }
          }
        },
        required: ["shiftName", "assignments"]
      }
    },
    improvementSummary: { type: Type.STRING, description: "Brief explanation of why this schedule is better." }
  },
  required: ["schedules", "improvementSummary"]
};

const incidentAnalysisSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    rootCauseAnalysis: { type: Type.STRING },
    trendIdentification: { type: Type.STRING },
    safetyRecommendations: { 
      type: Type.ARRAY, 
      items: { type: Type.STRING } 
    }
  },
  required: ["rootCauseAnalysis", "trendIdentification", "safetyRecommendations"]
};

const realTimeSafetySchema: Schema = {
  type: Type.OBJECT,
  properties: {
    alerts: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          workerId: { type: Type.STRING },
          type: { type: Type.STRING, description: "e.g., Heat Stress, Fatigue, Man Down, PPE Violation" },
          description: { type: Type.STRING },
          priority: { type: Type.STRING, enum: ['High', 'Medium', 'Low'] }
        },
        required: ["workerId", "type", "description", "priority"]
      }
    },
    zoneAnalysis: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          zoneName: { type: Type.STRING },
          safetyStatus: { type: Type.STRING, description: "General safety assessment of this zone based on worker data" }
        },
        required: ["zoneName", "safetyStatus"]
      }
    },
    recommendedActions: {
      type: Type.ARRAY,
      items: { type: Type.STRING }
    }
  },
  required: ["alerts", "zoneAnalysis", "recommendedActions"]
};

// --- API Functions ---

export const analyzeRealTimeSafety = async (workers: Worker[]): Promise<any> => {
  try {
    const streamData = JSON.stringify(workers.map(w => ({
      name: w.name,
      id: w.id,
      location: w.currentLocation,
      vitals: w.vitals,
      ppe: w.ppeCompliant ? "Compliant" : "Violation",
      fatigue: w.fatigueLevel
    })));

    const prompt = `
      Act as an AI Safety Officer for Our Lady of Fatima University General Services.
      Analyze this real-time data stream of workers.

      Data: ${streamData}

      Tasks:
      1. Identify immediate hazards (Heat stroke if Temp > 37.5C, Fatigue if level > 50, PPE violations).
      2. If a worker has abnormal vitals, flag them.
      3. Recommend immediate emergency responses.
    `;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: realTimeSafetySchema,
        systemInstruction: "You are a real-time safety monitoring system. Prioritize human safety and immediate response."
      }
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("Error analyzing real-time safety:", error);
    throw error;
  }
};

export const predictOperationalRisk = async (
  context: string,
  workers: Worker[]
): Promise<any> => {
  try {
    const workerStats = workers.map(w => `${w.name} (Fatigue: ${w.fatigueLevel}%, Role: ${w.role})`).join(", ");

    const prompt = `
      Analyze the operational risk for the following context: "${context}".
      Considering these workers on site: ${workerStats}.
      Predict the risk level, probability, key risk factors, and mitigation strategies.
    `;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: riskPredictionSchema,
        systemInstruction: "You are an expert industrial safety officer and risk analyst."
      }
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("Error predicting risk:", error);
    throw error;
  }
};

export const optimizeSchedule = async (
  shifts: Partial<Shift>[],
  workers: Worker[]
): Promise<any> => {
  try {
    const shiftData = JSON.stringify(shifts.map(s => ({ name: s.name, requiredRoles: s.requiredRoles })));
    const workerData = JSON.stringify(workers.map(w => ({ 
      name: w.name, 
      role: w.role, 
      skillLevel: w.skillLevel, 
      productivity: w.productivityScore, 
