              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {workers.map(worker => (
                <tr key={worker.id} className="hover:bg-slate-50">
                  <td className="px-6 py-4 font-medium text-slate-900">{worker.name}</td>
                  <td className="px-6 py-4 text-slate-500">{worker.role}</td>
                  <td className="px-6 py-4">
                     {worker.fatigueLevel > 30 ? (
                       <span className="text-orange-600 flex items-center gap-1"><AlertTriangle size={14}/> Fatigue {worker.fatigueLevel}%</span>
                     ) : (
                       <span className="text-green-600 flex items-center gap-1"><CheckCircle2 size={14}/> Fit</span>
                     )}
                  </td>
                  <td className="px-6 py-4">
                    <span className={`px-2 py-1 rounded-full text-xs font-bold ${
                      worker.safetyStatus === 'Cleared' ? 'bg-green-100 text-green-700' :
                      worker.safetyStatus === 'Rejected' ? 'bg-red-100 text-red-700' :
                      worker.safetyStatus === 'Deployed' ? 'bg-blue-100 text-blue-700' :
                      'bg-yellow-100 text-yellow-700'
                    }`}>
                      {worker.safetyStatus.toUpperCase()}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    {worker.safetyStatus === 'Pending' || worker.safetyStatus === 'Rejected' ? (
                      <button 
                        onClick={() => handleOpenChecklist(worker)}
                        className="bg-indigo-600 text-white px-3 py-1.5 rounded text-xs font-medium hover:bg-indigo-700 transition"
                      >
                        Verify Safety
                      </button>
                    ) : (
                      <span className="text-slate-400 text-xs italic">Reviewed</span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );

  const renderSupervisorView = () => (
    <div className="space-y-6">
      <div className="bg-indigo-50 border border-indigo-200 p-4 rounded-lg flex items-start gap-3">
        <Briefcase className="text-indigo-600 mt-1" />
        <div>
          <h3 className="font-bold text-indigo-800">Supervisor Dashboard</h3>
          <p className="text-sm text-indigo-600">Assign cleared personnel to active shifts. Only Safety-Cleared workers are eligible.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-4 rounded-xl border border-slate-200">
          <h4 className="font-bold text-slate-700 mb-4 flex items-center gap-2">
            <ShieldCheck size={18} className="text-green-600"/> Available & Cleared Workers
          </h4>
          <div className="space-y-2">
            {workers.filter(w => w.safetyStatus === 'Cleared').length === 0 && (
              <p className="text-sm text-slate-400 italic">No workers currently cleared for deployment.</p>
            )}
            {workers.filter(w => w.safetyStatus === 'Cleared').map(worker => (
              <div key={worker.id} className="p-3 border border-green-100 bg-green-50 rounded-lg flex justify-between items-center group">
                 <div>
                   <p className="font-bold text-slate-800 text-sm">{worker.name}</p>
                   <p className="text-xs text-slate-500">{worker.role} • {worker.skillLevel}</p>
                 </div>
                 <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                    {shifts.map((shift, i) => (
                      <button 
                        key={i}
                        onClick={() => handleDeploy(worker.id, shift.name || 'Site')}
                        className="text-xs bg-indigo-600 text-white px-2 py-1 rounded hover:bg-indigo-700"
                      >
                        Deploy to {shift.name?.split(' ')[0]}
