                className="flex-1 bg-green-600 text-white font-bold py-2.5 rounded-lg hover:bg-green-700 transition disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Approve & Clear
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

