import React, { useState, useEffect } from 'react';
import { Worker, SafetyChecklist, Shift, UserRole } from '../types';
import { getClearanceRecommendation } from '../services/gemini';
import { ClipboardCheck, ShieldCheck, UserCheck, AlertTriangle, Briefcase, FileSignature, CheckCircle2, XCircle, BrainCircuit } from 'lucide-react';

interface Props {
  workers: Worker[];
  shifts: Partial<Shift>[];
  userRole: UserRole;
}

const WorkforceDeployment: React.FC<Props> = ({ workers: initialWorkers, shifts, userRole }) => {
  // If Admin, default to SafetyOfficer, but allow toggling. If other role, force that role.
  const [activeView, setActiveView] = useState<'SafetyOfficer' | 'Supervisor'>(
    userRole === 'Supervisor' ? 'Supervisor' : 'SafetyOfficer'
  );

  useEffect(() => {
    if (userRole === 'Supervisor') setActiveView('Supervisor');
    else if (userRole === 'SafetyOfficer') setActiveView('SafetyOfficer');
  }, [userRole]);

  const [workers, setWorkers] = useState<Worker[]>(initialWorkers);
  const [selectedWorker, setSelectedWorker] = useState<Worker | null>(null);
  const [aiRecommendation, setAiRecommendation] = useState<any>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // Checklist State
  const [checklist, setChecklist] = useState<SafetyChecklist>({
    ppeCheck: false,
    trainingValid: false,
    healthCheck: false,
    permitsActive: false
  });

  const handleOpenChecklist = async (worker: Worker) => {
    setSelectedWorker(worker);
    setChecklist({ ppeCheck: false, trainingValid: false, healthCheck: false, permitsActive: false });
    setAiRecommendation(null);
    setLoadingAi(true);

    try {
      const rec = await getClearanceRecommendation(worker);
      setAiRecommendation(rec);
    } catch (e) {
      console.error("AI Recommendation failed");
    } finally {
      setLoadingAi(false);
    }
  };

  const submitSafetyDecision = (status: 'Cleared' | 'Rejected') => {
    if (!selectedWorker) return;

    setWorkers(prev => prev.map(w => 
      w.id === selectedWorker.id ? { ...w, safetyStatus: status } : w
    ));
    setSelectedWorker(null);
  };

  const handleDeploy = (workerId: string, shiftName: string) => {
    setWorkers(prev => prev.map(w => 
      w.id === workerId ? { ...w, safetyStatus: 'Deployed', currentLocation: shiftName } : w
    ));
  };

  const renderSafetyOfficerView = () => (
    <div className="space-y-6">
      <div className="bg-blue-50 border border-blue-200 p-4 rounded-lg flex items-start gap-3">
        <ClipboardCheck className="text-blue-600 mt-1" />
        <div>
          <h3 className="font-bold text-blue-800">Safety Officer Dashboard</h3>
          <p className="text-sm text-blue-600">Review worker profiles and verify safety checklists before clearance.</p>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-6 py-4 font-semibold text-slate-700">Worker</th>
                <th className="px-6 py-4 font-semibold text-slate-700">Role</th>
                <th className="px-6 py-4 font-semibold text-slate-700">Health Status</th>
                <th className="px-6 py-4 font-semibold text-slate-700">Clearance Status</th>
                <th className="px-6 py-4 font-semibold text-slate-700">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {workers.map(worker => (
                <tr key={worker.id} className="hover:bg-slate-50">
                  <td className="px-6 py-4 font-medium text-slate-900">{worker.name}</td>
                  <td className="px-6 py-4 text-slate-500">{worker.role}</td>
                  <td className="px-6 py-4">
                     {worker.fatigueLevel > 30 ? (
                       <span className="text-orange-600 flex items-center gap-1"><AlertTriangle size={14}/> Fatigue {worker.fatigueLevel}%</span>
                     ) : (
                       <span className="text-green-600 flex items-center gap-1"><CheckCircle2 size={14}/> Fit</span>
                     )}
                  </td>
                  <td className="px-6 py-4">
                    <span className={`px-2 py-1 rounded-full text-xs font-bold ${
                      worker.safetyStatus === 'Cleared' ? 'bg-green-100 text-green-700' :
                      worker.safetyStatus === 'Rejected' ? 'bg-red-100 text-red-700' :
                      worker.safetyStatus === 'Deployed' ? 'bg-blue-100 text-blue-700' :
                      'bg-yellow-100 text-yellow-700'
                    }`}>
                      {worker.safetyStatus.toUpperCase()}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    {worker.safetyStatus === 'Pending' || worker.safetyStatus === 'Rejected' ? (
                      <button 
                        onClick={() => handleOpenChecklist(worker)}
                        className="bg-indigo-600 text-white px-3 py-1.5 rounded text-xs font-medium hover:bg-indigo-700 transition"
                      >
                        Verify Safety
                      </button>
                    ) : (
                      <span className="text-slate-400 text-xs italic">Reviewed</span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );

  const renderSupervisorView = () => (
    <div className="space-y-6">
      <div className="bg-indigo-50 border border-indigo-200 p-4 rounded-lg flex items-start gap-3">
        <Briefcase className="text-indigo-600 mt-1" />
        <div>
          <h3 className="font-bold text-indigo-800">Supervisor Dashboard</h3>
          <p className="text-sm text-indigo-600">Assign cleared personnel to active shifts. Only Safety-Cleared workers are eligible.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-4 rounded-xl border border-slate-200">
          <h4 className="font-bold text-slate-700 mb-4 flex items-center gap-2">
            <ShieldCheck size={18} className="text-green-600"/> Available & Cleared Workers
          </h4>
          <div className="space-y-2">
            {workers.filter(w => w.safetyStatus === 'Cleared').length === 0 && (
              <p className="text-sm text-slate-400 italic">No workers currently cleared for deployment.</p>
            )}
            {workers.filter(w => w.safetyStatus === 'Cleared').map(worker => (
              <div key={worker.id} className="p-3 border border-green-100 bg-green-50 rounded-lg flex justify-between items-center group">
                 <div>
                   <p className="font-bold text-slate-800 text-sm">{worker.name}</p>
                   <p className="text-xs text-slate-500">{worker.role} • {worker.skillLevel}</p>
                 </div>
                 <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                    {shifts.map((shift, i) => (
                      <button 
                        key={i}
                        onClick={() => handleDeploy(worker.id, shift.name || 'Site')}
                        className="text-xs bg-indigo-600 text-white px-2 py-1 rounded hover:bg-indigo-700"
                      >
                        Deploy to {shift.name?.split(' ')[0]}
                      </button>
                    ))}
                 </div>
              </div>
            ))}
          </div>
        </div>

        <div className="bg-white p-4 rounded-xl border border-slate-200">
          <h4 className="font-bold text-slate-700 mb-4 flex items-center gap-2">
            <UserCheck size={18} className="text-blue-600"/> Deployed Workforce
          </h4>
          <div className="space-y-2">
            {workers.filter(w => w.safetyStatus === 'Deployed').map(worker => (
              <div key={worker.id} className="p-3 border border-blue-100 bg-blue-50 rounded-lg flex justify-between items-center">
                 <div>
                   <p className="font-bold text-slate-800 text-sm">{worker.name}</p>
                   <p className="text-xs text-slate-500">{worker.currentLocation}</p>
                 </div>
                 <span className="text-xs font-bold text-blue-700 bg-blue-100 px-2 py-1 rounded">ACTIVE</span>
              </div>
            ))}
            {workers.filter(w => w.safetyStatus === 'Deployed').length === 0 && (
              <p className="text-sm text-slate-400 italic">No workers deployed yet.</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="space-y-6">
      {/* Role Toggle Header */}
      <div className="flex justify-between items-center">
        <div>
           <h2 className="text-2xl font-bold text-slate-800">Deployment & Compliance</h2>
           <p className="text-slate-500">Manage safety clearances and project assignments.</p>
        </div>

        {/* Only Admin sees the toggle */}
        {userRole === 'Admin' && (
          <div className="bg-white border border-slate-200 rounded-lg p-1 flex gap-1">
            <button
              onClick={() => setActiveView('SafetyOfficer')}
              className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${
                activeView === 'SafetyOfficer' ? 'bg-indigo-100 text-indigo-700' : 'text-slate-500 hover:bg-slate-50'
              }`}
            >
              Safety Officer
            </button>
            <button
              onClick={() => setActiveView('Supervisor')}
              className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${
                activeView === 'Supervisor' ? 'bg-indigo-100 text-indigo-700' : 'text-slate-500 hover:bg-slate-50'
              }`}
            >
              Supervisor
            </button>
          </div>
        )}
      </div>

      {activeView === 'SafetyOfficer' ? renderSafetyOfficerView() : renderSupervisorView()}

      {/* Safety Checklist Modal */}
      {selectedWorker && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl w-full max-w-lg overflow-hidden animate-fade-in">
            <div className="bg-indigo-600 p-4 text-white flex justify-between items-center">
              <h3 className="font-bold flex items-center gap-2"><FileSignature size={20}/> Safety Clearance Checklist</h3>
              <button onClick={() => setSelectedWorker(null)}><XCircle className="opacity-80 hover:opacity-100"/></button>
            </div>

            <div className="p-6 space-y-6">
              <div className="flex justify-between items-center bg-slate-50 p-3 rounded-lg border border-slate-200">
                <div>
                  <p className="font-bold text-slate-800">{selectedWorker.name}</p>
                  <p className="text-xs text-slate-500">{selectedWorker.role}</p>
                </div>
                <div className="text-right text-xs">
                   <p>Fatigue: {selectedWorker.fatigueLevel}%</p>
                   <p>Temp: {selectedWorker.vitals.bodyTemp}°C</p>
                </div>
              </div>

              {/* AI Insight */}
              <div className="bg-gradient-to-r from-indigo-50 to-blue-50 border border-indigo-100 p-4 rounded-lg">
                <h4 className="text-xs font-bold text-indigo-600 uppercase mb-2 flex items-center gap-1">
                  <BrainCircuit size={14}/> AI Recommendation
                </h4>
                {loadingAi ? (
                  <p className="text-sm text-slate-500 italic">Analyzing worker profile...</p>
                ) : aiRecommendation ? (
                  <div>
                    <p className={`font-bold ${aiRecommendation.recommendation === 'Approve' ? 'text-green-700' : 'text-red-700'}`}>
                      Suggestion: {aiRecommendation.recommendation}
                    </p>
                    <p className="text-xs text-slate-600 mt-1">{aiRecommendation.reasoning}</p>
                  </div>
                ) : (
                  <p className="text-sm text-slate-500">AI Analysis unavailable.</p>
                )}
              </div>

              {/* Checklist Form */}
              <div className="space-y-3">
                <label className="flex items-center gap-3 p-3 border border-slate-200 rounded-lg hover:bg-slate-50 cursor-pointer">
                  <input type="checkbox" className="w-5 h-5 text-indigo-600 rounded" 
                    checked={checklist.ppeCheck}
                    onChange={e => setChecklist({...checklist, ppeCheck: e.target.checked})}
                  />
                  <span className="text-sm font-medium text-slate-700">PPE Verified & Compliant</span>
                </label>
                <label className="flex items-center gap-3 p-3 border border-slate-200 rounded-lg hover:bg-slate-50 cursor-pointer">
                  <input type="checkbox" className="w-5 h-5 text-indigo-600 rounded" 
                     checked={checklist.trainingValid}
                     onChange={e => setChecklist({...checklist, trainingValid: e.target.checked})}
                  />
                  <span className="text-sm font-medium text-slate-700">Training Certificates Valid</span>
                </label>
                <label className="flex items-center gap-3 p-3 border border-slate-200 rounded-lg hover:bg-slate-50 cursor-pointer">
                  <input type="checkbox" className="w-5 h-5 text-indigo-600 rounded" 
                     checked={checklist.healthCheck}
                     onChange={e => setChecklist({...checklist, healthCheck: e.target.checked})}
                  />
                  <span className="text-sm font-medium text-slate-700">Fit-to-Work (Health Check)</span>
                </label>
                <label className="flex items-center gap-3 p-3 border border-slate-200 rounded-lg hover:bg-slate-50 cursor-pointer">
                  <input type="checkbox" className="w-5 h-5 text-indigo-600 rounded" 
                     checked={checklist.permitsActive}
                     onChange={e => setChecklist({...checklist, permitsActive: e.target.checked})}
                  />
                  <span className="text-sm font-medium text-slate-700">Work Permits Active</span>
                </label>
              </div>
            </div>

            <div className="p-4 bg-slate-50 border-t border-slate-200 flex gap-3">
              <button 
                onClick={() => submitSafetyDecision('Rejected')}
                className="flex-1 bg-white border border-red-300 text-red-700 font-bold py-2.5 rounded-lg hover:bg-red-50 transition"
              >
                Reject Clearance
              </button>
              <button 
                onClick={() => submitSafetyDecision('Cleared')}
                disabled={!Object.values(checklist).every(Boolean)}
                className="flex-1 bg-green-600 text-white font-bold py-2.5 rounded-lg hover:bg-green-700 transition disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Approve & Clear
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

