        </nav>

        <div className="p-4 border-t border-green-800">
          <div className="flex items-center gap-3 mb-4 px-2">
             <div className="w-8 h-8 rounded-full bg-green-800 border border-green-600 flex items-center justify-center text-xs font-bold text-white">
               {user.name.charAt(0)}
             </div>
             <div className="flex-1 overflow-hidden">
               <p className="text-sm font-medium text-white truncate">{user.name}</p>
               <p className="text-xs text-green-300 truncate">{user.role}</p>
             </div>
          </div>
          <button 
            onClick={handleLogout}
            className="w-full bg-green-800 hover:bg-green-700 text-green-100 py-2 rounded-lg text-sm font-medium transition-colors flex items-center justify-center gap-2"
          >
            <LogOut size={16} /> Logout
