import React, { useState, useEffect } from 'react';
import { Worker, RealTimeAnalysis } from '../types';
import { analyzeRealTimeSafety } from '../services/gemini';
import { Heart, Thermometer, User, MapPin, ShieldCheck, ShieldAlert, Activity, Radio, AlertTriangle, Phone, Siren } from 'lucide-react';

interface Props {
  initialWorkers: Worker[];
}

const SafetyMonitoring: React.FC<Props> = ({ initialWorkers }) => {
  const [workers, setWorkers] = useState<Worker[]>(initialWorkers);
  const [analysis, setAnalysis] = useState<RealTimeAnalysis | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [lastScan, setLastScan] = useState<Date | null>(null);

  // Simulate live data updates
  useEffect(() => {
    const interval = setInterval(() => {
      setWorkers(prev => prev.map(w => {
        // Randomly fluctuate vitals slightly to simulate realism
        const hrFluctuation = Math.floor(Math.random() * 5) - 2;
        const tempFluctuation = (Math.random() * 0.2) - 0.1;

        let newHr = w.vitals.heartRate + hrFluctuation;
        let newTemp = w.vitals.bodyTemp + tempFluctuation;

        // Boundaries
        if (newHr < 50) newHr = 50; if (newHr > 160) newHr = 160;
        if (newTemp < 36) newTemp = 36; if (newTemp > 40) newTemp = 40;

        // Auto-detect critical status based on simple thresholds (Client-side simulation)
        let status = w.status;
        if (newTemp > 38 || newHr > 130) status = 'Warning';
        if (newTemp > 39 || newHr > 150) status = 'Critical';

        return {
          ...w,
          vitals: {
            ...w.vitals,
            heartRate: newHr,
            bodyTemp: Number(newTemp.toFixed(1))
          },
          status: status
        };
      }));
    }, 2000);

    return () => clearInterval(interval);
  }, []);

  const handleScan = async () => {
    setIsScanning(true);
    try {
      const result = await analyzeRealTimeSafety(workers);
      setAnalysis(result);
      setLastScan(new Date());
    } catch (e) {
      alert("Analysis failed. Please check connection.");
    } finally {
      setIsScanning(false);
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Safe': return 'bg-green-100 text-green-800 border-green-200';
      case 'Active': return 'bg-green-100 text-green-800 border-green-200';
      case 'Warning': return 'bg-orange-100 text-orange-800 border-orange-200 animate-pulse';
      case 'Critical': return 'bg-red-100 text-red-800 border-red-200 animate-pulse-slow';
      default: return 'bg-slate-100 text-slate-800';
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'Warning': return <AlertTriangle size={18} />;
      case 'Critical': return <Siren size={18} />;
      default: return <ShieldCheck size={18} />;
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Real-Time Protection</h2>
          <p className="text-slate-500">Live monitoring of OLFU General Services staff vitals and compliance.</p>
        </div>
        <button
          onClick={handleScan}
          disabled={isScanning}
          className="flex items-center gap-2 bg-green-700 hover:bg-green-800 text-white px-5 py-2.5 rounded-lg shadow-sm transition-all disabled:opacity-70"
        >
          {isScanning ? <Activity className="animate-spin" size={20} /> : <Radio size={20} />}
          {isScanning ? 'Scanning Hazards...' : 'Scan for Hazards'}
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Worker Grid */}
        <div className="lg:col-span-2 grid grid-cols-1 md:grid-cols-2 gap-4">
          {workers.map((worker) => (
            <div key={worker.id} className={`p-4 rounded-xl border-2 transition-all ${
              worker.status === 'Critical' ? 'border-red-400 shadow-red-100 shadow-lg bg-white' : 
              worker.status === 'Warning' ? 'border-orange-300 bg-white' : 
              'border-slate-100 bg-white shadow-sm'
            }`}>
              <div className="flex justify-between items-start mb-3">
                <div className="flex items-center gap-3">
                  <div className={`w-10 h-10 rounded-full flex items-center justify-center text-lg font-bold ${
                    worker.status === 'Critical' ? 'bg-red-100 text-red-600' : 'bg-green-100 text-green-700'
                  }`}>
                    {worker.name.charAt(0)}
                  </div>
                  <div>
                    <h3 className="font-bold text-slate-800">{worker.name}</h3>
                    <p className="text-xs text-slate-500">{worker.role}</p>
                  </div>
                </div>
                <span className={`px-2.5 py-1 rounded-full text-xs font-bold flex items-center gap-1 ${getStatusColor(worker.status)}`}>
                  {getStatusIcon(worker.status)}
                  {worker.status.toUpperCase()}
                </span>
              </div>

              <div className="space-y-3">
                <div className="flex items-center gap-2 text-sm text-slate-600">
                  <MapPin size={16} className="text-slate-400" />
                  <span className="truncate">{worker.currentLocation}</span>
                </div>

                <div className="grid grid-cols-3 gap-2 py-2 border-t border-b border-slate-50">
                  <div className="text-center">
                    <div className="flex items-center justify-center gap-1 text-xs text-slate-400 mb-1">
                      <Heart size={12} /> HR
                    </div>
                    <span className={`font-mono font-bold ${worker.vitals.heartRate > 100 ? 'text-orange-600' : 'text-slate-700'}`}>
                      {Math.round(worker.vitals.heartRate)}
                    </span>
                  </div>
                  <div className="text-center border-l border-slate-100">
                     <div className="flex items-center justify-center gap-1 text-xs text-slate-400 mb-1">
                      <Thermometer size={12} /> Temp
                    </div>
                    <span className={`font-mono font-bold ${worker.vitals.bodyTemp > 37.5 ? 'text-red-600' : 'text-slate-700'}`}>
                      {worker.vitals.bodyTemp.toFixed(1)}°C
                    </span>
                  </div>
                  <div className="text-center border-l border-slate-100">
                     <div className="flex items-center justify-center gap-1 text-xs text-slate-400 mb-1">
                      <ShieldCheck size={12} /> PPE
                    </div>
                    <span className={`text-xs font-bold ${worker.ppeCompliant ? 'text-green-600' : 'text-red-600'}`}>
                      {worker.ppeCompliant ? 'OK' : 'FAIL'}
                    </span>
                  </div>
                </div>

                {worker.status === 'Critical' && (
                  <button className="w-full mt-2 bg-red-600 hover:bg-red-700 text-white py-2 rounded-lg font-bold flex items-center justify-center gap-2 animate-pulse">
                    <Phone size={18} /> DISPATCH EMERGENCY
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>

        {/* AI Analysis Panel */}
        <div className="lg:col-span-1 space-y-4">
          <div className="bg-green-900 text-white p-5 rounded-xl shadow-lg">
            <h3 className="font-bold text-lg mb-4 flex items-center gap-2">
              <ShieldAlert className="text-yellow-400" /> 
              Hazard Identification
            </h3>

            {!analysis ? (
              <div className="text-green-100/60 text-sm text-center py-8">
                <Radio className="mx-auto mb-2 opacity-50" size={32} />
                <p>System monitoring active.</p>
                <p>Click "Scan" for detailed analysis.</p>
              </div>
            ) : (
              <div className="space-y-4 animate-fade-in">
                {analysis.alerts.length === 0 && (
                  <div className="bg-green-500/20 border border-green-500/30 p-3 rounded-lg text-green-300 text-sm">
                    No immediate hazards detected.
                  </div>
                )}

                {analysis.alerts.map((alert, i) => (
                  <div key={i} className={`p-3 rounded-lg border text-sm ${
                    alert.priority === 'High' ? 'bg-red-500/10 border-red-500/30 text-red-200' : 
                    alert.priority === 'Medium' ? 'bg-orange-500/10 border-orange-500/30 text-orange-200' :
                    'bg-blue-500/10 border-blue-500/30 text-blue-200'
                  }`}>
                    <div className="flex justify-between items-start">
                      <span className="font-bold">{alert.type}</span>
                      <span className="text-[10px] uppercase bg-black/20 px-1.5 py-0.5 rounded">{alert.priority}</span>
                    </div>
                    <p className="mt-1 opacity-90">{alert.description}</p>
                    <p className="mt-2 text-xs opacity-60">Worker ID: {alert.workerId}</p>
                  </div>
                ))}

                <div className="pt-4 border-t border-green-700">
                  <h4 className="text-xs font-bold text-green-300 uppercase mb-2">Recommended Actions</h4>
                  <ul className="space-y-2">
                    {analysis.recommendedActions.map((action, i) => (
                      <li key={i} className="flex items-start gap-2 text-sm text-green-100">
                        <span className="w-1.5 h-1.5 bg-green-400 rounded-full mt-1.5 flex-shrink-0"></span>
                        {action}
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            )}

            {lastScan && (
               <p className="text-xs text-green-400 mt-4 text-center">Last Scan: {lastScan.toLocaleTimeString()}</p>
            )}
          </div>

          <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
             <h3 className="font-bold text-slate-800 mb-3 text-sm uppercase">Zone Status</h3>
             <div className="space-y-2">
                {analysis?.zoneAnalysis ? analysis.zoneAnalysis.map((zone, i) => (
                   <div key={i} className="flex justify-between items-center text-sm p-2 bg-slate-50 rounded">
                      <span className="text-slate-700">{zone.zoneName}</span>
                      <span className={`font-medium ${zone.safetyStatus.includes('Safe') ? 'text-green-600' : 'text-orange-600'}`}>
                        {zone.safetyStatus}
                      </span>
                   </div>
                )) : (
                  ['Main Building', 'Science Wing', 'Grounds'].map((z, i) => (
                    <div key={i} className="flex justify-between items-center text-sm p-2 bg-slate-50 rounded">
                      <span className="text-slate-700">{z}</span>
                      <span className="text-slate-400 text-xs">Waiting for scan...</span>
                   </div>
                  ))
                )}
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SafetyMonitoring;

