    if (!selectedWorker) return;

    setWorkers(prev => prev.map(w => 
      w.id === selectedWorker.id ? { ...w, safetyStatus: status } : w
    ));
    setSelectedWorker(null);
  };

  const handleDeploy = (workerId: string, shiftName: string) => {
    setWorkers(prev => prev.map(w => 
      w.id === workerId ? { ...w, safetyStatus: 'Deployed', currentLocation: shiftName } : w
    ));
  };

  const renderSafetyOfficerView = () => (
