          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="space-y-6">
      {/* Role Toggle Header */}
      <div className="flex justify-between items-center">
        <div>
           <h2 className="text-2xl font-bold text-slate-800">Deployment & Compliance</h2>
           <p className="text-slate-500">Manage safety clearances and project assignments.</p>
        </div>

        {/* Only Admin sees the toggle */}
        {userRole === 'Admin' && (
          <div className="bg-white border border-slate-200 rounded-lg p-1 flex gap-1">
            <button
              onClick={() => setActiveView('SafetyOfficer')}
              className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${
