import React, { useState } from 'react';
import { predictOperationalRisk } from '../services/gemini';
import { Worker, RiskPrediction } from '../types';
import { ShieldAlert, CheckCircle, AlertTriangle, Wind, Droplets, Clock } from 'lucide-react';

interface Props {
  workers: Worker[];
}

const RiskAssessment: React.FC<Props> = ({ workers }) => {
  const [context, setContext] = useState('');
  const [loading, setLoading] = useState(false);
  const [prediction, setPrediction] = useState<RiskPrediction | null>(null);

  const predefinedScenarios = [
    "Heavy rain forecast, outdoor crane operation, 2 workers on double shift.",
    "Assembly line speed increased by 15%, 3 junior workers on site.",
    "Night shift, power outage in Zone B, backup generators active."
  ];

  const handlePredict = async () => {
    if (!context) return;
    setLoading(true);
    try {
      const data = await predictOperationalRisk(context, workers);
      setPrediction(data);
    } catch (error) {
      alert("Prediction failed. Check API Key.");
    } finally {
      setLoading(false);
    }
  };

  const getRiskColor = (level: string) => {
    switch (level) {
      case 'Low': return 'text-green-600 bg-green-50 border-green-200';
      case 'Medium': return 'text-yellow-600 bg-yellow-50 border-yellow-200';
      case 'High': return 'text-orange-600 bg-orange-50 border-orange-200';
      case 'Critical': return 'text-red-600 bg-red-50 border-red-200';
      default: return 'text-slate-600 bg-slate-50 border-slate-200';
    }
  };

  return (
    <div className="space-y-8">
      <div>
        <h2 className="text-2xl font-bold text-slate-800">Predictive Risk Assessment</h2>
        <p className="text-slate-500">Analyze current conditions to identify potential accidents before they happen.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="space-y-6">
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
            <label className="block text-sm font-medium text-slate-700 mb-2">Operational Context</label>
            <textarea
              value={context}
              onChange={(e) => setContext(e.target.value)}
              placeholder="Describe weather, shift conditions, machinery status, etc..."
              className="w-full h-32 p-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-green-500 outline-none resize-none text-slate-700"
            />

            <div className="mt-4">
              <p className="text-xs text-slate-500 mb-2">Quick Scenarios:</p>
              <div className="flex flex-wrap gap-2">
                {predefinedScenarios.map((scen, i) => (
                  <button 
                    key={i} 
                    onClick={() => setContext(scen)}
                    className="text-xs bg-slate-100 hover:bg-slate-200 text-slate-700 px-3 py-1.5 rounded-full transition-colors border border-slate-200"
                  >
                    {scen.substring(0, 30)}...
                  </button>
                ))}
              </div>
            </div>

            <button
              onClick={handlePredict}
              disabled={loading || !context}
              className="mt-6 w-full bg-green-700 hover:bg-green-800 text-white font-medium py-2.5 rounded-lg transition-all disabled:opacity-50 flex justify-center items-center gap-2"
            >
              {loading ? 'Analyzing...' : 'Assess Risk'}
            </button>
          </div>
        </div>

        <div className="space-y-6">
          {!prediction && !loading && (
             <div className="h-full min-h-[300px] flex flex-col items-center justify-center bg-slate-50 rounded-xl border-2 border-dashed border-slate-200 text-slate-400">
                <ShieldAlert size={48} className="mb-4 opacity-50" />
                <p>Enter context to generate risk prediction</p>
             </div>
          )}

          {prediction && (
            <div className="bg-white rounded-xl shadow-lg overflow-hidden border border-slate-100 animate-fade-in">
              <div className={`p-6 border-b ${getRiskColor(prediction.riskLevel)}`}>
                <div className="flex justify-between items-start">
                  <div>
                    <h3 className="text-lg font-bold uppercase tracking-wide opacity-80">Risk Level</h3>
                    <p className="text-3xl font-extrabold mt-1">{prediction.riskLevel}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-sm opacity-80">Probability</p>
                    <p className="text-3xl font-bold">{prediction.probability}%</p>
                  </div>
                </div>
              </div>

              <div className="p-6 space-y-6">
                <div>
                  <h4 className="text-slate-800 font-semibold mb-3 flex items-center gap-2">
                    <AlertTriangle size={18} className="text-orange-500"/> Risk Factors
                  </h4>
                  <ul className="space-y-2">
                    {prediction.factors.map((factor, i) => (
                      <li key={i} className="flex items-start gap-2 text-slate-600 text-sm">
                        <span className="mt-1.5 w-1.5 h-1.5 bg-orange-400 rounded-full flex-shrink-0"></span>
                        {factor}
                      </li>
                    ))}
                  </ul>
                </div>

                <div>
                  <h4 className="text-slate-800 font-semibold mb-3 flex items-center gap-2">
                    <CheckCircle size={18} className="text-green-500"/> Mitigation Strategies
                  </h4>
                  <ul className="space-y-2">
                    {prediction.mitigationStrategies.map((strat, i) => (
                      <li key={i} className="flex items-start gap-2 text-slate-600 text-sm bg-green-50 p-2 rounded border border-green-100">
                        {strat}
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default RiskAssessment;

import React, { useState, useEffect } from 'react';
import { Incident } from '../types';
