          <button 
            onClick={handleLogout}
            className="w-full bg-green-600 hover:bg-green-500 text-white py-2 rounded-lg text-sm font-medium transition-colors flex items-center justify-center gap-2"
          >
            <LogOut size={16} /> Logout
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden bg-slate-50">
        {/* Top Header (Mobile) */}
        <div className="lg:hidden bg-white border-b border-slate-200 p-4 flex items-center justify-between shadow-sm">
          <div className="flex items-center space-x-3">
             <div className="w-8 h-8">
               <img 
                 src="https://upload.wikimedia.org/wikipedia/en/e/e6/Our_Lady_of_Fatima_University_seal.png" 
                 alt="OLFU" 
                 className="w-full h-full object-contain"
               />
             </div>
            <span className="font-bold text-green-700">OLFU SafetyNet</span>
          </div>
          <button onClick={() => setIsSidebarOpen(true)} className="text-slate-600">
            <Menu size={24} />
