        </div>

        {/* Scrollable Content Area */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8">
          <div className="max-w-7xl mx-auto">
             {renderContent()}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Worker, Incident } from '../types';
import { AlertTriangle, TrendingUp, Users, Activity } from 'lucide-react';

interface DashboardProps {
  workers: Worker[];
  incidents: Incident[];
}

const COLORS = ['#16a34a', '#4ade80', '#fbbf24', '#f97316', '#ef4444']; // Lighter greens

const Dashboard: React.FC<DashboardProps> = ({ workers, incidents }) => {

  const stats = useMemo(() => {
    const avgProd = workers.reduce((acc, w) => acc + w.productivityScore, 0) / workers.length;
    const avgFatigue = workers.reduce((acc, w) => acc + w.fatigueLevel, 0) / workers.length;
    const openRisks = incidents.filter(i => i.severity === 'High' || i.severity === 'Critical').length;

    return {
      avgProd: Math.round(avgProd),
      avgFatigue: Math.round(avgFatigue),
      openRisks,
      totalWorkers: workers.length
    };
  }, [workers, incidents]);

  const incidentData = useMemo(() => {
    const counts: Record<string, number> = {};
    incidents.forEach(i => {
      counts[i.type] = (counts[i.type] || 0) + 1;
    });
    return Object.keys(counts).map(key => ({ name: key, value: counts[key] }));
  }, [incidents]);

  const productivityData = useMemo(() => {
    return workers.map(w => ({
      name: w.name.split(' ')[0], // First name for chart
      productivity: w.productivityScore,
      fatigue: w.fatigueLevel
    }));
  }, [workers]);

  return (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-slate-800">Operational Overview</h2>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-center space-x-4">
          <div className="p-3 bg-green-50 rounded-lg text-green-600">
            <TrendingUp size={24} />
          </div>
          <div>
            <p className="text-sm text-slate-500">Avg Productivity</p>
            <p className="text-2xl font-bold text-slate-800">{stats.avgProd}%</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-center space-x-4">
          <div className="p-3 bg-orange-100 rounded-lg text-orange-600">
            <Activity size={24} />
          </div>
          <div>
            <p className="text-sm text-slate-500">Avg Fatigue Level</p>
            <p className={`text-2xl font-bold ${stats.avgFatigue > 40 ? 'text-orange-600' : 'text-green-600'}`}>
              {stats.avgFatigue}%
            </p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-center space-x-4">
          <div className="p-3 bg-red-100 rounded-lg text-red-600">
            <AlertTriangle size={24} />
          </div>
          <div>
            <p className="text-sm text-slate-500">High Severity Incidents</p>
            <p className="text-2xl font-bold text-slate-800">{stats.openRisks}</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-center space-x-4">
          <div className="p-3 bg-green-50 rounded-lg text-green-600">
            <Users size={24} />
          </div>
          <div>
            <p className="text-sm text-slate-500">Active Workforce</p>
            <p className="text-2xl font-bold text-slate-800">{stats.totalWorkers}</p>
          </div>
        </div>
      </div>

      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">Workforce Metrics</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={productivityData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" stroke="#64748b" />
                <YAxis stroke="#64748b" />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0' }}
                />
                <Bar dataKey="productivity" fill="#16a34a" name="Productivity" radius={[4, 4, 0, 0]} />
                <Bar dataKey="fatigue" fill="#fbbf24" name="Fatigue" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">Incident Distribution</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={incidentData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  fill="#16a34a"
                  paddingAngle={5}
                  dataKey="value"
                >
                  {incidentData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
            <div className="flex flex-wrap gap-2 justify-center mt-4">
              {incidentData.map((entry, index) => (
                <div key={entry.name} className="flex items-center text-xs text-slate-600">
                  <span className="w-3 h-3 rounded-full mr-1" style={{ backgroundColor: COLORS[index % COLORS.length] }}></span>
                  {entry.name}
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { Worker, SafetyChecklist, Shift, UserRole } from '../types';
import { getClearanceRecommendation } from '../services/gemini';
import { ClipboardCheck, ShieldCheck, UserCheck, AlertTriangle, Briefcase, FileSignature, CheckCircle2, XCircle, BrainCircuit } from 'lucide-react';

interface Props {
  workers: Worker[];
  shifts: Partial<Shift>[];
  userRole: UserRole;
}

const WorkforceDeployment: React.FC<Props> = ({ workers: initialWorkers, shifts, userRole }) => {
  // If Admin, default to SafetyOfficer, but allow toggling. If other role, force that role.
  const [activeView, setActiveView] = useState<'SafetyOfficer' | 'Supervisor'>(
    userRole === 'Supervisor' ? 'Supervisor' : 'SafetyOfficer'
  );

  useEffect(() => {
    if (userRole === 'Supervisor') setActiveView('Supervisor');
    else if (userRole === 'SafetyOfficer') setActiveView('SafetyOfficer');
  }, [userRole]);

  const [workers, setWorkers] = useState<Worker[]>(initialWorkers);
  const [selectedWorker, setSelectedWorker] = useState<Worker | null>(null);
  const [aiRecommendation, setAiRecommendation] = useState<any>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // Checklist State
  const [checklist, setChecklist] = useState<SafetyChecklist>({
    ppeCheck: false,
    trainingValid: false,
    healthCheck: false,
    permitsActive: false
  });

  const handleOpenChecklist = async (worker: Worker) => {
    setSelectedWorker(worker);
    setChecklist({ ppeCheck: false, trainingValid: false, healthCheck: false, permitsActive: false });
    setAiRecommendation(null);
    setLoadingAi(true);

    try {
      const rec = await getClearanceRecommendation(worker);
      setAiRecommendation(rec);
    } catch (e) {
      console.error("AI Recommendation failed");
    } finally {
      setLoadingAi(false);
    }
  };

  const submitSafetyDecision = (status: 'Cleared' | 'Rejected') => {
    if (!selectedWorker) return;

    setWorkers(prev => prev.map(w => 
      w.id === selectedWorker.id ? { ...w, safetyStatus: status } : w
    ));
    setSelectedWorker(null);
  };

  const handleDeploy = (workerId: string, shiftName: string) => {
    setWorkers(prev => prev.map(w => 
      w.id === workerId ? { ...w, safetyStatus: 'Deployed', currentLocation: shiftName } : w
    ));
  };

  const renderSafetyOfficerView = () => (
    <div className="space-y-6">
      <div className="bg-green-50 border border-green-200 p-4 rounded-lg flex items-start gap-3">
        <ClipboardCheck className="text-green-600 mt-1" />
        <div>
          <h3 className="font-bold text-green-800">Safety Officer Dashboard</h3>
          <p className="text-sm text-green-600">Review worker profiles and verify safety checklists before clearance.</p>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-6 py-4 font-semibold text-slate-700">Worker</th>
                <th className="px-6 py-4 font-semibold text-slate-700">Role</th>
                <th className="px-6 py-4 font-semibold text-slate-700">Health Status</th>
                <th className="px-6 py-4 font-semibold text-slate-700">Clearance Status</th>
                <th className="px-6 py-4 font-semibold text-slate-700">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {workers.map(worker => (
