          </h4>
          <div className="space-y-2">
            {workers.filter(w => w.safetyStatus === 'Cleared').length === 0 && (
              <p className="text-sm text-slate-400 italic">No workers currently cleared for deployment.</p>
            )}
            {workers.filter(w => w.safetyStatus === 'Cleared').map(worker => (
              <div key={worker.id} className="p-3 border border-green-100 bg-green-50 rounded-lg flex justify-between items-center group">
                 <div>
                   <p className="font-bold text-slate-800 text-sm">{worker.name}</p>
                   <p className="text-xs text-slate-500">{worker.role} • {worker.skillLevel}</p>
                 </div>
                 <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                    {shifts.map((shift, i) => (
                      <button 
                        key={i}
                        onClick={() => handleDeploy(worker.id, shift.name || 'Site')}
                        className="text-xs bg-green-600 text-white px-2 py-1 rounded hover:bg-green-700"
                      >
                        Deploy to {shift.name?.split(' ')[0]}
                      </button>
                    ))}
                 </div>
              </div>
            ))}
          </div>
        </div>

        <div className="bg-white p-4 rounded-xl border border-slate-200">
          <h4 className="font-bold text-slate-700 mb-4 flex items-center gap-2">
            <UserCheck size={18} className="text-blue-600"/> Deployed Workforce
          </h4>
          <div className="space-y-2">
            {workers.filter(w => w.safetyStatus === 'Deployed').map(worker => (
