              </div>
            ))}
            {workers.filter(w => w.safetyStatus === 'Deployed').length === 0 && (
              <p className="text-sm text-slate-400 italic">No workers deployed yet.</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="space-y-6">
      {/* Role Toggle Header */}
      <div className="flex justify-between items-center">
        <div>
           <h2 className="text-2xl font-bold text-slate-800">Deployment & Compliance</h2>
           <p className="text-slate-500">Manage safety clearances and project assignments.</p>
        </div>

        {/* Only Admin sees the toggle */}
        {userRole === 'Admin' && (
          <div className="bg-white border border-slate-200 rounded-lg p-1 flex gap-1">
            <button
              onClick={() => setActiveView('SafetyOfficer')}
              className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${
                activeView === 'SafetyOfficer' ? 'bg-green-100 text-green-700' : 'text-slate-500 hover:bg-slate-50'
              }`}
            >
              Safety Officer
            </button>
            <button
              onClick={() => setActiveView('Supervisor')}
              className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${
                activeView === 'Supervisor' ? 'bg-green-100 text-green-700' : 'text-slate-500 hover:bg-slate-50'
              }`}
            >
              Supervisor
            </button>
          </div>
        )}
      </div>

      {activeView === 'SafetyOfficer' ? renderSafetyOfficerView() : renderSupervisorView()}

      {/* Safety Checklist Modal */}
      {selectedWorker && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl w-full max-w-lg overflow-hidden animate-fade-in">
            <div className="bg-green-600 p-4 text-white flex justify-between items-center">
