                         <span className="text-green-600 flex items-center gap-1"><CheckCircle2 size={14}/> Fit</span>
                       )}
                    </td>
                    <td className="px-6 py-4">
                      <span className={`px-2 py-1 rounded-full text-xs font-bold ${
                        worker.safetyStatus === 'Rejected' ? 'bg-red-100 text-red-700' : 'bg-yellow-100 text-yellow-700'
                      }`}>
                        {worker.safetyStatus.toUpperCase()}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <button 
                        onClick={() => handleOpenChecklist(worker)}
                        className="bg-green-600 text-white px-3 py-1.5 rounded text-xs font-medium hover:bg-green-700 transition shadow-sm"
                      >
                        Verify & Clear
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );

  const renderSupervisorView = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="bg-blue-50 border border-blue-200 p-4 rounded-lg flex items-start gap-3">
        <Briefcase className="text-blue-600 mt-1" />
        <div>
          <h3 className="font-bold text-blue-800">Supervisor Dashboard</h3>
          <p className="text-sm text-blue-600">
            Assign cleared personnel to active shifts. Only Safety-Cleared workers appear in the "Ready" list.
          </p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Column 1: Available / Cleared */}
        <div className="flex flex-col h-[600px] bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="p-4 bg-green-50 border-b border-green-100 flex justify-between items-center">
             <div className="flex items-center gap-2">
                <ShieldCheck className="text-green-600" size={18} />
                <h4 className="font-bold text-green-900">Ready for Deployment</h4>
             </div>
             <span className="bg-white text-green-700 px-2 py-0.5 rounded-full text-xs font-bold shadow-sm">{clearedCount}</span>
          </div>

          <div className="p-4 overflow-y-auto space-y-3 flex-1 bg-slate-50/50">
            {workers.filter(w => w.safetyStatus === 'Cleared').length === 0 && (
              <div className="text-center py-10 text-slate-400">
                <ClipboardCheck size={32} className="mx-auto mb-2 opacity-50"/>
                <p>No cleared workers available.</p>
                <p className="text-xs">Ask Safety Officer to approve pending staff.</p>
              </div>
            )}

            {workers.filter(w => w.safetyStatus === 'Cleared').map(worker => (
              <div key={worker.id} className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm hover:shadow-md transition-all">
                 <div className="flex justify-between items-start mb-3">
                    <div>
                      <p className="font-bold text-slate-800">{worker.name}</p>
                      <p className="text-xs text-slate-500">{worker.role} • {worker.skillLevel}</p>
                    </div>
                    <span className="text-[10px] bg-green-100 text-green-700 px-2 py-1 rounded-full font-bold">CLEARED</span>
                 </div>

                 <div className="pt-3 border-t border-slate-100">
                    <label className="text-xs text-slate-500 font-medium mb-1 block">Assign to Shift:</label>
                    <div className="flex gap-2">
                       <select 
                         className="flex-1 text-sm border border-slate-300 rounded px-2 py-1 bg-slate-50"
                         onChange={(e) => setSelectedShiftForDeploy(e.target.value)}
                         defaultValue={shifts[0]?.name}
                       >
                         {shifts.map((s, i) => <option key={i} value={s.name}>{s.name?.split(' ')[0]}</option>)}
                       </select>
                       <button 
                         onClick={() => handleDeploy(worker.id, selectedShiftForDeploy)}
                         className="bg-green-600 hover:bg-green-700 text-white px-3 py-1 rounded text-sm font-medium flex items-center gap-1"
                       >
                         Deploy <ArrowRight size={14}/>
                       </button>
                    </div>
                 </div>
              </div>
            ))}
          </div>
        </div>

        {/* Column 2: Deployed */}
        <div className="flex flex-col h-[600px] bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="p-4 bg-blue-50 border-b border-blue-100 flex justify-between items-center">
             <div className="flex items-center gap-2">
                <UserCheck className="text-blue-600" size={18} />
                <h4 className="font-bold text-blue-900">Active Operations</h4>
             </div>
             <span className="bg-white text-blue-700 px-2 py-0.5 rounded-full text-xs font-bold shadow-sm">{deployedCount}</span>
          </div>

          <div className="p-4 overflow-y-auto space-y-3 flex-1 bg-slate-50/50">
            {workers.filter(w => w.safetyStatus === 'Deployed').length === 0 && (
              <div className="text-center py-10 text-slate-400">
                <Briefcase size={32} className="mx-auto mb-2 opacity-50"/>
                <p>No active deployments.</p>
              </div>
            )}

            {workers.filter(w => w.safetyStatus === 'Deployed').map(worker => (
              <div key={worker.id} className="bg-white p-4 rounded-lg border border-blue-200 shadow-sm flex justify-between items-center">
                 <div>
                   <p className="font-bold text-slate-800">{worker.name}</p>
                   <p className="text-xs text-blue-600 font-medium flex items-center gap-1">
                     <MapPin size={12}/> {worker.currentLocation}
                   </p>
                 </div>
                 <button 
                   onClick={() => handleRecall(worker.id)}
                   className="text-xs border border-slate-200 text-slate-600 hover:bg-red-50 hover:text-red-600 px-3 py-1.5 rounded transition-colors flex items-center gap-1"
                   title="End Shift / Recall"
                 >
                   <RotateCcw size={12} /> Recall
                 </button>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="space-y-6">
      {/* Role Toggle Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
           <h2 className="text-2xl font-bold text-slate-800">Deployment & Compliance</h2>
           <p className="text-slate-500">Manage safety clearances and workforce assignment.</p>
        </div>

        {/* Role Switcher Tabs */}
        {(userRole === 'Admin' || userRole === 'Supervisor' || userRole === 'SafetyOfficer') && (
          <div className="bg-white border border-slate-200 rounded-lg p-1 flex gap-1 shadow-sm">
            {(userRole === 'Admin' || userRole === 'SafetyOfficer') && (
              <button
                onClick={() => setActiveView('SafetyOfficer')}
                className={`px-4 py-2 rounded-md text-sm font-medium transition-all flex items-center gap-2 ${
                  activeView === 'SafetyOfficer' 
                  ? 'bg-green-100 text-green-700 shadow-sm' 
                  : 'text-slate-500 hover:bg-slate-50'
                }`}
              >
                Safety Review 
                {pendingCount > 0 && <span className="bg-red-500 text-white text-[10px] px-1.5 rounded-full">{pendingCount}</span>}
              </button>
            )}
            {(userRole === 'Admin' || userRole === 'Supervisor') && (
              <button
                onClick={() => setActiveView('Supervisor')}
                className={`px-4 py-2 rounded-md text-sm font-medium transition-all flex items-center gap-2 ${
                  activeView === 'Supervisor' 
                  ? 'bg-blue-100 text-blue-700 shadow-sm' 
                  : 'text-slate-500 hover:bg-slate-50'
                }`}
              >
                Supervisor
                {clearedCount > 0 && <span className="bg-green-500 text-white text-[10px] px-1.5 rounded-full">{clearedCount}</span>}
              </button>
            )}
          </div>
        )}
      </div>

      {activeView === 'SafetyOfficer' ? renderSafetyOfficerView() : renderSupervisorView()}

      {/* Safety Checklist Modal */}
      {selectedWorker && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl w-full max-w-lg overflow-hidden animate-fade-in scale-100">
            <div className="bg-green-600 p-4 text-white flex justify-between items-center">
              <h3 className="font-bold flex items-center gap-2"><FileSignature size={20}/> Safety Clearance Checklist</h3>
              <button onClick={() => setSelectedWorker(null)}><XCircle className="opacity-80 hover:opacity-100"/></button>
            </div>

            <div className="p-6 space-y-6">
              <div className="flex justify-between items-center bg-slate-50 p-3 rounded-lg border border-slate-200">
                <div>
                  <p className="font-bold text-slate-800">{selectedWorker.name}</p>
                  <p className="text-xs text-slate-500">{selectedWorker.role}</p>
                </div>
                <div className="text-right text-xs">
                   <p>Fatigue: {selectedWorker.fatigueLevel}%</p>
                   <p>Temp: {selectedWorker.vitals.bodyTemp}°C</p>
                </div>
              </div>

              {/* AI Insight */}
              <div className="bg-gradient-to-r from-green-50 to-emerald-50 border border-green-100 p-4 rounded-lg">
                <h4 className="text-xs font-bold text-green-700 uppercase mb-2 flex items-center gap-1">
                  <BrainCircuit size={14}/> AI Recommendation
                </h4>
                {loadingAi ? (
                  <p className="text-sm text-slate-500 italic">Analyzing worker profile...</p>
                ) : aiRecommendation ? (
                  <div>
                    <p className={`font-bold ${aiRecommendation.recommendation === 'Approve' ? 'text-green-700' : 'text-red-700'}`}>
                      Suggestion: {aiRecommendation.recommendation}
                    </p>
                    <p className="text-xs text-slate-600 mt-1">{aiRecommendation.reasoning}</p>
                  </div>
                ) : (
                  <p className="text-sm text-slate-500">AI Analysis unavailable.</p>
                )}
              </div>

              {/* Checklist Form */}
              <div className="space-y-3">
                <label className="flex items-center gap-3 p-3 border border-slate-200 rounded-lg hover:bg-slate-50 cursor-pointer transition-colors">
                  <input type="checkbox" className="w-5 h-5 text-green-600 rounded focus:ring-green-500" 
                    checked={checklist.ppeCheck}
                    onChange={e => setChecklist({...checklist, ppeCheck: e.target.checked})}
                  />
                  <span className="text-sm font-medium text-slate-700">PPE Verified & Compliant</span>
                </label>
                <label className="flex items-center gap-3 p-3 border border-slate-200 rounded-lg hover:bg-slate-50 cursor-pointer transition-colors">
                  <input type="checkbox" className="w-5 h-5 text-green-600 rounded focus:ring-green-500" 
                     checked={checklist.trainingValid}
                     onChange={e => setChecklist({...checklist, trainingValid: e.target.checked})}
                  />
                  <span className="text-sm font-medium text-slate-700">Training Certificates Valid</span>
                </label>
                <label className="flex items-center gap-3 p-3 border border-slate-200 rounded-lg hover:bg-slate-50 cursor-pointer transition-colors">
                  <input type="checkbox" className="w-5 h-5 text-green-600 rounded focus:ring-green-500" 
                     checked={checklist.healthCheck}
                     onChange={e => setChecklist({...checklist, healthCheck: e.target.checked})}
                  />
                  <span className="text-sm font-medium text-slate-700">Fit-to-Work (Health Check)</span>
                </label>
                <label className="flex items-center gap-3 p-3 border border-slate-200 rounded-lg hover:bg-slate-50 cursor-pointer transition-colors">
                  <input type="checkbox" className="w-5 h-5 text-green-600 rounded focus:ring-green-500" 
                     checked={checklist.permitsActive}
                     onChange={e => setChecklist({...checklist, permitsActive: e.target.checked})}
                  />
                  <span className="text-sm font-medium text-slate-700">Work Permits Active</span>
                </label>
              </div>
            </div>

            <div className="p-4 bg-slate-50 border-t border-slate-200 flex gap-3">
              <button 
                onClick={() => submitSafetyDecision('Rejected')}
                className="flex-1 bg-white border border-red-300 text-red-700 font-bold py-2.5 rounded-lg hover:bg-red-50 transition"
              >
                Reject Clearance
              </button>
              <button 
                onClick={() => submitSafetyDecision('Cleared')}
                disabled={!Object.values(checklist).every(Boolean)}
                className="flex-1 bg-green-600 text-white font-bold py-2.5 rounded-lg hover:bg-green-700 transition disabled:opacity-50 disabled:cursor-not-allowed shadow-md"
              >
                Approve & Clear
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default WorkforceDeployment;

import React, { useState } from 'react';
import Dashboard from './components/Dashboard';
import ScheduleOptimizer from './components/ScheduleOptimizer';
import RiskAssessment from './components/RiskAssessment';
import IncidentAnalysis from './components/IncidentAnalysis';
import SafetyMonitoring from './components/SafetyMonitoring';
import WorkforceDeployment from './components/WorkforceDeployment';
import Login from './components/Login';
import UserManagement from './components/UserManagement';
import TechnicianPortal from './components/TechnicianPortal';
import Logo from './components/Logo';
import { mockWorkers, mockIncidents, mockShifts } from './mockData';
import { User, UserRole, Worker } from './types';
import { LayoutDashboard, Users, ShieldAlert, FileWarning, Menu, LogOut, HardHat, Activity, ClipboardCheck, UserCog } from 'lucide-react';

type View = 'dashboard' | 'monitoring' | 'deployment' | 'schedule' | 'risk' | 'incidents' | 'users' | 'portal';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Lifted State: Manage workers globally so changes in Deployment reflect in Dashboard/Monitoring
  const [globalWorkers, setGlobalWorkers] = useState<Worker[]>(mockWorkers);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);

    // Set default view based on role
    if (loggedInUser.role === 'Technician') setCurrentView('portal');
    else if (loggedInUser.role === 'SafetyOfficer') setCurrentView('deployment');
    else setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setUser(null);
    setCurrentView('dashboard');
  };

  const handleUpdateWorkers = (updatedWorkers: Worker[]) => {
    setGlobalWorkers(updatedWorkers);
  };

  const renderContent = () => {
    if (!user) return <Login onLogin={handleLogin} />;

    switch (currentView) {
      case 'dashboard':
        return <Dashboard workers={globalWorkers} incidents={mockIncidents} />;
      case 'monitoring':
        // Note: SafetyMonitoring uses its own internal simulation for vitals, 
        // but we pass globalWorkers as the seed.
        return <SafetyMonitoring initialWorkers={globalWorkers} />;
      case 'deployment':
        return (
          <WorkforceDeployment 
            workers={globalWorkers} 
            onUpdateWorkers={handleUpdateWorkers}
            shifts={mockShifts} 
            userRole={user.role} 
          />
        );
      case 'schedule':
        return <ScheduleOptimizer workers={globalWorkers} shifts={mockShifts} />;
      case 'risk':
        return <RiskAssessment workers={globalWorkers} />;
      case 'incidents':
        return <IncidentAnalysis incidents={mockIncidents} />;
      case 'users':
        return <UserManagement />;
      case 'portal':
        // Pass the live globalWorkers state here instead of letting the component import mock data
        return <TechnicianPortal user={user} workers={globalWorkers} />;
      default:
        return <Dashboard workers={globalWorkers} incidents={mockIncidents} />;
    }
  };

  const NavItem = ({ view, label, icon: Icon, allowedRoles }: { view: View; label: string; icon: any; allowedRoles?: UserRole[] }) => {
    // If roles are specified, check if current user has permission
    if (allowedRoles && user && !allowedRoles.includes(user.role)) return null;

    return (
      <button
        onClick={() => {
          setCurrentView(view);
          setIsSidebarOpen(false);
        }}
        className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors ${
          currentView === view 
            ? 'bg-green-600 text-white shadow-md font-semibold' 
            : 'text-green-50 hover:bg-green-600 hover:text-white'
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </button>
    );
  };

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 flex font-sans text-slate-900">
      {/* Mobile Sidebar Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-20 lg:hidden"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 left-0 z-30 w-64 bg-green-700 text-white transform transition-transform duration-200 ease-in-out lg:translate-x-0 lg:static lg:h-screen flex flex-col shadow-xl
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-6 border-b border-green-600">
          <div className="flex items-center space-x-3 mb-2">
            <div className="w-10 h-10 bg-white rounded-full p-1 flex items-center justify-center">
               <Logo />
            </div>
            <span className="text-lg font-bold tracking-tight leading-tight">OLFU<br/>SafetyNet</span>
          </div>
          <p className="text-xs text-green-100">General Services Dept.</p>
        </div>

        <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
          {/* Dashboard - All admins and supervisors */}
          <NavItem view="dashboard" label="Overview" icon={LayoutDashboard} allowedRoles={['Admin', 'Supervisor', 'SafetyOfficer']} />

          {/* Deployment - Safety Officer (Checklist) & Supervisor (Assign) & Admin */}
          <NavItem view="deployment" label="Deployment & Compliance" icon={ClipboardCheck} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />

          {/* Monitoring - Admin, Safety, Supervisor */}
          <NavItem view="monitoring" label="Real-Time Protection" icon={Activity} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />

          {/* Schedule - Admin, Supervisor */}
          <NavItem view="schedule" label="Schedule Optimizer" icon={Users} allowedRoles={['Admin', 'Supervisor']} />

          {/* Risk - Admin, Safety */}
          <NavItem view="risk" label="Risk Assessment" icon={ShieldAlert} allowedRoles={['Admin', 'SafetyOfficer']} />

          {/* Incidents - Admin, Safety */}
          <NavItem view="incidents" label="Incident Logs" icon={FileWarning} allowedRoles={['Admin', 'SafetyOfficer']} />

          {/* User Mgmt - Admin Only */}
          <NavItem view="users" label="User Management" icon={UserCog} allowedRoles={['Admin']} />

          {/* Tech Portal - Technician Only */}
          <NavItem view="portal" label="My Assignment" icon={HardHat} allowedRoles={['Technician']} />
        </nav>

        <div className="p-4 border-t border-green-600">
          <div className="flex items-center gap-3 mb-4 px-2">
             <div className="w-8 h-8 rounded-full bg-green-600 border border-green-400 flex items-center justify-center text-xs font-bold text-white">
               {user.name.charAt(0)}
             </div>
             <div className="flex-1 overflow-hidden">
               <p className="text-sm font-medium text-white truncate">{user.name}</p>
               <p className="text-xs text-green-200 truncate">{user.role}</p>
             </div>
          </div>
          <button 
            onClick={handleLogout}
            className="w-full bg-green-600 hover:bg-green-500 text-white py-2 rounded-lg text-sm font-medium transition-colors flex items-center justify-center gap-2"
          >
            <LogOut size={16} /> Logout
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden bg-slate-50">
        {/* Top Header (Mobile) */}
        <div className="lg:hidden bg-white border-b border-slate-200 p-4 flex items-center justify-between shadow-sm">
          <div className="flex items-center space-x-3">
             <div className="w-8 h-8">
               <Logo />
             </div>
            <span className="font-bold text-green-700">OLFU SafetyNet</span>
          </div>
          <button onClick={() => setIsSidebarOpen(true)} className="text-slate-600">
            <Menu size={24} />
          </button>
        </div>

        {/* Scrollable Content Area */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8">
          <div className="max-w-7xl mx-auto">
             {renderContent()}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

