import IncidentAnalysis from './components/IncidentAnalysis';
import SafetyMonitoring from './components/SafetyMonitoring';
import WorkforceDeployment from './components/WorkforceDeployment';
import Login from './components/Login';
import UserManagement from './components/UserManagement';
import TechnicianPortal from './components/TechnicianPortal';
import Logo from './components/Logo';
import { mockWorkers, mockIncidents, mockShifts, mockUsers } from './mockData';
import { User, UserRole, Worker } from './types';
import { LayoutDashboard, Users, ShieldAlert, FileWarning, Menu, LogOut, HardHat, Activity, ClipboardCheck, UserCog } from 'lucide-react';

type View = 'dashboard' | 'monitoring' | 'deployment' | 'schedule' | 'risk' | 'incidents' | 'users' | 'portal';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Lifted State: Manage workers globally
  const [globalWorkers, setGlobalWorkers] = useState<Worker[]>(mockWorkers);

  // Lifted State: Manage users globally so added users persist
  const [globalUsers, setGlobalUsers] = useState<User[]>(mockUsers);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);

    // Set default view based on role
    if (loggedInUser.role === 'Technician') setCurrentView('portal');
    else if (loggedInUser.role === 'SafetyOfficer') setCurrentView('deployment');
    else setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setUser(null);
    setCurrentView('dashboard');
  };

  const handleUpdateWorkers = (updatedWorkers: Worker[]) => {
    setGlobalWorkers(updatedWorkers);
  };

  const handleAddWorker = (newWorker: Worker) => {
    setGlobalWorkers([...globalWorkers, newWorker]);
  };

  const handleAddUser = (newUser: User) => {
    setGlobalUsers([...globalUsers, newUser]);
  };

  const handleDeleteUser = (userId: string) => {
    setGlobalUsers(globalUsers.filter(u => u.id !== userId));
  };

  const renderContent = () => {
    if (!user) return <Login onLogin={handleLogin} users={globalUsers} />;

    switch (currentView) {
      case 'dashboard':
        return <Dashboard workers={globalWorkers} incidents={mockIncidents} />;
      case 'monitoring':
        return <SafetyMonitoring initialWorkers={globalWorkers} />;
      case 'deployment':
        return (
          <WorkforceDeployment 
            workers={globalWorkers} 
            onUpdateWorkers={handleUpdateWorkers}
            shifts={mockShifts} 
            userRole={user.role} 
          />
        );
      case 'schedule':
        return <ScheduleOptimizer workers={globalWorkers} shifts={mockShifts} />;
      case 'risk':
        return <RiskAssessment workers={globalWorkers} />;
      case 'incidents':
        return <IncidentAnalysis incidents={mockIncidents} />;
      case 'users':
        return (
          <UserManagement 
            users={globalUsers} 
            onAddUser={handleAddUser}
            onAddWorker={handleAddWorker}
            onDeleteUser={handleDeleteUser}
          />
        );
      case 'portal':
        return <TechnicianPortal user={user} workers={globalWorkers} />;
      default:
        return <Dashboard workers={globalWorkers} incidents={mockIncidents} />;
    }
  };

  const NavItem = ({ view, label, icon: Icon, allowedRoles }: { view: View; label: string; icon: any; allowedRoles?: UserRole[] }) => {
    if (allowedRoles && user && !allowedRoles.includes(user.role)) return null;

    return (
      <button
        onClick={() => {
          setCurrentView(view);
          setIsSidebarOpen(false);
        }}
        className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors ${
          currentView === view 
            ? 'bg-green-600 text-white shadow-md font-semibold' 
            : 'text-green-50 hover:bg-green-600 hover:text-white'
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </button>
    );
  };

  if (!user) {
    return <Login onLogin={handleLogin} users={globalUsers} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 flex font-sans text-slate-900">
      {/* Mobile Sidebar Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-20 lg:hidden"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 left-0 z-30 w-64 bg-green-700 text-white transform transition-transform duration-200 ease-in-out lg:translate-x-0 lg:static lg:h-screen flex flex-col shadow-xl
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-6 border-b border-green-600">
          <div className="flex items-center space-x-3 mb-2">
            <div className="w-10 h-10 bg-white rounded-full p-1 flex items-center justify-center">
               <Logo />
            </div>
            <span className="text-lg font-bold tracking-tight leading-tight">OLFU<br/>SafetyNet</span>
          </div>
          <p className="text-xs text-green-100">General Services Dept.</p>
        </div>

        <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
          {/* Dashboard - All admins and supervisors */}
          <NavItem view="dashboard" label="Overview" icon={LayoutDashboard} allowedRoles={['Admin', 'Supervisor', 'SafetyOfficer']} />

          {/* Deployment - Safety Officer (Checklist) & Supervisor (Assign) & Admin */}
          <NavItem view="deployment" label="Deployment & Compliance" icon={ClipboardCheck} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />

          {/* Monitoring - Admin, Safety, Supervisor */}
          <NavItem view="monitoring" label="Real-Time Protection" icon={Activity} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />

          {/* Schedule - Admin, Supervisor */}
          <NavItem view="schedule" label="Schedule Optimizer" icon={Users} allowedRoles={['Admin', 'Supervisor']} />

          {/* Risk - Admin, Safety */}
          <NavItem view="risk" label="Risk Assessment" icon={ShieldAlert} allowedRoles={['Admin', 'SafetyOfficer']} />

          {/* Incidents - Admin, Safety */}
          <NavItem view="incidents" label="Incident Logs" icon={FileWarning} allowedRoles={['Admin', 'SafetyOfficer']} />

          {/* User Mgmt - Admin Only */}
          <NavItem view="users" label="User Management" icon={UserCog} allowedRoles={['Admin']} />

          {/* Tech Portal - Technician Only */}
          <NavItem view="portal" label="My Assignment" icon={HardHat} allowedRoles={['Technician']} />
        </nav>

        <div className="p-4 border-t border-green-600">
          <div className="flex items-center gap-3 mb-4 px-2">
             <div className="w-8 h-8 rounded-full bg-green-600 border border-green-400 flex items-center justify-center text-xs font-bold text-white">
               {user.name.charAt(0)}
             </div>
             <div className="flex-1 overflow-hidden">
               <p className="text-sm font-medium text-white truncate">{user.name}</p>
               <p className="text-xs text-green-200 truncate">{user.role}</p>
             </div>
          </div>
          <button 
            onClick={handleLogout}
            className="w-full bg-green-600 hover:bg-green-500 text-white py-2 rounded-lg text-sm font-medium transition-colors flex items-center justify-center gap-2"
          >
            <LogOut size={16} /> Logout
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden bg-slate-50">
        {/* Top Header (Mobile) */}
        <div className="lg:hidden bg-white border-b border-slate-200 p-4 flex items-center justify-between shadow-sm">
          <div className="flex items-center space-x-3">
             <div className="w-8 h-8">
               <Logo />
             </div>
            <span className="font-bold text-green-700">OLFU SafetyNet</span>
          </div>
          <button onClick={() => setIsSidebarOpen(true)} className="text-slate-600">
            <Menu size={24} />
          </button>
        </div>

        {/* Scrollable Content Area */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8">
          <div className="max-w-7xl mx-auto">
             {renderContent()}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { User, UserRole, Worker, SkillLevel } from '../types';
import { UserCog, Trash2, Edit, X, Plus, Briefcase } from 'lucide-react';

interface Props {
  users: User[];
  onAddUser: (user: User) => void;
  onAddWorker: (worker: Worker) => void;
  onDeleteUser: (userId: string) => void;
}

const UserManagement: React.FC<Props> = ({ users, onAddUser, onAddWorker, onDeleteUser }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newUser, setNewUser] = useState({
    name: '',
    username: '',
    role: 'Technician' as UserRole,
    jobTitle: '' // New field for Worker Role/Job Title
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUser.name || !newUser.username) return;

    const timestamp = Date.now();
    const userId = `u${timestamp}`;
    const workerId = `w${timestamp}`;

    // 1. Create User
    const userToAdd: User = {
      id: userId,
      name: newUser.name,
      username: newUser.username.toLowerCase(),
      role: newUser.role,
      workerId: workerId // Link to the worker profile we are about to create
    };
    onAddUser(userToAdd);

    // 2. Create Linked Worker Profile
    // If the user is a Technician, Supervisor or Safety Officer, they act as a "Worker" in the system
    if (newUser.role !== 'Admin') {
      const workerToAdd: Worker = {
        id: workerId,
        name: newUser.name,
        role: newUser.jobTitle || newUser.role, // Use custom job title or fallback to system role
        skillLevel: SkillLevel.Junior, // Default for new adds
        certifications: [],
        productivityScore: 100, // Fresh start
        fatigueLevel: 0,
        currentLocation: 'General Assembly',
        vitals: { heartRate: 75, bodyTemp: 36.5, oxygenLevel: 98 },
        ppeCompliant: true,
        status: 'Active',
        safetyStatus: 'Pending'
      };
      onAddWorker(workerToAdd);
    }

    setIsModalOpen(false);
    setNewUser({ name: '', username: '', role: 'Technician', jobTitle: '' });
  };

  return (
    <div className="space-y-6 relative">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">User Management</h2>
          <p className="text-slate-500">Manage system access and assign roles.</p>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg text-sm font-medium flex items-center gap-2 transition-colors"
        >
          <Plus size={16} /> Add New User
        </button>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <table className="w-full text-left text-sm">
          <thead className="bg-slate-50 border-b border-slate-200">
            <tr>
              <th className="px-6 py-4 font-semibold text-slate-700">Name</th>
              <th className="px-6 py-4 font-semibold text-slate-700">Username</th>
              <th className="px-6 py-4 font-semibold text-slate-700">Role</th>
              <th className="px-6 py-4 font-semibold text-slate-700 text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {users.map(user => (
              <tr key={user.id} className="hover:bg-slate-50 transition-colors">
                <td className="px-6 py-4 font-medium text-slate-900 flex items-center gap-3">
                  <div className="w-8 h-8 rounded-full bg-slate-200 flex items-center justify-center text-slate-600 font-bold uppercase">
                    {user.name.charAt(0)}
                  </div>
                  {user.name}
                </td>
                <td className="px-6 py-4 text-slate-500 font-mono">{user.username}</td>
                <td className="px-6 py-4">
                  <span className={`px-2 py-1 rounded-full text-xs font-bold ${
                    user.role === 'Admin' ? 'bg-purple-100 text-purple-700' :
                    user.role === 'SafetyOfficer' ? 'bg-blue-100 text-blue-700' :
                    user.role === 'Supervisor' ? 'bg-indigo-100 text-indigo-700' :
                    'bg-green-100 text-green-700'
                  }`}>
                    {user.role}
                  </span>
                </td>
                <td className="px-6 py-4 text-right">
                  <div className="flex justify-end gap-2">
                    <button className="p-1 text-slate-400 hover:text-blue-600 transition-colors">
                      <Edit size={16} />
                    </button>
                    <button 
                      onClick={() => onDeleteUser(user.id)}
                      className="p-1 text-slate-400 hover:text-red-600 transition-colors"
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Add User Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in">
            <div className="bg-indigo-600 p-4 flex justify-between items-center text-white">
              <h3 className="font-bold flex items-center gap-2">
                <UserCog size={20} /> Add New User
              </h3>
              <button onClick={() => setIsModalOpen(false)} className="hover:bg-indigo-700 p-1 rounded">
                <X size={20} />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Full Name</label>
                <input 
                  type="text" 
                  required
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none"
                  placeholder="e.g. Juan Dela Cruz"
                  value={newUser.name}
                  onChange={(e) => setNewUser({...newUser, name: e.target.value})}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Username</label>
                <input 
                  type="text" 
                  required
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none"
                  placeholder="e.g. juan"
                  value={newUser.username}
                  onChange={(e) => setNewUser({...newUser, username: e.target.value})}
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Access Role</label>
                  <select 
                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none bg-white"
                    value={newUser.role}
                    onChange={(e) => setNewUser({...newUser, role: e.target.value as UserRole})}
                  >
                    <option value="Technician">Technician</option>
                    <option value="SafetyOfficer">Safety Officer</option>
                    <option value="Supervisor">Supervisor</option>
                    <option value="Admin">Admin</option>
                  </select>
                </div>

                {/* Job Title Input - Only show if not Admin, as admins usually don't need a worker profile */}
                {newUser.role !== 'Admin' && (
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                      <Briefcase size={14} /> Job Title
                    </label>
                    <input 
                      type="text"
                      className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none"
                      placeholder="e.g. Plumber"
                      value={newUser.jobTitle}
                      onChange={(e) => setNewUser({...newUser, jobTitle: e.target.value})}
                    />
                  </div>
                )}
              </div>

              {newUser.role !== 'Admin' && (
                <p className="text-xs text-slate-500 italic bg-slate-50 p-2 rounded">
                  * A corresponding Worker Profile will be automatically created for this user in the Deployment system.
                </p>
              )}

              <div className="pt-2 flex gap-3">
                <button 
                  type="button" 
                  onClick={() => setIsModalOpen(false)}
                  className="flex-1 bg-slate-100 text-slate-700 font-medium py-2.5 rounded-lg hover:bg-slate-200 transition-colors"
                >
                  Cancel
                </button>
                <button 
                  type="submit" 
                  className="flex-1 bg-indigo-600 text-white font-bold py-2.5 rounded-lg hover:bg-indigo-700 transition-colors shadow-md"
                >
                  Create User
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default UserManagement;

export enum SkillLevel {
  Junior = 'Junior',
  Mid = 'Mid',
  Senior = 'Senior',
  Expert = 'Expert'
}

export type UserRole = 'Admin' | 'SafetyOfficer' | 'Supervisor' | 'Staff';

export interface User {
  id: string;
  username: string;
  name: string;
  role: UserRole;
  avatar?: string;
  workerId?: string; // Link to worker profile if applicable
}

export type WorkerStatus = 'Active' | 'Warning' | 'Critical' | 'Offline';
export type SafetyClearanceStatus = 'Pending' | 'Cleared' | 'Rejected' | 'Deployed';

export interface Worker {
  id: string;
  name: string;
  role: string;
  skillLevel: SkillLevel;
  certifications: string[];
  productivityScore: number; // 0-100
  fatigueLevel: number; // 0-100 (Higher is more tired)
  lastIncidentDate?: string;

  // Real-time Monitoring Data
  currentLocation: string;
  vitals: {
    heartRate: number; // bpm
    bodyTemp: number; // celsius
    oxygenLevel: number; // %
  };
  ppeCompliant: boolean;
  status: WorkerStatus;

  // Workflow Status
  safetyStatus: SafetyClearanceStatus;
  assignedShiftId?: string;
}

export interface Shift {
  id: string;
  name: string;
  time: string;
  requiredRoles: string[];
  assignedWorkers: Worker[];
  riskScore: number; // Predicted by AI
}

export interface Incident {
  id: string;
  date: string;
  type: 'Near Miss' | 'Injury' | 'Equipment Failure' | 'Protocol Violation';
  severity: 'Low' | 'Medium' | 'High' | 'Critical';
  description: string;
  location: string;
}

export interface RiskPrediction {
  riskLevel: 'Low' | 'Medium' | 'High' | 'Critical';
  probability: number;
  factors: string[];
  mitigationStrategies: string[];
}

export interface OptimizationResult {
  schedules: {
    shiftName: string;
    assignments: {
      role: string;
      workerName: string;
      reason: string;
    }[];
  }[];
  improvementSummary: string;
}

export interface RealTimeAnalysis {
  alerts: {
    workerId: string;
    type: string;
    description: string;
    priority: 'High' | 'Medium' | 'Low';
  }[];
  zoneAnalysis: {
    zoneName: string;
    safetyStatus: string;
  }[];
  recommendedActions: string[];
}

export interface SafetyChecklist {
  ppeCheck: boolean;
  trainingValid: boolean;
  healthCheck: boolean;
  permitsActive: boolean;
}

import React, { useState } from 'react';
import Dashboard from './components/Dashboard';
import ScheduleOptimizer from './components/ScheduleOptimizer';
import RiskAssessment from './components/RiskAssessment';
import IncidentAnalysis from './components/IncidentAnalysis';
import SafetyMonitoring from './components/SafetyMonitoring';
import WorkforceDeployment from './components/WorkforceDeployment';
import Login from './components/Login';
import UserManagement from './components/UserManagement';
import TechnicianPortal from './components/TechnicianPortal';
import Logo from './components/Logo';
import { mockWorkers, mockIncidents, mockShifts, mockUsers } from './mockData';
import { User, UserRole, Worker } from './types';
import { LayoutDashboard, Users, ShieldAlert, FileWarning, Menu, LogOut, HardHat, Activity, ClipboardCheck, UserCog } from 'lucide-react';

type View = 'dashboard' | 'monitoring' | 'deployment' | 'schedule' | 'risk' | 'incidents' | 'users' | 'portal';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Lifted State: Manage workers globally
  const [globalWorkers, setGlobalWorkers] = useState<Worker[]>(mockWorkers);

  // Lifted State: Manage users globally so added users persist
  const [globalUsers, setGlobalUsers] = useState<User[]>(mockUsers);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);

    // Set default view based on role
    if (loggedInUser.role === 'Staff') setCurrentView('portal');
    else if (loggedInUser.role === 'SafetyOfficer') setCurrentView('deployment');
    else setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setUser(null);
    setCurrentView('dashboard');
  };

  const handleUpdateWorkers = (updatedWorkers: Worker[]) => {
    setGlobalWorkers(updatedWorkers);
  };

  const handleAddWorker = (newWorker: Worker) => {
    setGlobalWorkers([...globalWorkers, newWorker]);
  };

  const handleAddUser = (newUser: User) => {
    setGlobalUsers([...globalUsers, newUser]);
  };

  const handleEditUser = (updatedUser: User) => {
    setGlobalUsers(globalUsers.map(u => u.id === updatedUser.id ? updatedUser : u));

    // If the user name changed, update the linked worker profile as well for consistency
    if (updatedUser.workerId) {
       const updatedWorkers = globalWorkers.map(w => 
         w.id === updatedUser.workerId 
           ? { ...w, name: updatedUser.name } 
           : w
       );
       setGlobalWorkers(updatedWorkers);
    }
  };

  const handleDeleteUser = (userId: string) => {
    const userToDelete = globalUsers.find(u => u.id === userId);
    setGlobalUsers(globalUsers.filter(u => u.id !== userId));

    // Also remove the linked worker if applicable
    if (userToDelete && userToDelete.workerId) {
      setGlobalWorkers(globalWorkers.filter(w => w.id !== userToDelete.workerId));
    }
  };

  const renderContent = () => {
    if (!user) return <Login onLogin={handleLogin} users={globalUsers} />;

    switch (currentView) {
      case 'dashboard':
        return <Dashboard workers={globalWorkers} incidents={mockIncidents} />;
      case 'monitoring':
        return <SafetyMonitoring initialWorkers={globalWorkers} />;
      case 'deployment':
        return (
          <WorkforceDeployment 
            workers={globalWorkers} 
            onUpdateWorkers={handleUpdateWorkers}
            shifts={mockShifts} 
            userRole={user.role} 
          />
        );
      case 'schedule':
        return <ScheduleOptimizer workers={globalWorkers} shifts={mockShifts} />;
      case 'risk':
        return <RiskAssessment workers={globalWorkers} />;
      case 'incidents':
        return <IncidentAnalysis incidents={mockIncidents} />;
      case 'users':
        return (
          <UserManagement 
            users={globalUsers} 
            onAddUser={handleAddUser}
            onEditUser={handleEditUser}
            onAddWorker={handleAddWorker}
            onDeleteUser={handleDeleteUser}
          />
        );
      case 'portal':
        return <TechnicianPortal user={user} workers={globalWorkers} />;
      default:
        return <Dashboard workers={globalWorkers} incidents={mockIncidents} />;
    }
  };

  const NavItem = ({ view, label, icon: Icon, allowedRoles }: { view: View; label: string; icon: any; allowedRoles?: UserRole[] }) => {
    if (allowedRoles && user && !allowedRoles.includes(user.role)) return null;

    return (
      <button
        onClick={() => {
          setCurrentView(view);
          setIsSidebarOpen(false);
        }}
        className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors ${
          currentView === view 
            ? 'bg-green-600 text-white shadow-md font-semibold' 
            : 'text-green-50 hover:bg-green-600 hover:text-white'
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </button>
    );
  };

  if (!user) {
    return <Login onLogin={handleLogin} users={globalUsers} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 flex font-sans text-slate-900">
      {/* Mobile Sidebar Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-20 lg:hidden"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`
