{
  "name": "OLFU SafetyNet",
  "description": "Workforce deployment and safety monitoring system for Our Lady of Fatima University (Valenzuela Campus) General Services. Features real-time protection, hazard identification, and risk assessment.",
  "requestFramePermissions": []
