Here are the codes for the 5 files you need to create in the main folder (root) of your project.

### 1. `package.json`
This file tells the computer which libraries (React, Gemini AI, etc.) to download.

```json
{
  "name": "olfu-safetynet",
  "private": true,
  "version": "0.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "tsc && vite build",
    "preview": "vite preview"
  },
  "dependencies": {
    "@google/genai": "^0.1.0",
    "lucide-react": "^0.344.0",
    "react": "^18.2.0",
    "react-dom": "^18.2.0",
    "recharts": "^2.12.2"
  },
  "devDependencies": {
    "@types/react": "^18.2.64",
    "@types/react-dom": "^18.2.21",
    "@vitejs/plugin-react": "^4.2.1",
    "typescript": "^5.2.2",
    "vite": "^5.1.6"
  }
}
```

### 2. `vite.config.ts`
This configures the build tool and ensures your API Key works securely.

```typescript
import { defineConfig, loadEnv } from 'vite'
import react from '@vitejs/plugin-react'

// https://vitejs.dev/config/
export default defineConfig(({ mode }) => {
  const env = loadEnv(mode, (process as any).cwd(), '');
  return {
    plugins: [react()],
    define: {
      // This ensures process.env.API_KEY works in the browser
      'process.env.API_KEY': JSON.stringify(env.API_KEY)
    }
  }
})
```

### 3. `tsconfig.json`
This configures TypeScript (the programming language rules).

```json
{
  "compilerOptions": {
    "target": "ES2020",
    "useDefineForClassFields": true,
    "lib": ["ES2020", "DOM", "DOM.Iterable"],
    "module": "ESNext",
    "skipLibCheck": true,
    "moduleResolution": "bundler",
    "allowImportingTsExtensions": true,
    "resolveJsonModule": true,
    "isolatedModules": true,
    "noEmit": true,
    "jsx": "react-jsx",
    "strict": true,
    "noUnusedLocals": false,
    "noUnusedParameters": false,
    "noFallthroughCasesInSwitch": true
  },
  "include": ["src"],
  "references": [{ "path": "./tsconfig.node.json" }]
}
```

### 4. `tsconfig.node.json`
A helper file for TypeScript to understand the Vite configuration.

```json
{
  "compilerOptions": {
    "composite": true,
    "skipLibCheck": true,
    "module": "ESNext",
    "moduleResolution": "bundler",
    "allowSyntheticDefaultImports": true
  },
  "include": ["vite.config.ts"]
}
```

### 5. `index.html`
The main entry point of your website. I have cleaned this up to work perfectly on your local computer.

```html
<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>OLFU SafetyNet - Valenzuela Campus</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet">
    <style>
      body {
        font-family: 'Inter', sans-serif;
        background-color: #f8fafc;
      }
      ::-webkit-scrollbar {
        width: 8px;
        height: 8px;
      }
      ::-webkit-scrollbar-track {
        background: #f1f5f9;
      }
      ::-webkit-scrollbar-thumb {
        background: #cbd5e1;
        border-radius: 4px;
      }
      ::-webkit-scrollbar-thumb:hover {
        background: #94a3b8;
      }
      .animate-pulse-slow {
        animation: pulse 3s cubic-bezier(0.4, 0, 0.6, 1) infinite;
      }
    </style>
  </head>
  <body>
    <div id="root"></div>
    <script type="module" src="/src/main.tsx"></script>
  </body>
</html>

Here are the codes for the 5 files inside your `src` folder.

### 1. `src/main.tsx`
This connects your App to the HTML file.

```tsx
import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import './index.css'; // Ensure Tailwind directives are loaded

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);
```

### 2. `src/types.ts`
This defines the data structures (Users, Workers, Shifts, etc.) so TypeScript knows what to expect.

```typescript
export enum SkillLevel {
  Junior = 'Junior',
  Mid = 'Mid',
  Senior = 'Senior',
  Expert = 'Expert'
}

export type UserRole = 'Admin' | 'SafetyOfficer' | 'Supervisor' | 'Staff';

export interface User {
  id: string;
  username: string;
  name: string;
  role: UserRole;
  avatar?: string;
  workerId?: string; // Link to worker profile if applicable
}

export type WorkerStatus = 'Active' | 'Warning' | 'Critical' | 'Offline';
export type SafetyClearanceStatus = 'Pending' | 'Cleared' | 'Rejected' | 'Deployed';

export interface Worker {
  id: string;
  name: string;
  role: string;
  skillLevel: SkillLevel;
  certifications: string[];
  productivityScore: number; // 0-100
  fatigueLevel: number; // 0-100 (Higher is more tired)
  lastIncidentDate?: string;

  // Real-time Monitoring Data
  currentLocation: string;
  vitals: {
    heartRate: number; // bpm
    bodyTemp: number; // celsius
    oxygenLevel: number; // %
  };
  ppeCompliant: boolean;
  status: WorkerStatus;

  // Workflow Status
  safetyStatus: SafetyClearanceStatus;
  assignedShiftId?: string;
}

export interface Shift {
  id: string;
  name: string;
  time: string;
  requiredRoles: string[];
  assignedWorkers: Worker[];
  riskScore: number; // Predicted by AI
}

export interface Incident {
  id: string;
  date: string;
  type: 'Near Miss' | 'Injury' | 'Equipment Failure' | 'Protocol Violation';
  severity: 'Low' | 'Medium' | 'High' | 'Critical';
  description: string;
  location: string;
}

export interface RiskPrediction {
  riskLevel: 'Low' | 'Medium' | 'High' | 'Critical';
  probability: number;
  factors: string[];
  mitigationStrategies: string[];
}

export interface OptimizationResult {
  schedules: {
    shiftName: string;
    assignments: {
      role: string;
      workerName: string;
      reason: string;
    }[];
  }[];
  improvementSummary: string;
}

export interface RealTimeAnalysis {
  alerts: {
    workerId: string;
    type: string;
    description: string;
    priority: 'High' | 'Medium' | 'Low';
  }[];
  zoneAnalysis: {
    zoneName: string;
    safetyStatus: string;
  }[];
  recommendedActions: string[];
}

export interface SafetyChecklist {
  ppeCheck: boolean;
  trainingValid: boolean;
  healthCheck: boolean;
  permitsActive: boolean;
}
```

### 3. `src/mockData.ts`
This contains the sample users and workers so the app isn't empty when you first run it.

```typescript
