### 5. `src/App.tsx`
This is the main brain of your application. It controls which screen is shown (Dashboard, Monitoring, etc.).

```tsx
import React, { useState } from 'react';
import Dashboard from './components/Dashboard';
import ScheduleOptimizer from './components/ScheduleOptimizer';
import RiskAssessment from './components/RiskAssessment';
import IncidentAnalysis from './components/IncidentAnalysis';
import SafetyMonitoring from './components/SafetyMonitoring';
import WorkforceDeployment from './components/WorkforceDeployment';
import Login from './components/Login';
import UserManagement from './components/UserManagement';
import TechnicianPortal from './components/TechnicianPortal';
import Logo from './components/Logo';
import { mockWorkers, mockIncidents, mockShifts, mockUsers } from './mockData';
import { User, UserRole, Worker } from './types';
import { LayoutDashboard, Users, ShieldAlert, FileWarning, Menu, LogOut, HardHat, Activity, ClipboardCheck, UserCog } from 'lucide-react';

type View = 'dashboard' | 'monitoring' | 'deployment' | 'schedule' | 'risk' | 'incidents' | 'users' | 'portal';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Lifted State: Manage workers globally
  const [globalWorkers, setGlobalWorkers] = useState<Worker[]>(mockWorkers);

  // Lifted State: Manage users globally so added users persist
  const [globalUsers, setGlobalUsers] = useState<User[]>(mockUsers);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);

    // Set default view based on role
    if (loggedInUser.role === 'Staff') setCurrentView('portal');
    else if (loggedInUser.role === 'SafetyOfficer') setCurrentView('deployment');
    else setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setUser(null);
    setCurrentView('dashboard');
  };

  const handleUpdateWorkers = (updatedWorkers: Worker[]) => {
    setGlobalWorkers(updatedWorkers);
  };

  const handleAddWorker = (newWorker: Worker) => {
    setGlobalWorkers([...globalWorkers, newWorker]);
  };

  const handleAddUser = (newUser: User) => {
    setGlobalUsers([...globalUsers, newUser]);
  };

  const handleEditUser = (updatedUser: User) => {
    setGlobalUsers(globalUsers.map(u => u.id === updatedUser.id ? updatedUser : u));

    // If the user name changed, update the linked worker profile as well for consistency
    if (updatedUser.workerId) {
       const updatedWorkers = globalWorkers.map(w => 
         w.id === updatedUser.workerId 
           ? { ...w, name: updatedUser.name } 
           : w
       );
       setGlobalWorkers(updatedWorkers);
    }
  };

  const handleDeleteUser = (userId: string) => {
    const userToDelete = globalUsers.find(u => u.id === userId);
    setGlobalUsers(globalUsers.filter(u => u.id !== userId));

    // Also remove the linked worker if applicable
    if (userToDelete && userToDelete.workerId) {
      setGlobalWorkers(globalWorkers.filter(w => w.id !== userToDelete.workerId));
    }
  };

  const renderContent = () => {
    if (!user) return <Login onLogin={handleLogin} users={globalUsers} />;

    switch (currentView) {
      case 'dashboard':
        return <Dashboard workers={globalWorkers} incidents={mockIncidents} />;
      case 'monitoring':
        return <SafetyMonitoring initialWorkers={globalWorkers} />;
      case 'deployment':
        return (
          <WorkforceDeployment 
            workers={globalWorkers} 
            onUpdateWorkers={handleUpdateWorkers}
            shifts={mockShifts} 
            userRole={user.role} 
          />
        );
      case 'schedule':
        return <ScheduleOptimizer workers={globalWorkers} shifts={mockShifts} />;
      case 'risk':
        return <RiskAssessment workers={globalWorkers} />;
      case 'incidents':
        return <IncidentAnalysis incidents={mockIncidents} />;
      case 'users':
        return (
          <UserManagement 
            users={globalUsers} 
            onAddUser={handleAddUser}
            onEditUser={handleEditUser}
            onAddWorker={handleAddWorker}
            onDeleteUser={handleDeleteUser}
          />
        );
      case 'portal':
        return <TechnicianPortal user={user} workers={globalWorkers} />;
      default:
        return <Dashboard workers={globalWorkers} incidents={mockIncidents} />;
    }
  };

  const NavItem = ({ view, label, icon: Icon, allowedRoles }: { view: View; label: string; icon: any; allowedRoles?: UserRole[] }) => {
    if (allowedRoles && user && !allowedRoles.includes(user.role)) return null;

    return (
      <button
        onClick={() => {
          setCurrentView(view);
          setIsSidebarOpen(false);
        }}
        className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors ${
          currentView === view 
            ? 'bg-green-600 text-white shadow-md font-semibold' 
            : 'text-green-50 hover:bg-green-600 hover:text-white'
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </button>
    );
  };

  if (!user) {
    return <Login onLogin={handleLogin} users={globalUsers} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 flex font-sans text-slate-900">
      {/* Mobile Sidebar Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-20 lg:hidden"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
