          <div>
            <p className="text-sm text-slate-500">Avg Productivity</p>
            <p className="text-2xl font-bold text-slate-800">{stats.avgProd}%</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-center space-x-4">
          <div className="p-3 bg-orange-100 rounded-lg text-orange-600">
            <Activity size={24} />
          </div>
          <div>
            <p className="text-sm text-slate-500">Avg Fatigue Level</p>
            <p className={`text-2xl font-bold ${stats.avgFatigue > 40 ? 'text-orange-600' : 'text-green-600'}`}>
              {stats.avgFatigue}%
            </p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-center space-x-4">
          <div className="p-3 bg-red-100 rounded-lg text-red-600">
            <AlertTriangle size={24} />
          </div>
          <div>
            <p className="text-sm text-slate-500">High Severity Incidents</p>
            <p className="text-2xl font-bold text-slate-800">{stats.openRisks}</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-center space-x-4">
          <div className="p-3 bg-green-50 rounded-lg text-green-600">
            <Users size={24} />
          </div>
          <div>
            <p className="text-sm text-slate-500">Active Workforce</p>
            <p className="text-2xl font-bold text-slate-800">{stats.totalWorkers}</p>
          </div>
        </div>
      </div>

      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
