                  <h4 className="text-slate-800 font-semibold mb-3 flex items-center gap-2">
                    <AlertTriangle size={18} className="text-orange-500"/> Risk Factors
                  </h4>
                  <ul className="space-y-2">
                    {prediction.factors.map((factor, i) => (
                      <li key={i} className="flex items-start gap-2 text-slate-600 text-sm">
                        <span className="mt-1.5 w-1.5 h-1.5 bg-orange-400 rounded-full flex-shrink-0"></span>
                        {factor}
                      </li>
                    ))}
                  </ul>
                </div>

                <div>
                  <h4 className="text-slate-800 font-semibold mb-3 flex items-center gap-2">
                    <CheckCircle size={18} className="text-green-500"/> Mitigation Strategies
                  </h4>
                  <ul className="space-y-2">
                    {prediction.mitigationStrategies.map((strat, i) => (
