import { GoogleGenAI, Type, Schema } from "@google/genai";
import { Worker, Incident, Shift } from "../types";

// --- Configuration ---
// Try to get the key from environment, fallback to empty string if missing.
// This allows the app to load even without a key (triggers Mock Mode).
const API_KEY = process.env.API_KEY || ""; 

let ai: GoogleGenAI | null = null;
if (API_KEY) {
  try {
    ai = new GoogleGenAI({ apiKey: API_KEY });
  } catch (e) {
    console.warn("Gemini Client failed to initialize. Falling back to Mock Mode.");
  }
} else {
  console.log("No API Key detected. Running in Mock/Offline Mode.");
}

// --- Schemas (Kept for Reference) ---
const clearanceRecommendationSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    recommendation: { type: Type.STRING, enum: ['Approve', 'Reject'] },
    reasoning: { type: Type.STRING },
    flaggedRisks: { type: Type.ARRAY, items: { type: Type.STRING } }
  },
  required: ["recommendation", "reasoning", "flaggedRisks"]
};

const riskPredictionSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    riskLevel: { type: Type.STRING, enum: ['Low', 'Medium', 'High', 'Critical'] },
    probability: { type: Type.NUMBER, description: "Probability percentage 0-100" },
    factors: { type: Type.ARRAY, items: { type: Type.STRING } },
    mitigationStrategies: { type: Type.ARRAY, items: { type: Type.STRING } }
  },
  required: ["riskLevel", "probability", "factors", "mitigationStrategies"]
};

const scheduleOptimizationSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    schedules: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          shiftName: { type: Type.STRING },
          assignments: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                role: { type: Type.STRING },
                workerName: { type: Type.STRING },
                reason: { type: Type.STRING }
              },
              required: ["role", "workerName", "reason"]
            }
          }
        },
        required: ["shiftName", "assignments"]
      }
    },
    improvementSummary: { type: Type.STRING }
  },
  required: ["schedules", "improvementSummary"]
};

const incidentAnalysisSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    rootCauseAnalysis: { type: Type.STRING },
    trendIdentification: { type: Type.STRING },
    safetyRecommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
  },
  required: ["rootCauseAnalysis", "trendIdentification", "safetyRecommendations"]
};

const realTimeSafetySchema: Schema = {
  type: Type.OBJECT,
  properties: {
    alerts: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          workerId: { type: Type.STRING },
          type: { type: Type.STRING },
          description: { type: Type.STRING },
          priority: { type: Type.STRING, enum: ['High', 'Medium', 'Low'] }
        },
        required: ["workerId", "type", "description", "priority"]
      }
    },
    zoneAnalysis: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          zoneName: { type: Type.STRING },
          safetyStatus: { type: Type.STRING }
        },
        required: ["zoneName", "safetyStatus"]
      }
    },
    recommendedActions: { type: Type.ARRAY, items: { type: Type.STRING } }
  },
  required: ["alerts", "zoneAnalysis", "recommendedActions"]
};

// --- Mock Data Generators (Offline Mode) ---

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const getMockClearance = (worker: Worker) => {
  const isFatigued = worker.fatigueLevel > 30;
  return {
    recommendation: isFatigued ? "Reject" : "Approve",
    reasoning: isFatigued 
      ? `Worker fatigue is at ${worker.fatigueLevel}%, exceeding the 30% safety threshold.` 
      : "Worker is well-rested and all certifications are valid.",
    flaggedRisks: isFatigued ? ["High Fatigue", "Reduced Alertness"] : []
  };
};

const getMockRisk = () => ({
  riskLevel: "Medium",
  probability: 45,
  factors: ["High ambient temperature", "Equipment maintenance overdue", "New staff mix"],
  mitigationStrategies: ["Implement 15-min hydration breaks", "Verify equipment guards", "Pair juniors with seniors"]
});

const getMockSchedule = (shifts: Partial<Shift>[]) => ({
  improvementSummary: "Optimized for skill balance. High-fatigue workers moved to low-risk roles.",
  schedules: shifts.map(s => ({
    shiftName: s.name || "Shift",
    assignments: [
      { role: "Supervisor", workerName: "Tristan Cruz", reason: "High Leadership Score" },
      { role: "Safety Officer", workerName: "Delaney Ame", reason: "Certification Match" },
      { role: "Specialist", workerName: "Ethan Cloa", reason: "Expert Skill Level" }
    ]
  }))
});

const getMockIncidents = () => ({
  rootCauseAnalysis: "Analysis suggests a pattern of slips and trips in high-traffic zones during wet weather conditions.",
  trendIdentification: "Increasing frequency of minor injuries in the renovation wing.",
  safetyRecommendations: ["Install non-slip mats", "Review cleaning schedule", "Refresh PPE training"]
});

const getMockSafety = (workers: Worker[]) => {
  const critical = workers.filter(w => w.vitals.bodyTemp > 38 || w.vitals.heartRate > 120);
  return {
    alerts: critical.map(w => ({
      workerId: w.id,
      type: "Heat Stress Risk",
      description: `Elevated body temp (${w.vitals.bodyTemp}°C) detected.`,
      priority: "High"
    })),
    zoneAnalysis: [
      { zoneName: "St. Bonaventure Hall", safetyStatus: "Safe" },
      { zoneName: "Main Quadrangle", safetyStatus: critical.length > 0 ? "Caution" : "Safe" },
      { zoneName: "Machine Room", safetyStatus: "Safe" }
    ],
    recommendedActions: critical.length > 0 
      ? ["Dispatch medical unit to Quadrangle", "Enforce hydration break"] 
      : ["Continue routine monitoring"]
  };
};

// --- API Functions with Fallback ---

export const getClearanceRecommendation = async (worker: Worker): Promise<any> => {
  if (!ai) { await delay(1000); return getMockClearance(worker); }

  try {
    const workerContext = JSON.stringify({
      name: worker.name,
      fatigue: worker.fatigueLevel,
      lastIncident: worker.lastIncidentDate,
      vitals: worker.vitals,
      certs: worker.certifications,
      role: worker.role
    });

    const prompt = `
      Review this worker for safety clearance before deployment at OLFU Valenzuela Campus.
      Worker Data: ${workerContext}

      Rules:
      1. Reject if fatigue > 40%.
      2. Reject if body temp > 37.5.
      3. Flag if certificates are missing for role.
      4. Otherwise, Approve.
    `;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: clearanceRecommendationSchema,
        systemInstruction: "You are a strict OLFU Valenzuela Safety Officer assistant."
      }
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("API Error, using mock:", error);
    return getMockClearance(worker);
  }
};

export const analyzeRealTimeSafety = async (workers: Worker[]): Promise<any> => {
  if (!ai) { await delay(1500); return getMockSafety(workers); }

  try {
    const streamData = JSON.stringify(workers.map(w => ({
      name: w.name,
      id: w.id,
      location: w.currentLocation,
      vitals: w.vitals,
      ppe: w.ppeCompliant ? "Compliant" : "Violation",
      fatigue: w.fatigueLevel
    })));

    const prompt = `
      Act as an AI Safety Officer for Our Lady of Fatima University (Valenzuela Campus) General Services.
      Analyze this real-time data stream of workers.

      Data: ${streamData}

      Tasks:
      1. Identify immediate hazards (Heat stroke if Temp > 37.5C, Fatigue if level > 50, PPE violations).
      2. If a worker has abnormal vitals, flag them.
      3. Recommend immediate emergency responses suitable for a university campus setting.
    `;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: realTimeSafetySchema,
        systemInstruction: "You are a real-time safety monitoring system. Prioritize human safety and immediate response."
      }
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("API Error, using mock:", error);
    return getMockSafety(workers);
  }
};

export const predictOperationalRisk = async (
  context: string,
  workers: Worker[]
): Promise<any> => {
  if (!ai) { await delay(2000); return getMockRisk(); }

  try {
    const workerStats = workers.map(w => `${w.name} (Fatigue: ${w.fatigueLevel}%, Role: ${w.role})`).join(", ");

    const prompt = `
      Analyze the operational risk for the OLFU Valenzuela Campus context: "${context}".
      Considering these workers on site: ${workerStats}.
      Predict the risk level, probability, key risk factors, and mitigation strategies.
    `;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: riskPredictionSchema,
        systemInstruction: "You are an expert industrial safety officer and risk analyst."
      }
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("API Error, using mock:", error);
    return getMockRisk();
  }
};

export const optimizeSchedule = async (
  shifts: Partial<Shift>[],
  workers: Worker[]
): Promise<any> => {
  if (!ai) { await delay(2500); return getMockSchedule(shifts); }

  try {
    const shiftData = JSON.stringify(shifts.map(s => ({ name: s.name, requiredRoles: s.requiredRoles })));
    const workerData = JSON.stringify(workers.map(w => ({ 
      name: w.name, 
      role: w.role, 
      skillLevel: w.skillLevel, 
      productivity: w.productivityScore, 
      fatigue: w.fatigueLevel 
    })));

    const prompt = `
      Optimize the workforce deployment for OLFU Valenzuela General Services.
      Shifts Requirements: ${shiftData}
      Available Workforce: ${workerData}

      Goal:
      1. Ensure all required roles are filled.
      2. Minimize fatigue risk (avoid high fatigue workers on critical tasks).
      3. Balance skill levels (mix Senior/Junior where possible for mentorship, or keep Experts on critical paths).
      4. Maximize overall productivity score.
    `;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: scheduleOptimizationSchema,
        systemInstruction: "You are a logistics and workforce optimization expert."
      }
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("API Error, using mock:", error);
    return getMockSchedule(shifts);
  }
};

export const analyzeIncidents = async (incidents: Incident[]): Promise<any> => {
  if (!ai) { await delay(1500); return getMockIncidents(); }

  try {
    const incidentData = JSON.stringify(incidents);
    const prompt = `
      Analyze the following incident logs from the OLFU Valenzuela Campus:
      ${incidentData}

      Identify root causes, spotting any patterns in time, location, or type. Provide safety recommendations to prevent recurrence.
    `;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: incidentAnalysisSchema,
        systemInstruction: "You are a safety data analyst specializing in root cause analysis."
      }
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("API Error, using mock:", error);
    return getMockIncidents();
  }
};

