      config: { 
        responseMimeType: "application/json", 
        responseSchema: scheduleOptimizationSchema,
        systemInstruction: "You are a workforce logistics expert. Optimize for maximum productivity while ensuring safety compliance."
      }
    });
    return cleanAndParseJSON(response.text) || getMockSchedule(shifts);
  } catch (error) {
    return getMockSchedule(shifts);
  }
};

