export const generateShiftSummary = async (worker: Worker): Promise<any> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const workerData = `Name: ${worker.name}, Role: ${worker.role}, Location: ${worker.currentLocation}, Productivity: ${worker.productivityScore}%, Fatigue: ${worker.fatigueLevel}%, Heart Rate: ${worker.vitals.heartRate} bpm, Temp: ${worker.vitals.bodyTemp}C. PPE Compliant: ${worker.ppeCompliant}`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Generate a shift completion summary for: ${workerData}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: shiftSummarySchema,
        systemInstruction: "You are the Head of General Services at OLFU Valenzuela. Write a professional shift assessment for personnel records. Acknowledge their effort, safety compliance, and physical status."
      }
    });
    return cleanAndParseJSON(response.text);
  } catch (error) {
