          { inlineData: { mimeType: "image/jpeg", data: imageBase64 } },
          { text: "Analyze this worker for PPE compliance. Detect if they are wearing a Hard Hat, a High-Visibility Vest, and Safety Gloves. Return JSON result." }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: ppeDetectionSchema,
        systemInstruction: "You are an automated safety compliance inspector at OLFU. Be strict but accurate in identifying safety gear."
      }
    });
    return cleanAndParseJSON(response.text);
  } catch (error) {
    console.error("PPE Detection Error:", error);
    return { hasHardHat: false, hasHighVisVest: false, hasSafetyGloves: false, confidenceScore: 0, feedback: "Detection system error. Please retry." };
  }
};

