/**
 * Optimizes workforce deployment based on productivity scores and fatigue levels
 */
export const optimizeSchedule = async (shifts: Partial<Shift>[], workers: Worker[]): Promise<any> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const workerSummary = workers.map(w => `${w.name} (Productivity: ${w.productivityScore}%, Fatigue: ${w.fatigueLevel}%, Role: ${w.role})`).join("; ");
    const shiftSummary = shifts.map(s => `${s.name} needs: ${s.requiredRoles?.join(", ")}`).join("; ");

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Optimize workforce for productivity. Requirements: ${shiftSummary}. Available pool: ${workerSummary}. Rank workers by (Productivity - Fatigue/2).`,
      config: { 
        responseMimeType: "application/json", 
        responseSchema: scheduleOptimizationSchema,
        systemInstruction: "You are a workforce deployment expert. Maximize campus operational efficiency while ensuring no high-fatigue worker is assigned critical tasks."
      }
    });
    return cleanAndParseJSON(response.text);
  } catch (error) {
    console.error("Gemini Error:", error);
    return null;
  }
};

/**
 * Real-time safety analysis of live vitals data
 */
export const analyzeRealTimeSafety = async (workers: Worker[]): Promise<RealTimeAnalysis> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analyze vitals for ${workers.length} workers: ${JSON.stringify(workers.map(w => ({ id: w.id, hr: w.vitals.heartRate, temp: w.vitals.bodyTemp, status: w.status })))}`,
      config: { 
        responseMimeType: "application/json",
        responseSchema: realTimeSafetySchema,
        systemInstruction: "Return a JSON object with 'alerts' (array of {workerId, type, description, priority: 'High'|'Medium'|'Low'}), 'zoneAnalysis', and 'recommendedActions'."
      }
    });

    const parsed = cleanAndParseJSON(response.text);
    return parsed || { alerts: [], zoneAnalysis: [], recommendedActions: ["Maintain routine monitoring"] };
  } catch (error) {
    return { 
      alerts: workers.filter(w => w.status === 'Critical').map(w => ({ 
        workerId: w.id, 
        type: 'Health Alert', 
        description: 'Vitals outside normal range', 
        priority: 'High' as const
      })),
      zoneAnalysis: [],
      recommendedActions: ["Check on critical staff immediately"]
    };
  }
};

