  const workerProfile = workers.find(w => w.id === user.workerId) || workers[0];

  const handleStartShiftScan = async () => {
    setShowCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } });
