import React, { useState, useRef, useEffect } from 'react';
import { User, Worker } from '../types';
import { generateShiftSummary, analyzePPECompliance } from '../services/gemini';
import { 
  HardHat, MapPin, CheckCircle, Clock, FileText, 
  CalendarCheck, Printer, ArrowLeft, ShieldCheck, 
  TrendingUp, AlertTriangle, Loader2, Sparkles, 
  Download, Award, BookmarkCheck, Camera, Scan, X,
  Bluetooth, Cpu, RefreshCw
} from 'lucide-react';
import Logo from './Logo';

interface Props {
  user: User;
  workers: Worker[];
}

const TechnicianPortal: React.FC<Props> = ({ user, workers }) => {
  const [isCompleted, setIsCompleted] = useState(false);
  const [isLoadingSummary, setIsLoadingSummary] = useState(false);
  const [aiSummary, setAiSummary] = useState<{summary: string, performanceRating: string, safetyFeedback: string} | null>(null);

  // Hardware Sync State
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSync, setLastSync] = useState<string | null>(null);
  const [localVitals, setLocalVitals] = useState({ hr: 0, temp: 0 });

  // PPE Scan State
  const [showCamera, setShowCamera] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const [completionDate] = useState(new Date().toLocaleDateString('en-US', { 
    year: 'numeric', month: 'long', day: 'numeric' 
  }));
  const [completionTime] = useState(new Date().toLocaleTimeString());

  // Find the specific worker profile linked to this user
  const workerProfile = workers.find(w => w.id === user.workerId) || workers[0];

  useEffect(() => {
    setLocalVitals({ hr: workerProfile.vitals.heartRate, temp: workerProfile.vitals.bodyTemp });
  }, [workerProfile]);

  const handleHardwareSync = () => {
    setIsSyncing(true);
    // Simulating BLE Handshake and Data Retrieval
    setTimeout(() => {
      const newHr = 72 + Math.floor(Math.random() * 10);
      const newTemp = 36.5 + (Math.random() * 0.5);
      setLocalVitals({ hr: newHr, temp: Number(newTemp.toFixed(1)) });
      setLastSync(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }));
      setIsSyncing(false);
    }, 2000);
  };

  const handleStartShiftScan = async () => {
    setShowCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
    } catch (err) {
      console.error("Camera error:", err);
      alert("Please allow camera access for the safety scan.");
    }
  };

  const captureAndAnalyze = async () => {
    if (!videoRef.current || !canvasRef.current) return;
    setIsScanning(true);

    const context = canvasRef.current.getContext('2d');
    canvasRef.current.width = videoRef.current.videoWidth;
    canvasRef.current.height = videoRef.current.videoHeight;
    context?.drawImage(videoRef.current, 0, 0);

    const base64Image = canvasRef.current.toDataURL('image/jpeg').split(',')[1];

    try {
      const result = await analyzePPECompliance(base64Image);
      if (result.hasHardHat && result.hasHighVisVest) {
        workerProfile.ppeCompliant = true;
        alert("Safety Check Passed! PPE Verified.");
      } else {
        alert(`Safety Check Flagged: ${result.feedback}`);
      }
      closeCamera();
    } catch (e) {
      console.error(e);
      alert("Analysis failed. Please try again.");
    } finally {
      setIsScanning(false);
    }
  };

  const closeCamera = () => {
    const stream = videoRef.current?.srcObject as MediaStream;
    stream?.getTracks().forEach(track => track.stop());
    setShowCamera(false);
  };

  const handleCompleteShift = async () => {
    setIsLoadingSummary(true);
    setIsCompleted(true);
    try {
      // Update worker profile with latest local vitals before summary
      workerProfile.vitals.heartRate = localVitals.hr;
      workerProfile.vitals.bodyTemp = localVitals.temp;
      const summary = await generateShiftSummary(workerProfile);
      setAiSummary(summary);
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoadingSummary(false);
    }
  };

  const handlePrintPDF = () => {
    window.print();
  };

  const resetPortal = () => {
    setIsCompleted(false);
    setAiSummary(null);
  };

  return (
