                  className="flex-[2] py-4 bg-green-600 text-white rounded-2xl font-black flex items-center justify-center gap-2 shadow-lg shadow-green-900/40"
                >
                  {isScanning ? <Loader2 className="animate-spin" size={20} /> : <Camera size={20} />}
