import { 
  Heart, Thermometer, User, MapPin, ShieldCheck, 
  ShieldAlert, Activity, Radio, AlertTriangle, 
  Phone, Siren, Cpu, Settings, Zap, Clock, TrendingDown
} from 'lucide-react';

interface Props {
  initialWorkers: Worker[];
}

const SafetyMonitoring: React.FC<Props> = ({ initialWorkers }) => {
  const [workers, setWorkers] = useState<Worker[]>(initialWorkers);
  const [analysis, setAnalysis] = useState<any | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [lastScan, setLastScan] = useState<Date | null>(null);
  const [showHardwareGuide, setShowHardwareGuide] = useState(false);

  useEffect(() => {
    const interval = setInterval(() => {
      setWorkers(prev => prev.map(w => {
        // Natural fatigue accumulation over time (simulation)
        const fatigueIncr = Math.random() > 0.7 ? 1 : 0;
        const hrFluctuation = Math.floor(Math.random() * 5) - 2;
        const tempFluctuation = (Math.random() * 0.1) - 0.05;

        let newHr = w.vitals.heartRate + hrFluctuation;
        let newTemp = w.vitals.bodyTemp + tempFluctuation;
        let newFatigue = Math.min(100, w.fatigueLevel + fatigueIncr);

        if (newHr < 60) newHr = 60; if (newHr > 170) newHr = 170;
        if (newTemp < 36.2) newTemp = 36.2; if (newTemp > 39.5) newTemp = 39.5;

        let status: any = 'Active';
        if (newFatigue > 60 || newHr > 120) status = 'Warning';
        if (newFatigue > 85 || newTemp > 38.8) status = 'Critical';

        return {
          ...w,
          fatigueLevel: newFatigue,
          vitals: {
            ...w.vitals,
            heartRate: newHr,
            bodyTemp: Number(newTemp.toFixed(1))
          },
          status: status
        };
      }));
    }, 3000);

    return () => clearInterval(interval);
  }, []);

  const handleScan = async () => {
    setIsScanning(true);
    try {
      const result = await analyzeRealTimeSafety(workers);
      setAnalysis(result);
      setLastScan(new Date());
