                <div className="text-center">
                  <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">Fatigue</p>
                  <p className={`text-lg font-black ${worker.fatigueLevel > 70 ? 'text-red-600' : 'text-slate-800'}`}>
                    {worker.fatigueLevel}%
                  </p>
                </div>
              </div>

              {/* Fatigue Progress Bar */}
              <div className="mt-4">
                <div className="flex justify-between items-center mb-1">
                  <span className="text-[10px] font-bold text-slate-400 uppercase">Physical Reserve</span>
                  <span className="text-[10px] font-black text-slate-800">{100 - worker.fatigueLevel}%</span>
                </div>
                <div className="w-full h-1.5 bg-slate-100 rounded-full overflow-hidden">
                   <div 
                    className={`h-full transition-all duration-1000 ${worker.fatigueLevel > 80 ? 'bg-red-500' : worker.fatigueLevel > 50 ? 'bg-orange-500' : 'bg-green-500'}`} 
                    style={{ width: `${100 - worker.fatigueLevel}%` }}
                   ></div>
                </div>
              </div>

              {worker.status === 'Critical' && (
                <button className="w-full mt-4 bg-red-600 text-white py-2.5 rounded-xl font-black text-xs uppercase flex items-center justify-center gap-2 shadow-lg shadow-red-900/20">
                  <Phone size={16} /> EMERGENCY DISPATCH
                </button>
              )}
            </div>
          ))}
        </div>

        <div className="lg:col-span-1 space-y-4">
          <div className="bg-slate-900 text-white p-6 rounded-3xl shadow-2xl relative overflow-hidden border border-green-500/30">
            <h3 className="font-black text-lg mb-6 flex items-center gap-2">
              <ShieldAlert className="text-green-400" /> AI Diagnostic Hub
            </h3>

            {!analysis ? (
              <div className="py-12 text-center text-slate-500">
                <Radio className="mx-auto mb-4 animate-pulse" size={40} />
                <p className="text-xs font-bold uppercase tracking-widest">Awaiting Bio-Metric Handshake</p>
              </div>
            ) : (
              <div className="space-y-4 animate-fade-in">
                {analysis.alerts.map((alert: any, i: number) => (
                  <div key={i} className={`p-4 rounded-2xl border ${
                    alert.priority === 'High' ? 'bg-red-500/10 border-red-500/40' : 'bg-orange-500/10 border-orange-500/40'
                  }`}>
                    <div className="flex justify-between items-start mb-2">
                       <span className="text-[10px] font-black uppercase text-white/70">{alert.type}</span>
                       <span className={`text-[8px] font-black px-2 py-0.5 rounded-full border ${alert.priority === 'High' ? 'border-red-400' : 'border-orange-400'}`}>
                         {alert.priority}
                       </span>
                    </div>
                    <p className="text-sm font-medium leading-tight mb-3">{alert.description}</p>

                    {alert.fatigueDiagnostic && (
                      <div className="bg-black/40 p-3 rounded-xl border border-white/5">
                        <p className="text-[9px] font-bold text-green-400 uppercase tracking-tighter mb-1">Gemini Root Cause:</p>
                        <p className="text-xs text-white/90 font-bold">{alert.fatigueDiagnostic.primaryReason}</p>
                        <div className="mt-2 flex items-center gap-2">
                          <TrendingDown size={12} className="text-red-400" />
                          <span className="text-[9px] text-white/50">Stress Probability: {alert.fatigueDiagnostic.score}%</span>
                        </div>
                      </div>
                    )}
                  </div>
                ))}

                <div className="pt-4 border-t border-white/10">
                   <h4 className="text-[10px] font-black text-green-400 uppercase mb-3 flex items-center gap-2">
                     <Zap size={12} /> Response Directive
                   </h4>
                   <ul className="space-y-2">
                     {analysis.recommendedActions.map((action: string, i: number) => (
                       <li key={i} className="text-xs text-white/80 font-medium flex items-start gap-2">
                         <div className="w-4 h-4 rounded bg-white/10 flex items-center justify-center text-[9px] font-black shrink-0">{i+1}</div>
                         {action}
                       </li>
                     ))}
                   </ul>
                </div>
              </div>
            )}

            {lastScan && (
              <p className="mt-6 text-[10px] text-center font-bold text-white/30 uppercase tracking-widest flex items-center justify-center gap-1">
                <Clock size={10} /> Last Diagnostic: {lastScan.toLocaleTimeString()}
              </p>
            )}
          </div>

          <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
             <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest mb-4">Safety Zone Heatmap</h3>
             <div className="space-y-2">
                {analysis?.zoneAnalysis?.map((zone: any, i: number) => (
                  <div key={i} className="flex justify-between items-center p-3 bg-slate-50 rounded-xl border border-slate-100">
                    <div className="flex items-center gap-2">
                      <MapPin size={12} className="text-slate-400" />
                      <span className="text-xs font-bold text-slate-700">{zone.zoneName}</span>
                    </div>
                    <span className="text-[9px] font-black text-green-600 uppercase">{zone.safetyStatus}</span>
                  </div>
                ))}
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SafetyMonitoring;

import React, { useState, useRef, useEffect } from 'react';
import { User, Worker } from '../types';
import { generateShiftSummary, analyzePPECompliance } from '../services/gemini';
import { 
  HardHat, MapPin, CheckCircle, Clock, FileText, 
  CalendarCheck, Printer, ArrowLeft, ShieldCheck, 
  TrendingUp, AlertTriangle, Loader2, Sparkles, 
  Download, Award, BookmarkCheck, Camera, Scan, X,
  Bluetooth, Cpu, RefreshCw, Activity, Calendar
} from 'lucide-react';
import Logo from './Logo';

interface Props {
  user: User;
  workers: Worker[];
}

const TechnicianPortal: React.FC<Props> = ({ user, workers }) => {
  const [isCompleted, setIsCompleted] = useState(false);
  const [isLoadingSummary, setIsLoadingSummary] = useState(false);
  const [aiSummary, setAiSummary] = useState<{summary: string, performanceRating: string, safetyFeedback: string} | null>(null);

  // Hardware Sync State
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSync, setLastSync] = useState<string | null>(null);
  const [localVitals, setLocalVitals] = useState({ hr: 0, temp: 0 });

  // PPE Scan State
  const [showCamera, setShowCamera] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const [reportGeneratedAt, setReportGeneratedAt] = useState<string>('');
  const [reportDate, setReportDate] = useState<string>('');

  // Find the specific worker profile linked to this user
  const workerProfile = workers.find(w => w.id === user.workerId) || workers[0];

  useEffect(() => {
    setLocalVitals({ hr: workerProfile.vitals.heartRate, temp: workerProfile.vitals.bodyTemp });
  }, [workerProfile]);

  const handleHardwareSync = () => {
    setIsSyncing(true);
    setTimeout(() => {
      const newHr = 72 + Math.floor(Math.random() * 10);
      const newTemp = 36.5 + (Math.random() * 0.5);
      setLocalVitals({ hr: newHr, temp: Number(newTemp.toFixed(1)) });
      setLastSync(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }));
      setIsSyncing(false);
    }, 1500);
  };

  const handleStartShiftScan = async () => {
    setShowCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
    } catch (err) {
      console.error("Camera error:", err);
      alert("Please allow camera access for the safety scan.");
    }
  };

  const captureAndAnalyze = async () => {
    if (!videoRef.current || !canvasRef.current) return;
    setIsScanning(true);

    const context = canvasRef.current.getContext('2d');
    canvasRef.current.width = videoRef.current.videoWidth;
    canvasRef.current.height = videoRef.current.videoHeight;
    context?.drawImage(videoRef.current, 0, 0);

    const base64Image = canvasRef.current.toDataURL('image/jpeg').split(',')[1];

    try {
      const result = await analyzePPECompliance(base64Image);
      if (result.hasHardHat && result.hasHighVisVest) {
        workerProfile.ppeCompliant = true;
      } else {
        alert(`Safety Check Flagged: ${result.feedback}`);
      }
      closeCamera();
    } catch (e) {
      console.error(e);
      alert("Analysis failed. Please try again.");
    } finally {
      setIsScanning(false);
    }
  };

  const closeCamera = () => {
    const stream = videoRef.current?.srcObject as MediaStream;
    stream?.getTracks().forEach(track => track.stop());
    setShowCamera(false);
  };

  const handleCompleteShift = async () => {
    setIsLoadingSummary(true);
    setIsCompleted(true);

    const now = new Date();
    setReportGeneratedAt(now.toLocaleTimeString());
    setReportDate(now.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' }));

    try {
      workerProfile.vitals.heartRate = localVitals.hr;
      workerProfile.vitals.bodyTemp = localVitals.temp;
      const summary = await generateShiftSummary(workerProfile);
      setAiSummary(summary);
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoadingSummary(false);
    }
  };

  const handlePrintPDF = () => {
    window.print();
  };

  const resetPortal = () => {
    setIsCompleted(false);
    setAiSummary(null);
  };

  return (
    <div className="space-y-6">
      {/* PPE Scan Modal Overlay */}
      {showCamera && (
        <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center p-6 animate-fade-in">
          <div className="w-full max-w-md bg-slate-900 rounded-3xl overflow-hidden shadow-2xl relative border border-white/10">
            <video ref={videoRef} autoPlay playsInline className="w-full aspect-[3/4] object-cover" />
            <canvas ref={canvasRef} className="hidden" />
            <div className="absolute inset-0 border-[40px] border-black/40 pointer-events-none">
              <div className="w-full h-full border-2 border-dashed border-white/30 rounded-2xl"></div>
            </div>
            <div className="p-6 flex flex-col items-center gap-4 bg-slate-900/90 backdrop-blur-md">
              <h3 className="text-white font-black uppercase tracking-widest text-sm flex items-center gap-2">
                <Scan className="text-green-400" size={16} /> AI Safety Scan
              </h3>
              <div className="flex gap-4 w-full">
                 <button onClick={closeCamera} className="flex-1 py-4 bg-slate-800 text-white rounded-2xl font-bold flex items-center justify-center gap-2">
                  <X size={20} /> Cancel
                </button>
                <button onClick={captureAndAnalyze} disabled={isScanning} className="flex-[2] py-4 bg-green-600 text-white rounded-2xl font-black flex items-center justify-center gap-2 shadow-lg active:scale-95 disabled:opacity-50">
                  {isScanning ? <Loader2 className="animate-spin" size={20} /> : <Camera size={20} />}
                  {isScanning ? 'ANALYZING...' : 'VERIFY PPE'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 
          ENHANCED PRINTABLE PDF TEMPLATE (HIDDEN IN UI)
      */}
      <div className="hidden print:block p-12 bg-white text-slate-900 min-h-screen relative overflow-hidden font-sans">
