            <p className="text-xs font-mono font-bold">SN-V-2025-{workerProfile.id}-{Date.now().toString().slice(-4)}</p>
          </div>
        </div>

        <div className="bg-slate-900 text-white px-6 py-3 rounded mb-8 flex justify-between items-center shadow-lg">
