              </div>
              <p className="text-[10px] text-slate-500 font-medium italic">Authorized Valenzuela Campus Zone</p>
            </div>
          </div>

          <div className="bg-white p-6 rounded-2xl border-2 border-slate-100 flex flex-col justify-center">
             <div className="flex items-center gap-2 mb-4">
               <Activity className="text-green-700" size={16} />
               <h3 className="text-[9px] font-black text-slate-600 uppercase tracking-widest">Bio-Metric Metrics (Hardware Verified)</h3>
