import React, { useState } from 'react';
import Dashboard from './components/Dashboard';
import ScheduleOptimizer from './components/ScheduleOptimizer';
import RiskAssessment from './components/RiskAssessment';
import IncidentAnalysis from './components/IncidentAnalysis';
import SafetyMonitoring from './components/SafetyMonitoring';
import WorkforceDeployment from './components/WorkforceDeployment';
import Login from './components/Login';
import UserManagement from './components/UserManagement';
import TechnicianPortal from './components/TechnicianPortal';
import Logo from './components/Logo';
import { mockWorkers, mockIncidents, mockShifts, mockUsers } from './mockData';
import { User, UserRole, Worker, Shift } from './types';
import { LayoutDashboard, Users, ShieldAlert, FileWarning, Menu, LogOut, HardHat, Activity, ClipboardCheck, UserCog } from 'lucide-react';

type View = 'dashboard' | 'monitoring' | 'deployment' | 'schedule' | 'risk' | 'incidents' | 'users' | 'portal';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const [globalWorkers, setGlobalWorkers] = useState<Worker[]>(mockWorkers);
  const [globalUsers, setGlobalUsers] = useState<User[]>(mockUsers);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    if (loggedInUser.role === 'Staff') setCurrentView('portal');
    else if (loggedInUser.role === 'SafetyOfficer') setCurrentView('deployment');
    else setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setUser(null);
    setCurrentView('dashboard');
  };

  const handleUpdateWorkers = (updatedWorkers: Worker[]) => {
    setGlobalWorkers(updatedWorkers);
  };

  const handleAddWorker = (newWorker: Worker) => {
    setGlobalWorkers([...globalWorkers, newWorker]);
  };

  const handleAddUser = (newUser: User) => {
    setGlobalUsers([...globalUsers, newUser]);
  };

  const handleEditUser = (updatedUser: User) => {
    setGlobalUsers(globalUsers.map(u => u.id === updatedUser.id ? updatedUser : u));
    if (updatedUser.workerId) {
       const updatedWorkers = globalWorkers.map(w => 
         w.id === updatedUser.workerId ? { ...w, name: updatedUser.name } : w
       );
       setGlobalWorkers(updatedWorkers);
    }
  };

  const handleDeleteUser = (userId: string) => {
    const userToDelete = globalUsers.find(u => u.id === userId);
    setGlobalUsers(globalUsers.filter(u => u.id !== userId));
    if (userToDelete && userToDelete.workerId) {
      setGlobalWorkers(globalWorkers.filter(w => w.id !== userToDelete.workerId));
    }
  };

  const renderContent = () => {
    if (!user) return <Login onLogin={handleLogin} users={globalUsers} />;

    switch (currentView) {
      case 'dashboard':
        return <Dashboard workers={globalWorkers} incidents={mockIncidents} user={user} setView={setCurrentView} />;
      case 'monitoring':
        return <SafetyMonitoring initialWorkers={globalWorkers} />;
      case 'deployment':
        return (
          <WorkforceDeployment 
            workers={globalWorkers} 
            onUpdateWorkers={handleUpdateWorkers}
            shifts={mockShifts} 
            userRole={user.role} 
          />
        );
      case 'schedule':
        return <ScheduleOptimizer workers={globalWorkers} shifts={mockShifts} />;
      case 'risk':
        return <RiskAssessment workers={globalWorkers} />;
      case 'incidents':
        return <IncidentAnalysis incidents={mockIncidents} />;
      case 'users':
        return (
          <UserManagement 
            users={globalUsers} 
            onAddUser={handleAddUser}
            onEditUser={handleEditUser}
            onAddWorker={handleAddWorker}
            onDeleteUser={handleDeleteUser}
          />
        );
      case 'portal':
        return <TechnicianPortal user={user} workers={globalWorkers} shifts={mockShifts as Shift[]} />;
      default:
        return <Dashboard workers={globalWorkers} incidents={mockIncidents} user={user} setView={setCurrentView} />;
    }
  };

  const NavItem = ({ view, label, icon: Icon, allowedRoles }: { view: View; label: string; icon: any; allowedRoles?: UserRole[] }) => {
    if (allowedRoles && user && !allowedRoles.includes(user.role)) return null;

    return (
      <button
        onClick={() => {
          setCurrentView(view);
          setIsSidebarOpen(false);
        }}
        className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all duration-200 ${
          currentView === view 
            ? 'bg-white text-green-700 shadow-lg shadow-green-900/20 font-bold scale-[1.02]' 
            : 'text-green-50 hover:bg-green-600/50 hover:text-white'
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </button>
    );
  };

  if (!user) return <Login onLogin={handleLogin} users={globalUsers} />;

  return (
    <div className="min-h-screen bg-slate-50 flex font-sans text-slate-900">
      {isSidebarOpen && <div className="fixed inset-0 bg-black/50 z-20 lg:hidden" onClick={() => setIsSidebarOpen(false)} />}

      <aside className={`
        fixed inset-y-0 left-0 z-30 w-72 bg-gradient-to-b from-green-700 to-green-800 text-white transform transition-transform duration-300 ease-in-out lg:translate-x-0 lg:static lg:h-screen flex flex-col shadow-2xl
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-8 border-b border-green-600/50">
          <div className="flex items-center space-x-4 mb-3">
            <div className="w-12 h-12 bg-white rounded-2xl p-1.5 flex items-center justify-center shadow-lg transform -rotate-3">
               <Logo />
            </div>
            <div>
              <span className="text-xl font-black tracking-tighter leading-none block">OLFU</span>
              <span className="text-sm font-bold tracking-widest text-green-100 block opacity-70">SAFETYNET</span>
            </div>
          </div>
          <p className="text-[10px] font-bold text-green-200/60 uppercase tracking-widest">Valenzuela Main Campus</p>
        </div>

        <nav className="flex-1 p-6 space-y-3 overflow-y-auto">
          <NavItem view="dashboard" label="Overview" icon={LayoutDashboard} allowedRoles={['Admin', 'Supervisor', 'SafetyOfficer']} />
          <NavItem view="deployment" label="Deployment" icon={ClipboardCheck} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />
          <NavItem view="monitoring" label="Real-Time Protection" icon={Activity} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />
          <NavItem view="schedule" label="Productivity Engine" icon={Users} allowedRoles={['Admin', 'Supervisor']} />
          <NavItem view="risk" label="Risk Assessment" icon={ShieldAlert} allowedRoles={['Admin', 'SafetyOfficer']} />
          <NavItem view="incidents" label="Incident Logs" icon={FileWarning} allowedRoles={['Admin', 'SafetyOfficer']} />
          <NavItem view="users" label="User Management" icon={UserCog} allowedRoles={['Admin']} />
          <NavItem view="portal" label="My Assignment" icon={HardHat} allowedRoles={['Staff']} />
        </nav>

        <div className="p-6 border-t border-green-600/50 bg-green-900/20">
          <div className="flex items-center gap-3 mb-6 px-2">
             <div className="w-10 h-10 rounded-xl bg-white/10 backdrop-blur-md border border-white/20 flex items-center justify-center text-sm font-black text-white">
               {user.name.charAt(0)}
             </div>
             <div className="flex-1 overflow-hidden">
               <p className="text-sm font-bold text-white truncate">{user.name}</p>
               <p className="text-[10px] font-bold text-green-300 uppercase truncate tracking-wider">{user.role}</p>
             </div>
          </div>
          <button onClick={handleLogout} className="w-full bg-red-500/10 hover:bg-red-500/20 text-red-200 border border-red-500/20 py-2.5 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-2">
            <LogOut size={14} /> Log Out
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden bg-slate-50">
        <div className="lg:hidden bg-white border-b border-slate-200 p-4 flex items-center justify-between shadow-sm">
          <div className="flex items-center space-x-3">
             <div className="w-8 h-8"><Logo /></div>
            <span className="font-black text-green-700 tracking-tighter">OLFU SAFETYNET</span>
          </div>
          <button onClick={() => setIsSidebarOpen(true)} className="text-slate-600"><Menu size={24} /></button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-10">
          <div className="max-w-6xl mx-auto">{renderContent()}</div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { User, Worker, Shift } from '../types';
import { generateShiftSummary, analyzePPECompliance } from '../services/gemini';
import { 
  HardHat, MapPin, CheckCircle, Clock, FileText, 
  CalendarCheck, Printer, ArrowLeft, ShieldCheck, 
  TrendingUp, AlertTriangle, Loader2, Sparkles, 
  Download, Award, BookmarkCheck, Camera, Scan, X,
  Bluetooth, Cpu, RefreshCw, Activity, Calendar
} from 'lucide-react';
import Logo from './Logo';

interface Props {
  user: User;
  workers: Worker[];
  shifts: Shift[];
}

const TechnicianPortal: React.FC<Props> = ({ user, workers, shifts }) => {
  const [isCompleted, setIsCompleted] = useState(false);
  const [isLoadingSummary, setIsLoadingSummary] = useState(false);
  const [aiSummary, setAiSummary] = useState<{summary: string, performanceRating: string, safetyFeedback: string} | null>(null);

  // Hardware Sync State
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSync, setLastSync] = useState<string | null>(null);
  const [localVitals, setLocalVitals] = useState({ hr: 0, temp: 0 });

  // PPE Scan State
  const [showCamera, setShowCamera] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const [reportGeneratedAt, setReportGeneratedAt] = useState<string>('');
  const [reportDate, setReportDate] = useState<string>('');

  // Find the specific worker profile linked to this user
  const workerProfile = workers.find(w => w.id === user.workerId) || workers[0];

  // Logic to find the current active shift
  const assignedShift = shifts.find(s => s.name === workerProfile.currentLocation) || shifts[0];

  useEffect(() => {
    setLocalVitals({ hr: workerProfile.vitals.heartRate, temp: workerProfile.vitals.bodyTemp });
  }, [workerProfile]);

  const handleHardwareSync = () => {
    setIsSyncing(true);
    setTimeout(() => {
      const newHr = 72 + Math.floor(Math.random() * 10);
      const newTemp = 36.5 + (Math.random() * 0.5);
      setLocalVitals({ hr: newHr, temp: Number(newTemp.toFixed(1)) });
      setLastSync(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }));
      setIsSyncing(false);
    }, 1500);
  };

  const handleStartShiftScan = async () => {
    setShowCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
    } catch (err) {
      console.error("Camera error:", err);
      alert("Please allow camera access for the safety scan.");
    }
  };

  const captureAndAnalyze = async () => {
    if (!videoRef.current || !canvasRef.current) return;
    setIsScanning(true);

    const context = canvasRef.current.getContext('2d');
    canvasRef.current.width = videoRef.current.videoWidth;
    canvasRef.current.height = videoRef.current.videoHeight;
    context?.drawImage(videoRef.current, 0, 0);

    const base64Image = canvasRef.current.toDataURL('image/jpeg').split(',')[1];

    try {
      const result = await analyzePPECompliance(base64Image);
      if (result.hasHardHat && result.hasHighVisVest) {
        workerProfile.ppeCompliant = true;
      } else {
        alert(`Safety Check Flagged: ${result.feedback}`);
      }
      closeCamera();
    } catch (e) {
      console.error(e);
      alert("Analysis failed. Please try again.");
    } finally {
      setIsScanning(false);
    }
  };

  const closeCamera = () => {
    const stream = videoRef.current?.srcObject as MediaStream;
    stream?.getTracks().forEach(track => track.stop());
    setShowCamera(false);
  };

  const handleCompleteShift = async () => {
    setIsLoadingSummary(true);
    setIsCompleted(true);

    const now = new Date();
    setReportGeneratedAt(now.toLocaleTimeString());
    setReportDate(now.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' }));

    try {
      workerProfile.vitals.heartRate = localVitals.hr;
      workerProfile.vitals.bodyTemp = localVitals.temp;
      const summary = await generateShiftSummary(workerProfile);
      setAiSummary(summary);
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoadingSummary(false);
    }
  };

  const handlePrintPDF = () => {
    window.print();
  };

  const resetPortal = () => {
    setIsCompleted(false);
    setAiSummary(null);
  };

  return (
    <div className="space-y-6">
      {/* PPE Scan Modal Overlay */}
      {showCamera && (
        <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center p-6 animate-fade-in">
          <div className="w-full max-w-md bg-slate-900 rounded-3xl overflow-hidden shadow-2xl relative border border-white/10">
            <video ref={videoRef} autoPlay playsInline className="w-full aspect-[3/4] object-cover" />
            <canvas ref={canvasRef} className="hidden" />
            <div className="absolute inset-0 border-[40px] border-black/40 pointer-events-none">
              <div className="w-full h-full border-2 border-dashed border-white/30 rounded-2xl"></div>
            </div>
            <div className="p-6 flex flex-col items-center gap-4 bg-slate-900/90 backdrop-blur-md">
              <h3 className="text-white font-black uppercase tracking-widest text-sm flex items-center gap-2">
                <Scan className="text-green-400" size={16} /> AI Safety Scan
              </h3>
              <div className="flex gap-4 w-full">
                 <button onClick={closeCamera} className="flex-1 py-4 bg-slate-800 text-white rounded-2xl font-bold flex items-center justify-center gap-2">
                  <X size={20} /> Cancel
                </button>
                <button onClick={captureAndAnalyze} disabled={isScanning} className="flex-[2] py-4 bg-green-600 text-white rounded-2xl font-black flex items-center justify-center gap-2 shadow-lg active:scale-95 disabled:opacity-50">
                  {isScanning ? <Loader2 className="animate-spin" size={20} /> : <Camera size={20} />}
                  {isScanning ? 'ANALYZING...' : 'VERIFY PPE'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 
          ENHANCED PRINTABLE PDF TEMPLATE (HIDDEN IN UI)
      */}
      <div className="hidden print:block p-12 bg-white text-slate-900 min-h-screen relative overflow-hidden font-sans">
        <div className="flex justify-between items-start border-b-4 border-green-800 pb-6 mb-8 relative">
          <div className="flex items-center gap-6">
            <div className="w-20 h-20"><Logo /></div>
            <div>
              <h1 className="text-2xl font-black text-green-900 tracking-tight leading-tight">Our Lady of Fatima University</h1>
              <p className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-1">General Services Department</p>
              <p className="text-[10px] text-green-700 font-semibold italic">Valenzuela Main Campus • SafetyNet Compliance Report</p>
            </div>
          </div>
          <div className="text-right">
            <p className="text-[8px] font-bold text-slate-400 uppercase tracking-[0.3em]">Official Document ID</p>
            <p className="text-xs font-mono font-bold">SN-V-2025-{workerProfile.id}-{Date.now().toString().slice(-4)}</p>
          </div>
        </div>

        <div className="bg-slate-900 text-white px-6 py-3 rounded mb-8 flex justify-between items-center shadow-lg">
          <h2 className="text-sm font-black uppercase tracking-[0.2em]">Deployment Completion & Bio-Metric Record</h2>
          <div className="text-right">
            <p className="text-[8px] opacity-60 font-bold uppercase">Report Generated On</p>
            <p className="text-[10px] font-bold">{reportDate} | {reportGeneratedAt}</p>
