        ) : (
          /* Completion & Report View */
          <div className="bg-white rounded-3xl shadow-2xl border-2 border-green-500 p-8 flex flex-col items-center justify-center text-center space-y-6 animate-fade-in relative overflow-hidden group">
             {isLoadingSummary && (
               <div className="absolute inset-0 bg-white/80 backdrop-blur-sm z-50 flex flex-col items-center justify-center">
                 <Loader2 className="animate-spin text-green-600 mb-4" size={48} />
                 <p className="font-black text-slate-800 uppercase tracking-widest text-sm">Generating OLFU Report...</p>
               </div>
             )}

             <div className="w-24 h-24 bg-green-50 text-green-600 rounded-full flex items-center justify-center border-4 border-green-100 shadow-inner z-10 scale-110 mb-4">
                <ShieldCheck size={52} />
             </div>

             <div className="z-10">
               <h3 className="text-3xl font-black text-slate-800 tracking-tighter">Shift Logged Successfully</h3>
               <p className="text-slate-500 mt-3 px-6 font-medium text-sm">
                 Your operational summary and bio-metric telemetry have been synchronized with the OLFU SafetyNet database.
               </p>
             </div>

             <div className="grid grid-cols-2 gap-4 w-full bg-slate-50 p-6 rounded-2xl border border-slate-100 z-10">
                <div className="text-center">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-1">Final HR</p>
                  <p className="text-xl font-black text-slate-800">{localVitals.hr} <span className="text-[10px]">BPM</span></p>
                </div>
                <div className="text-center border-l border-slate-200">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-1">Final Temp</p>
                  <p className="text-xl font-black text-slate-800">{localVitals.temp}°C</p>
                </div>
             </div>

             <div className="flex flex-col w-full gap-3 z-10">
               <button 
                 onClick={handlePrintPDF}
                 className="w-full bg-green-700 hover:bg-green-800 text-white font-black py-5 rounded-2xl flex items-center justify-center gap-3 shadow-xl shadow-green-900/10 transition-all hover:scale-[1.02] active:scale-95 text-lg"
               >
                 <Download size={22} /> Export Official PDF Report
               </button>
               <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.2em] mt-2">
                 Compliance Document ID: SN-GS-{workerProfile.id}-{Date.now().toString().slice(-4)}
               </p>
             </div>
          </div>
        )}

        {/* Real-time Insight Side Column */}
        <div className="space-y-6 print:hidden">
          <div className="bg-white rounded-3xl shadow-sm border border-slate-200 p-8 transition-all hover:shadow-md">
            <h3 className="font-black text-slate-800 mb-6 flex items-center gap-3 border-b pb-4 text-sm uppercase tracking-widest">
               <Cpu className="text-blue-600" /> Bio-Metric Live Stream
            </h3>
            <div className="grid grid-cols-2 gap-6">
              <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100 text-center group hover:bg-white transition-all">
                 <p className="text-[10px] font-black text-slate-400 uppercase mb-2 group-hover:text-blue-600">Heart Rate</p>
                 <div className="flex items-center justify-center gap-2">
                    <span className="text-3xl font-black text-slate-800">{localVitals.hr}</span>
                    <span className="text-[10px] font-bold text-slate-400 uppercase">BPM</span>
                 </div>
              </div>
              <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100 text-center group hover:bg-white transition-all">
                 <p className="text-[10px] font-black text-slate-400 uppercase mb-2 group-hover:text-red-600">Body Temp</p>
                 <div className="flex items-center justify-center gap-2">
                    <span className="text-3xl font-black text-slate-800">{localVitals.temp}</span>
                    <span className="text-[10px] font-bold text-slate-400 uppercase">°C</span>
                 </div>
              </div>
            </div>
            {lastSync && (
              <p className="text-[10px] text-blue-600 font-black text-center mt-4 uppercase tracking-[0.2em] flex items-center justify-center gap-2">
                <RefreshCw size={12} className="animate-spin-slow" /> SYNCED: {lastSync}
              </p>
            )}
          </div>

          <div className="bg-white rounded-3xl shadow-sm border border-slate-200 p-8 transition-all hover:shadow-md">
            <h3 className="font-black text-slate-800 mb-6 flex items-center gap-3 border-b pb-4 text-sm uppercase tracking-widest">
               <BookmarkCheck className="text-indigo-600" /> Operational Log
            </h3>
            <ul className="space-y-4">
               <li className="flex items-center justify-between p-4 rounded-2xl bg-slate-50 border border-slate-100 group transition-all hover:bg-indigo-50">
                 <div className="flex items-center gap-3">
                   <Activity size={16} className="text-indigo-400" />
                   <span className="text-xs font-bold text-slate-700">Bio-Telemetry</span>
                 </div>
                 <span className="text-[10px] font-black text-green-600 uppercase">Active</span>
               </li>
               <li className="flex items-center justify-between p-4 rounded-2xl bg-slate-50 border border-slate-100 group transition-all hover:bg-indigo-50">
                 <div className="flex items-center gap-3">
                   <Calendar size={16} className="text-indigo-400" />
                   <span className="text-xs font-bold text-slate-700">Shift Date</span>
                 </div>
                 <span className="text-[10px] font-black text-slate-600 uppercase">{new Date().toLocaleDateString('en-GB')}</span>
               </li>
               <li className="flex items-center justify-between p-4 rounded-2xl bg-slate-50 border border-slate-100 group transition-all hover:bg-indigo-50">
                 <div className="flex items-center gap-3">
                   <MapPin size={16} className="text-indigo-400" />
                   <span className="text-xs font-bold text-slate-700">Zone Lock</span>
                 </div>
                 <span className="text-[10px] font-black text-indigo-600 uppercase truncate max-w-[80px]">{workerProfile.currentLocation.split(' ')[0]}</span>
               </li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TechnicianPortal;

export enum SkillLevel {
  Junior = 'Junior',
  Mid = 'Mid',
  Senior = 'Senior',
  Expert = 'Expert'
}

export type UserRole = 'Admin' | 'SafetyOfficer' | 'Supervisor' | 'Staff';

export interface User {
  id: string;
  username: string;
  name: string;
  role: UserRole;
  avatar?: string;
  workerId?: string; // Link to worker profile if applicable
}

export type WorkerStatus = 'Active' | 'Warning' | 'Critical' | 'Offline';
export type SafetyClearanceStatus = 'Pending' | 'Cleared' | 'Rejected' | 'Deployed';

export interface Worker {
  id: string;
  name: string;
  role: string;
  skillLevel: SkillLevel;
  certifications: string[];
  productivityScore: number; // 0-100
  fatigueLevel: number; // 0-100 (Higher is more tired)
  lastIncidentDate?: string;

  // Real-time Monitoring Data
  currentLocation: string;
  vitals: {
    heartRate: number; // bpm
    bodyTemp: number; // celsius
    oxygenLevel: number; // %
  };
  ppeCompliant: boolean;
  status: WorkerStatus;

  // Workflow Status
  safetyStatus: SafetyClearanceStatus;
  assignedShiftId?: string;
}

export interface Shift {
  id: string;
  name: string;
  time: string;
  requiredRoles: string[];
  assignedWorkers: Worker[];
  riskScore: number; // Predicted by AI
}

export interface ShiftReport {
  id: string;
  workerId: string;
  workerName: string;
  date: string;
  time: string;
  shiftName: string;
  location: string;
  finalVitals: {
    hr: number;
    temp: number;
  };
  aiSummary?: string;
  performanceRating?: string;
}

export interface Incident {
  id: string;
  date: string;
  type: 'Near Miss' | 'Injury' | 'Equipment Failure' | 'Protocol Violation';
  severity: 'Low' | 'Medium' | 'High' | 'Critical';
  description: string;
  location: string;
}

export interface RiskPrediction {
  riskLevel: 'Low' | 'Medium' | 'High' | 'Critical';
  probability: number;
  factors: string[];
  mitigationStrategies: string[];
}

export interface OptimizationResult {
  schedules: {
    shiftName: string;
    assignments: {
      role: string;
      workerName: string;
      reason: string;
    }[];
  }[];
  improvementSummary: string;
}

export interface RealTimeAnalysis {
  alerts: {
    workerId: string;
    type: string;
    description: string;
    priority: 'High' | 'Medium' | 'Low';
    fatigueDiagnostic?: {
      score: number;
      primaryReason: string;
      isHeartRateDriven: boolean;
    };
  }[];
  zoneAnalysis: {
    zoneName: string;
    safetyStatus: string;
  }[];
  recommendedActions: string[];
}

export interface SafetyChecklist {
  ppeCheck: boolean;
  trainingValid: boolean;
  healthCheck: boolean;
  permitsActive: boolean;
}

import React, { useState } from 'react';
import Dashboard from './components/Dashboard';
import ScheduleOptimizer from './components/ScheduleOptimizer';
import RiskAssessment from './components/RiskAssessment';
import IncidentAnalysis from './components/IncidentAnalysis';
import SafetyMonitoring from './components/SafetyMonitoring';
import WorkforceDeployment from './components/WorkforceDeployment';
import Login from './components/Login';
import UserManagement from './components/UserManagement';
import TechnicianPortal from './components/TechnicianPortal';
import Logo from './components/Logo';
import { mockWorkers, mockIncidents, mockShifts, mockUsers } from './mockData';
import { User, UserRole, Worker, Shift, ShiftReport } from './types';
import { LayoutDashboard, Users, ShieldAlert, FileWarning, Menu, LogOut, HardHat, Activity, ClipboardCheck, UserCog } from 'lucide-react';

type View = 'dashboard' | 'monitoring' | 'deployment' | 'schedule' | 'risk' | 'incidents' | 'users' | 'portal';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const [globalWorkers, setGlobalWorkers] = useState<Worker[]>(mockWorkers);
  const [globalUsers, setGlobalUsers] = useState<User[]>(mockUsers);
  const [shiftReports, setShiftReports] = useState<ShiftReport[]>([]);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    if (loggedInUser.role === 'Staff') setCurrentView('portal');
    else if (loggedInUser.role === 'SafetyOfficer') setCurrentView('deployment');
    else setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setUser(null);
    setCurrentView('dashboard');
  };

  const handleUpdateWorkers = (updatedWorkers: Worker[]) => {
    setGlobalWorkers(updatedWorkers);
  };

  const handleAddWorker = (newWorker: Worker) => {
    setGlobalWorkers([...globalWorkers, newWorker]);
  };

  const handleAddUser = (newUser: User) => {
    setGlobalUsers([...globalUsers, newUser]);
  };

  const handleAddReport = (report: ShiftReport) => {
    setShiftReports(prev => [report, ...prev]);
  };

  const handleEditUser = (updatedUser: User) => {
    setGlobalUsers(globalUsers.map(u => u.id === updatedUser.id ? updatedUser : u));
    if (updatedUser.workerId) {
       const updatedWorkers = globalWorkers.map(w => 
         w.id === updatedUser.workerId ? { ...w, name: updatedUser.name } : w
       );
       setGlobalWorkers(updatedWorkers);
    }
  };

  const handleDeleteUser = (userId: string) => {
    const userToDelete = globalUsers.find(u => u.id === userId);
    setGlobalUsers(globalUsers.filter(u => u.id !== userId));
    if (userToDelete && userToDelete.workerId) {
      setGlobalWorkers(globalWorkers.filter(w => w.id !== userToDelete.workerId));
    }
  };

  const renderContent = () => {
    if (!user) return <Login onLogin={handleLogin} users={globalUsers} />;

    switch (currentView) {
      case 'dashboard':
        return <Dashboard workers={globalWorkers} incidents={mockIncidents} user={user} setView={setCurrentView} />;
      case 'monitoring':
        return <SafetyMonitoring initialWorkers={globalWorkers} />;
      case 'deployment':
        return (
          <WorkforceDeployment 
            workers={globalWorkers} 
            onUpdateWorkers={handleUpdateWorkers}
            shifts={mockShifts} 
            userRole={user.role} 
            reports={shiftReports}
          />
        );
      case 'schedule':
        return <ScheduleOptimizer workers={globalWorkers} shifts={mockShifts} />;
      case 'risk':
        return <RiskAssessment workers={globalWorkers} />;
      case 'incidents':
        return <IncidentAnalysis incidents={mockIncidents} />;
      case 'users':
        return (
          <UserManagement 
            users={globalUsers} 
            onAddUser={handleAddUser}
            onEditUser={handleEditUser}
            onAddWorker={handleAddWorker}
            onDeleteUser={handleDeleteUser}
          />
        );
      case 'portal':
        return (
          <TechnicianPortal 
            user={user} 
            workers={globalWorkers} 
            shifts={mockShifts as Shift[]} 
            onAddReport={handleAddReport}
          />
        );
      default:
        return <Dashboard workers={globalWorkers} incidents={mockIncidents} user={user} setView={setCurrentView} />;
    }
  };

  const NavItem = ({ view, label, icon: Icon, allowedRoles }: { view: View; label: string; icon: any; allowedRoles?: UserRole[] }) => {
    if (allowedRoles && user && !allowedRoles.includes(user.role)) return null;

    return (
      <button
        onClick={() => {
          setCurrentView(view);
          setIsSidebarOpen(false);
        }}
        className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all duration-200 ${
          currentView === view 
            ? 'bg-white text-green-700 shadow-lg shadow-green-900/20 font-bold scale-[1.02]' 
            : 'text-green-50 hover:bg-green-600/50 hover:text-white'
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </button>
    );
  };

  if (!user) return <Login onLogin={handleLogin} users={globalUsers} />;

  return (
    <div className="min-h-screen bg-slate-50 flex font-sans text-slate-900">
      {isSidebarOpen && <div className="fixed inset-0 bg-black/50 z-20 lg:hidden" onClick={() => setIsSidebarOpen(false)} />}

      <aside className={`
        fixed inset-y-0 left-0 z-30 w-72 bg-gradient-to-b from-green-700 to-green-800 text-white transform transition-transform duration-300 ease-in-out lg:translate-x-0 lg:static lg:h-screen flex flex-col shadow-2xl
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-8 border-b border-green-600/50">
          <div className="flex items-center space-x-4 mb-3">
            <div className="w-12 h-12 bg-white rounded-2xl p-1.5 flex items-center justify-center shadow-lg transform -rotate-3">
               <Logo />
            </div>
            <div>
              <span className="text-xl font-black tracking-tighter leading-none block">OLFU</span>
              <span className="text-sm font-bold tracking-widest text-green-100 block opacity-70">SAFETYNET</span>
            </div>
          </div>
          <p className="text-[10px] font-bold text-green-200/60 uppercase tracking-widest">Valenzuela Main Campus</p>
        </div>

        <nav className="flex-1 p-6 space-y-3 overflow-y-auto">
          <NavItem view="dashboard" label="Overview" icon={LayoutDashboard} allowedRoles={['Admin', 'Supervisor', 'SafetyOfficer']} />
          <NavItem view="deployment" label="Deployment" icon={ClipboardCheck} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />
          <NavItem view="monitoring" label="Real-Time Protection" icon={Activity} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />
          <NavItem view="schedule" label="Productivity Engine" icon={Users} allowedRoles={['Admin', 'Supervisor']} />
          <NavItem view="risk" label="Risk Assessment" icon={ShieldAlert} allowedRoles={['Admin', 'SafetyOfficer']} />
          <NavItem view="incidents" label="Incident Logs" icon={FileWarning} allowedRoles={['Admin', 'SafetyOfficer']} />
          <NavItem view="users" label="User Management" icon={UserCog} allowedRoles={['Admin']} />
          <NavItem view="portal" label="My Assignment" icon={HardHat} allowedRoles={['Staff']} />
        </nav>

        <div className="p-6 border-t border-green-600/50 bg-green-900/20">
          <div className="flex items-center gap-3 mb-6 px-2">
             <div className="w-10 h-10 rounded-xl bg-white/10 backdrop-blur-md border border-white/20 flex items-center justify-center text-sm font-black text-white">
               {user.name.charAt(0)}
             </div>
             <div className="flex-1 overflow-hidden">
               <p className="text-sm font-bold text-white truncate">{user.name}</p>
