                 <div className="flex items-center gap-3">
                   <Activity size={16} className="text-indigo-400" />
                   <span className="text-xs font-bold text-slate-700">Bio-Telemetry</span>
                 </div>
                 <span className="text-[10px] font-black text-green-600 uppercase">Active</span>
               </li>
               <li className="flex items-center justify-between p-4 rounded-2xl bg-slate-50 border border-slate-100 group transition-all hover:bg-indigo-50">
                 <div className="flex items-center gap-3">
                   <Calendar size={16} className="text-indigo-400" />
                   <span className="text-xs font-bold text-slate-700">Shift Date</span>
                 </div>
                 <span className="text-[10px] font-black text-slate-600 uppercase">{new Date().toLocaleDateString('en-GB')}</span>
