      {filteredReports.length === 0 ? (
        <div className="bg-white rounded-3xl p-16 text-center border border-slate-200 shadow-sm">
           <FileSearch className="mx-auto mb-6 text-slate-200" size={64} />
           <p className="text-slate-400 font-bold uppercase tracking-widest text-sm">No recorded reports found.</p>
           <p className="text-xs text-slate-300 mt-2">Completed staff shifts will automatically populate here.</p>
