           {filteredReports.map((report) => (
             <div key={report.id} className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden hover:shadow-lg transition-all border-t-4 border-t-indigo-500">
               <div className="p-5 border-b border-slate-100 flex justify-between items-start">
                  <div>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Staff Member</p>
                    <h4 className="font-black text-slate-800 text-lg">{report.workerName}</h4>
