                  <div className="bg-slate-50 px-2 py-1 rounded text-[9px] font-black text-slate-500 border border-slate-200 uppercase">
                    {report.id}
                  </div>
               </div>

               <div className="p-5 space-y-4">
                  <div className="flex gap-4">
                     <div className="flex-1">
                        <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">Location</p>
                        <p className="text-xs font-black text-slate-700 flex items-center gap-1">
                          <MapPin size={12} className="text-indigo-500" /> {report.location.split(' ')[0]}
                        </p>
                     </div>
                     <div className="flex-1">
                        <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">Completion</p>
                        <p className="text-xs font-black text-slate-700 flex items-center gap-1">
                          <Calendar size={12} className="text-indigo-500" /> {report.time}
                        </p>
