                      <p className="text-sm font-black text-slate-800">{report.finalVitals.hr} BPM</p>
                    </div>
                    <div>
                      <p className="text-[9px] font-bold text-slate-400 uppercase">Final Temp</p>
                      <p className="text-sm font-black text-slate-800">{report.finalVitals.temp}°C</p>
                    </div>
