                     <p className="text-[9px] font-black text-indigo-700 uppercase tracking-widest mb-2 flex items-center gap-2">
                       <BrainCircuit size={12} /> AI Performance Log
                     </p>
                     <p className="text-[11px] font-medium leading-relaxed text-slate-600 italic line-clamp-3">
                       {report.aiSummary}
                     </p>
                     <div className="mt-3 flex justify-between items-center pt-3 border-t border-indigo-100">
                        <span className="text-[9px] font-black text-slate-400 uppercase">System Rating:</span>
                        <span className="text-[10px] font-black text-indigo-700 uppercase">{report.performanceRating}</span>
                     </div>
                  </div>
               </div>

               <button className="w-full bg-slate-50 py-3 text-[10px] font-black text-indigo-600 uppercase border-t border-slate-100 hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center gap-2">
                 <FileSearch size={14} /> Full Record Access
               </button>
             </div>
