                     onChange={e => setChecklist({...checklist, trainingValid: e.target.checked})}
                  />
                  <span className="text-xs font-black text-slate-700 uppercase tracking-wide group-hover:text-green-700 transition-colors">Specialized Certifications Valid</span>
                </label>
              </div>
            </div>

            <div className="p-6 bg-slate-50 border-t border-slate-200 flex gap-4">
              <button 
                onClick={() => submitSafetyDecision('Rejected')}
                className="flex-1 bg-white border-2 border-red-200 text-red-600 font-black py-4 rounded-2xl hover:bg-red-50 transition uppercase text-xs tracking-widest shadow-sm"
              >
                Reject Clearance
              </button>
              <button 
                onClick={() => submitSafetyDecision('Cleared')}
                disabled={!checklist.ppeCheck || !checklist.trainingValid}
                className="flex-1 bg-green-700 text-white font-black py-4 rounded-2xl hover:bg-green-800 transition disabled:opacity-50 disabled:cursor-not-allowed shadow-xl uppercase text-xs tracking-widest"
              >
                Finalize & Clear
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default WorkforceDeployment;

import React, { useState, useEffect } from 'react';
import { Worker, SafetyChecklist, Shift, UserRole, ShiftReport } from '../types';
import { getClearanceRecommendation } from '../services/gemini';
import { 
  ClipboardCheck, ShieldCheck, UserCheck, AlertTriangle, 
  Briefcase, FileSignature, CheckCircle2, XCircle, 
  BrainCircuit, ArrowRight, RotateCcw, MapPin, 
  FileSearch, Activity, Calendar, History, TrendingUp, Search,
  Sparkles, Loader2
} from 'lucide-react';

interface Props {
  workers: Worker[];
  onUpdateWorkers: (workers: Worker[]) => void;
  shifts: Partial<Shift>[];
  userRole: UserRole;
  reports: ShiftReport[];
}

const WorkforceDeployment: React.FC<Props> = ({ workers, onUpdateWorkers, shifts, userRole, reports }) => {
  const [activeView, setActiveView] = useState<'SafetyOfficer' | 'Supervisor' | 'Archives'>(
    userRole === 'Supervisor' ? 'Supervisor' : 'SafetyOfficer'
  );

  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    if (userRole === 'Supervisor') setActiveView('Supervisor');
    else if (userRole === 'SafetyOfficer') setActiveView('SafetyOfficer');
  }, [userRole]);

  const [selectedWorker, setSelectedWorker] = useState<Worker | null>(null);
  const [aiRecommendation, setAiRecommendation] = useState<any>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [selectedShiftForDeploy, setSelectedShiftForDeploy] = useState<string>(shifts[0]?.name || '');

  // Filtered reports for the Archive view
  const filteredReports = reports.filter(r => 
    r.workerName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    r.location.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const pendingCount = workers.filter(w => w.safetyStatus === 'Pending' || w.safetyStatus === 'Rejected').length;
  const clearedCount = workers.filter(w => w.safetyStatus === 'Cleared').length;
  const deployedCount = workers.filter(w => w.safetyStatus === 'Deployed').length;

  const [checklist, setChecklist] = useState<SafetyChecklist>({
    ppeCheck: false,
    trainingValid: false,
    healthCheck: false,
    permitsActive: false
  });

  const handleOpenChecklist = async (worker: Worker) => {
    setSelectedWorker(worker);
    setChecklist({ ppeCheck: false, trainingValid: false, healthCheck: false, permitsActive: false });
    setAiRecommendation(null);
    setLoadingAi(true);

    try {
      const rec = await getClearanceRecommendation(worker);
      setAiRecommendation(rec);
    } catch (e) {
      console.error("AI Recommendation failed");
    } finally {
      setLoadingAi(false);
    }
  };

  const submitSafetyDecision = (status: 'Cleared' | 'Rejected') => {
    if (!selectedWorker) return;
    const updatedWorkers = workers.map(w => 
      w.id === selectedWorker.id ? { ...w, safetyStatus: status } : w
    );
    onUpdateWorkers(updatedWorkers);
    setSelectedWorker(null);
  };

  const handleDeploy = (workerId: string, shiftName: string) => {
    const updatedWorkers = workers.map(w => 
      w.id === workerId ? { 
        ...w, 
        safetyStatus: 'Deployed', 
        status: 'Active',
        currentLocation: shiftName 
      } as Worker : w
    );
    onUpdateWorkers(updatedWorkers);
  };

  const handleRecall = (workerId: string) => {
    const updatedWorkers = workers.map(w => 
      w.id === workerId ? { 
        ...w, 
        safetyStatus: 'Cleared', 
        status: 'Active',
        currentLocation: 'General Assembly' 
      } as Worker : w
    );
    onUpdateWorkers(updatedWorkers);
  };

  const renderSafetyOfficerView = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="bg-green-50 border border-green-200 p-4 rounded-lg flex items-start gap-3">
        <ClipboardCheck className="text-green-600 mt-1" />
        <div>
          <h3 className="font-bold text-green-800">Safety Officer Dashboard</h3>
          <p className="text-sm text-green-600">
            You have <span className="font-bold">{pendingCount}</span> workers waiting for safety clearance.
          </p>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="p-4 border-b border-slate-200 bg-slate-50 flex justify-between items-center">
          <h4 className="font-bold text-slate-700">Pending Safety Reviews</h4>
          <span className="text-xs bg-orange-100 text-orange-700 px-2 py-1 rounded-full font-bold">Action Required</span>
        </div>

        {workers.filter(w => w.safetyStatus !== 'Cleared' && w.safetyStatus !== 'Deployed').length === 0 ? (
          <div className="p-8 text-center text-slate-400">
            <CheckCircle2 size={48} className="mx-auto mb-3 text-green-200" />
            <p>All workers have been reviewed!</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead className="bg-slate-50 border-b border-slate-200">
                <tr>
                  <th className="px-6 py-4 font-semibold text-slate-700">Worker</th>
                  <th className="px-6 py-4 font-semibold text-slate-700">Role</th>
                  <th className="px-6 py-4 font-semibold text-slate-700">Health Status</th>
                  <th className="px-6 py-4 font-semibold text-slate-700">Status</th>
                  <th className="px-6 py-4 font-semibold text-slate-700">Action</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {workers.filter(w => w.safetyStatus !== 'Cleared' && w.safetyStatus !== 'Deployed').map(worker => (
                  <tr key={worker.id} className="hover:bg-slate-50">
                    <td className="px-6 py-4 font-medium text-slate-900">{worker.name}</td>
                    <td className="px-6 py-4 text-slate-500">{worker.role}</td>
                    <td className="px-6 py-4">
                       {worker.fatigueLevel > 30 ? (
                         <span className="text-orange-600 flex items-center gap-1"><AlertTriangle size={14}/> Fatigue {worker.fatigueLevel}%</span>
                       ) : (
                         <span className="text-green-600 flex items-center gap-1"><CheckCircle2 size={14}/> Fit</span>
                       )}
                    </td>
                    <td className="px-6 py-4">
                      <span className={`px-2 py-1 rounded-full text-xs font-bold ${
                        worker.safetyStatus === 'Rejected' ? 'bg-red-100 text-red-700' : 'bg-yellow-100 text-yellow-700'
                      }`}>
                        {worker.safetyStatus.toUpperCase()}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <button 
                        onClick={() => handleOpenChecklist(worker)}
                        className="bg-green-600 text-white px-3 py-1.5 rounded text-xs font-medium hover:bg-green-700 transition shadow-sm"
                      >
                        Verify & Clear
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );

  const renderSupervisorView = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="bg-blue-50 border border-blue-200 p-4 rounded-lg flex items-start gap-3">
        <Briefcase className="text-blue-600 mt-1" />
        <div>
          <h3 className="font-bold text-blue-800">Supervisor Dashboard</h3>
          <p className="text-sm text-blue-600">Assign cleared personnel to active shifts.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
