      {activeView === 'SafetyOfficer' && renderSafetyOfficerView()}
      {activeView === 'Supervisor' && renderSupervisorView()}
      {activeView === 'Archives' && renderArchivesView()}

      {/* Safety Checklist Modal */}
      {selectedWorker && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden animate-fade-in border border-slate-200">
            <div className="bg-green-700 p-6 text-white flex justify-between items-center">
              <h3 className="font-black uppercase tracking-widest flex items-center gap-3">
                <FileSignature size={24}/> Safety Clearance Verification
              </h3>
              <button onClick={() => setSelectedWorker(null)}><XCircle className="opacity-80 hover:opacity-100"/></button>
            </div>

            <div className="p-8 space-y-6">
              <div className="flex justify-between items-center bg-slate-50 p-5 rounded-2xl border border-slate-100 shadow-inner">
                <div>
                  <p className="font-black text-slate-800 text-lg">{selectedWorker.name}</p>
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">{selectedWorker.role}</p>
                </div>
                <div className="text-right">
                   <p className="text-[10px] font-black text-slate-400 uppercase mb-1">Fatigue Score</p>
                   <p className="font-black text-slate-800">{selectedWorker.fatigueLevel}%</p>
                </div>
              </div>

              <div className="bg-gradient-to-br from-green-50 to-emerald-50 border border-green-100 p-5 rounded-2xl relative overflow-hidden group">
                <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                  <BrainCircuit size={40} />
                </div>
                <h4 className="text-[10px] font-black text-green-800 uppercase tracking-[0.2em] mb-3 flex items-center gap-2">
                  <Sparkles size={14}/> Gemini Safety Intelligence
                </h4>
                {loadingAi ? (
                  <div className="flex items-center gap-3 text-sm text-slate-500 italic">
                    <Loader2 className="animate-spin" size={16} /> 
                    Conducting bio-metric audit...
                  </div>
                ) : aiRecommendation ? (
                  <div className="animate-fade-in">
                    <p className={`font-black text-base ${aiRecommendation.recommendation === 'Approve' ? 'text-green-700' : 'text-red-700'}`}>
                      {aiRecommendation.recommendation === 'Approve' ? 'MISSION READY: APPROVE' : 'RISK DETECTED: REJECT'}
                    </p>
                    <p className="text-xs text-slate-600 mt-2 font-medium leading-relaxed">{aiRecommendation.reasoning}</p>
                  </div>
                ) : (
                  <p className="text-sm text-slate-500">Telemetry feed interrupted.</p>
                )}
              </div>

              <div className="space-y-3">
                <label className="flex items-center gap-3 p-4 border-2 border-slate-100 rounded-2xl hover:bg-slate-50 cursor-pointer transition-all active:scale-95 group">
                  <input type="checkbox" className="w-5 h-5 text-green-700 rounded-lg focus:ring-green-500 border-slate-300" 
                    checked={checklist.ppeCheck}
                    onChange={e => setChecklist({...checklist, ppeCheck: e.target.checked})}
                  />
                  <span className="text-xs font-black text-slate-700 uppercase tracking-wide group-hover:text-green-700 transition-colors">PPE Verified & Bio-Scan Confirmed</span>
                </label>
                <label className="flex items-center gap-3 p-4 border-2 border-slate-100 rounded-2xl hover:bg-slate-50 cursor-pointer transition-all active:scale-95 group">
                  <input type="checkbox" className="w-5 h-5 text-green-700 rounded-lg focus:ring-green-500 border-slate-300" 
                     checked={checklist.trainingValid}
                     onChange={e => setChecklist({...checklist, trainingValid: e.target.checked})}
                  />
                  <span className="text-xs font-black text-slate-700 uppercase tracking-wide group-hover:text-green-700 transition-colors">Specialized Certifications Valid</span>
                </label>
              </div>
            </div>

            <div className="p-6 bg-slate-50 border-t border-slate-200 flex gap-4">
              <button 
                onClick={() => submitSafetyDecision('Rejected')}
                className="flex-1 bg-white border-2 border-red-200 text-red-600 font-black py-4 rounded-2xl hover:bg-red-50 transition uppercase text-xs tracking-widest shadow-sm"
              >
                Reject Clearance
              </button>
              <button 
                onClick={() => submitSafetyDecision('Cleared')}
                disabled={!checklist.ppeCheck || !checklist.trainingValid}
                className="flex-1 bg-green-700 text-white font-black py-4 rounded-2xl hover:bg-green-800 transition disabled:opacity-50 disabled:cursor-not-allowed shadow-xl uppercase text-xs tracking-widest"
              >
                Finalize & Clear
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default WorkforceDeployment;

export enum SkillLevel {
  Junior = 'Junior',
  Mid = 'Mid',
  Senior = 'Senior',
  Expert = 'Expert'
}

export type UserRole = 'Admin' | 'SafetyOfficer' | 'Supervisor' | 'Staff';

export interface User {
  id: string;
  username: string;
  name: string;
  role: UserRole;
  avatar?: string;
  workerId?: string; // Link to worker profile if applicable
}

export type WorkerStatus = 'Active' | 'Warning' | 'Critical' | 'Offline';
export type SafetyClearanceStatus = 'Pending' | 'Cleared' | 'Rejected' | 'Deployed';

export interface Worker {
  id: string;
  name: string;
  role: string;
  skillLevel: SkillLevel;
  certifications: string[];
  productivityScore: number; // 0-100
  fatigueLevel: number; // 0-100 (Higher is more tired)
  lastIncidentDate?: string;

  // Real-time Monitoring Data
  currentLocation: string;
  assignedTime?: string; // e.g., "08:00 AM - 05:00 PM"
  vitals: {
    heartRate: number; // bpm
    bodyTemp: number; // celsius
    oxygenLevel: number; // %
  };
  ppeCompliant: boolean;
  status: WorkerStatus;

  // Workflow Status
  safetyStatus: SafetyClearanceStatus;
  assignedShiftId?: string;
}

export interface Shift {
  id: string;
  name: string;
  time: string;
  requiredRoles: string[];
  assignedWorkers: Worker[];
  riskScore: number; // Predicted by AI
}

export interface ShiftReport {
  id: string;
  workerId: string;
  workerName: string;
  date: string;
  time: string;
  shiftName: string;
  location: string;
  finalVitals: {
    hr: number;
    temp: number;
  };
  aiSummary?: string;
  performanceRating?: string;
  completionPhoto?: string; // Base64 work evidence photo
}

export interface Incident {
  id: string;
  date: string;
  type: 'Near Miss' | 'Injury' | 'Equipment Failure' | 'Protocol Violation';
  severity: 'Low' | 'Medium' | 'High' | 'Critical';
  description: string;
  location: string;
}

export interface RiskPrediction {
  riskLevel: 'Low' | 'Medium' | 'High' | 'Critical';
  probability: number;
  factors: string[];
  mitigationStrategies: string[];
}

export interface OptimizationResult {
  schedules: {
    shiftName: string;
    assignments: {
      role: string;
      workerName: string;
      reason: string;
    }[];
  }[];
  improvementSummary: string;
}

export interface RealTimeAnalysis {
  alerts: {
    workerId: string;
    type: string;
    description: string;
    priority: 'High' | 'Medium' | 'Low';
    fatigueDiagnostic?: {
      score: number;
      primaryReason: string;
      isHeartRateDriven: boolean;
    };
  }[];
  zoneAnalysis: {
    zoneName: string;
    safetyStatus: string;
  }[];
  recommendedActions: string[];
}

export interface SafetyChecklist {
  ppeCheck: boolean;
  trainingValid: boolean;
  healthCheck: boolean;
  permitsActive: boolean;
}

import React, { useState, useEffect } from 'react';
import { Worker, SafetyChecklist, Shift, UserRole, ShiftReport } from '../types';
import { getClearanceRecommendation } from '../services/gemini';
import { 
  ClipboardCheck, ShieldCheck, UserCheck, AlertTriangle, 
  Briefcase, FileSignature, CheckCircle2, XCircle, 
  BrainCircuit, ArrowRight, RotateCcw, MapPin, 
  FileSearch, Activity, Calendar, History, TrendingUp, Search,
  Sparkles, Loader2, Clock, Map
} from 'lucide-react';

interface Props {
  workers: Worker[];
  onUpdateWorkers: (workers: Worker[]) => void;
  shifts: Partial<Shift>[];
  userRole: UserRole;
  reports: ShiftReport[];
}

const OLFU_LOCATIONS = [
  "Valenzuela - St. Bonaventure Hall",
  "Valenzuela - Rise Tower",
  "Valenzuela - St. John de Baptist Bldg",
  "Valenzuela - Fatima Gymnasium",
  "Valenzuela - San Vicente Hall",
  "Valenzuela - CAS Building",
  "Valenzuela - Parking Lot B",
  "Quezon City Campus",
  "Antipolo Campus",
  "Pampanga Campus",
  "Cabanatuan Campus",
  "Laguna Campus"
];

const WorkforceDeployment: React.FC<Props> = ({ workers, onUpdateWorkers, shifts, userRole, reports }) => {
  const [activeView, setActiveView] = useState<'SafetyOfficer' | 'Supervisor' | 'Archives'>(
    userRole === 'Supervisor' ? 'Supervisor' : 'SafetyOfficer'
  );

  const [searchTerm, setSearchTerm] = useState('');
  const [deploymentInputs, setDeploymentInputs] = useState<Record<string, { location: string, time: string }>>({});

  useEffect(() => {
    if (userRole === 'Supervisor') setActiveView('Supervisor');
    else if (userRole === 'SafetyOfficer') setActiveView('SafetyOfficer');
  }, [userRole]);

  // Initialize deployment inputs for cleared workers
  useEffect(() => {
    const initialInputs: Record<string, { location: string, time: string }> = {};
    workers.filter(w => w.safetyStatus === 'Cleared').forEach(w => {
      initialInputs[w.id] = { 
        location: OLFU_LOCATIONS[0], 
        time: "08:00 AM - 05:00 PM" 
      };
    });
    setDeploymentInputs(prev => ({ ...initialInputs, ...prev }));
  }, [workers]);

  const [selectedWorker, setSelectedWorker] = useState<Worker | null>(null);
  const [aiRecommendation, setAiRecommendation] = useState<any>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // Filtered reports for the Archive view
  const filteredReports = reports.filter(r => 
    r.workerName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    r.location.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const pendingCount = workers.filter(w => w.safetyStatus === 'Pending' || w.safetyStatus === 'Rejected').length;
  const clearedCount = workers.filter(w => w.safetyStatus === 'Cleared').length;
  const deployedCount = workers.filter(w => w.safetyStatus === 'Deployed').length;

  const [checklist, setChecklist] = useState<SafetyChecklist>({
    ppeCheck: false,
    trainingValid: false,
    healthCheck: false,
    permitsActive: false
  });

  const handleOpenChecklist = async (worker: Worker) => {
    setSelectedWorker(worker);
    setChecklist({ ppeCheck: false, trainingValid: false, healthCheck: false, permitsActive: false });
    setAiRecommendation(null);
    setLoadingAi(true);

    try {
      const rec = await getClearanceRecommendation(worker);
      setAiRecommendation(rec);
    } catch (e) {
      console.error("AI Recommendation failed");
    } finally {
      setLoadingAi(false);
    }
  };

  const submitSafetyDecision = (status: 'Cleared' | 'Rejected') => {
    if (!selectedWorker) return;
    const updatedWorkers = workers.map(w => 
      w.id === selectedWorker.id ? { ...w, safetyStatus: status } : w
    );
    onUpdateWorkers(updatedWorkers);
    setSelectedWorker(null);
  };

  const updateDeploymentInput = (workerId: string, field: 'location' | 'time', value: string) => {
    setDeploymentInputs(prev => ({
      ...prev,
      [workerId]: {
        ...prev[workerId],
        [field]: value
      }
    }));
  };

  const handleDeploy = (workerId: string) => {
    const input = deploymentInputs[workerId];
    if (!input) return;

    const updatedWorkers = workers.map(w => 
      w.id === workerId ? { 
        ...w, 
        safetyStatus: 'Deployed', 
        status: 'Active',
        currentLocation: input.location,
        assignedTime: input.time
      } as Worker : w
    );
    onUpdateWorkers(updatedWorkers);
  };

  const handleRecall = (workerId: string) => {
    const updatedWorkers = workers.map(w => 
      w.id === workerId ? { 
        ...w, 
        safetyStatus: 'Cleared', 
        status: 'Active',
        currentLocation: 'General Assembly',
        assignedTime: undefined
