    workers.filter(w => w.safetyStatus === 'Cleared').forEach(w => {
      initialInputs[w.id] = { 
        location: OLFU_LOCATIONS[0], 
        startTime: "08:00",
        endTime: "17:00"
      };
    });
    setDeploymentInputs(prev => {
      const merged = { ...initialInputs };
      // Keep existing inputs if they were already modified
