  const assignedShift = shifts.find(s => s.name === workerProfile.currentLocation) || shifts[0];

  useEffect(() => {
    setLocalVitals({ hr: workerProfile.vitals.heartRate, temp: workerProfile.vitals.bodyTemp });
  }, [workerProfile]);

  const handleHardwareSync = () => {
    setIsSyncing(true);
    setTimeout(() => {
      const newHr = 72 + Math.floor(Math.random() * 10);
      const newTemp = 36.5 + (Math.random() * 0.5);
      setLocalVitals({ hr: newHr, temp: Number(newTemp.toFixed(1)) });
      setLastSync(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }));
      setIsSyncing(false);
    }, 1500);
  };

  const handleRequestClearance = () => {
    const updatedWorkers = workers.map(w => 
      w.id === workerProfile.id ? { ...w, safetyStatus: 'Pending' } as Worker : w
    );
    onUpdateWorkers(updatedWorkers);
  };

  const handleStartCamera = async (mode: 'ppe' | 'completion') => {
    setCameraMode(mode);
    setShowCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: mode === 'ppe' ? 'user' : 'environment' } 
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
    } catch (err) {
      console.error("Camera error:", err);
      alert("Please allow camera access.");
    }
  };

  const captureImage = async () => {
    if (!videoRef.current || !canvasRef.current) return;
    setIsScanning(true);

    const context = canvasRef.current.getContext('2d');
    canvasRef.current.width = videoRef.current.videoWidth;
    canvasRef.current.height = videoRef.current.videoHeight;
    context?.drawImage(videoRef.current, 0, 0);

    const base64Image = canvasRef.current.toDataURL('image/jpeg').split(',')[1];

    if (cameraMode === 'ppe') {
      try {
        const result = await analyzePPECompliance(base64Image);
        if (result.hasHardHat && result.hasHighVisVest) {
          const updatedWorkers = workers.map(w => 
            w.id === workerProfile.id ? { ...w, ppeCompliant: true } as Worker : w
          );
          onUpdateWorkers(updatedWorkers);
        } else {
          alert(`Safety Check Flagged: ${result.feedback}`);
        }
        closeCamera();
      } catch (e) {
        console.error(e);
        alert("Analysis failed.");
      } finally {
        setIsScanning(false);
      }
    } else {
      setCompletionPhoto(`data:image/jpeg;base64,${base64Image}`);
      setIsScanning(false);
      closeCamera();
      finalizeShiftCompletion(`data:image/jpeg;base64,${base64Image}`);
    }
  };

  const closeCamera = () => {
    const stream = videoRef.current?.srcObject as MediaStream;
    stream?.getTracks().forEach(track => track.stop());
    setShowCamera(false);
  };

  const finalizeShiftCompletion = async (photoData: string) => {
    setIsLoadingSummary(true);
    setIsCompleted(true);

    const now = new Date();
    const timeStr = now.toLocaleTimeString();
    const dateStr = now.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
    setReportGeneratedAt(timeStr);
    setReportDate(dateStr);

    try {
      const updatedWorkers = workers.map(w => 
        w.id === workerProfile.id ? { ...w, vitals: { ...w.vitals, heartRate: localVitals.hr, bodyTemp: localVitals.temp } } as Worker : w
      );
      onUpdateWorkers(updatedWorkers);

      // Generate AI summary for record keeping only
      const summary = await generateShiftSummary(workerProfile);

      const newReport: ShiftReport = {
        id: `REP-${Date.now()}`,
        workerId: workerProfile.id,
        workerName: workerProfile.name,
        date: dateStr,
        time: timeStr,
        shiftName: assignedShift?.name || 'Unassigned Shift',
        location: workerProfile.currentLocation,
        finalVitals: {
          hr: localVitals.hr,
          temp: localVitals.temp
        },
        aiSummary: summary.summary,
        performanceRating: summary.performanceRating,
        completionPhoto: photoData
      };
      onAddReport(newReport);

    } catch (e) {
      console.error(e);
    } finally {
      setIsLoadingSummary(false);
    }
  };

  const handlePrintPDF = () => {
    window.print();
  };

  const resetPortal = () => {
    setIsCompleted(false);
    setCompletionPhoto(null);
  };

  return (
    <div className="space-y-6">
