import { User, Worker, Shift, ShiftReport, Incident } from './types';

const API_BASE_URL = '/api';

export const api = {
  // Authentication
  async getUsers(): Promise<User[]> {
    const res = await fetch(`${API_BASE_URL}/users`);
    if (!res.ok) throw new Error('Failed to fetch users');
    return res.json();
  },

  async createUser(user: Partial<User>): Promise<User> {
    const res = await fetch(`${API_BASE_URL}/users`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(user),
    });
    return res.json();
  },

  // Workers
  async getWorkers(): Promise<Worker[]> {
    const res = await fetch(`${API_BASE_URL}/workers`);
    return res.json();
  },

  async updateWorker(id: string, updates: Partial<Worker>): Promise<Worker> {
    const res = await fetch(`${API_BASE_URL}/workers/${id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(updates),
    });
    return res.json();
  },

  // Shifts & Reports
  async getReports(): Promise<ShiftReport[]> {
    const res = await fetch(`${API_BASE_URL}/reports`);
    return res.json();
  },

  async createReport(report: ShiftReport): Promise<ShiftReport> {
    const res = await fetch(`${API_BASE_URL}/reports`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(report),
    });
    return res.json();
  },

  // Incidents
  async getIncidents(): Promise<Incident[]> {
    const res = await fetch(`${API_BASE_URL}/incidents`);
    return res.json();
  }
};

import React, { useState, useEffect } from 'react';
import Dashboard from './components/Dashboard';
import IncidentAnalysis from './components/IncidentAnalysis';
import SafetyMonitoring from './components/SafetyMonitoring';
import WorkforceDeployment from './components/WorkforceDeployment';
import Login from './components/Login';
import UserManagement from './components/UserManagement';
import TechnicianPortal from './components/TechnicianPortal';
import Logo from './components/Logo';
import { api } from './api';
import { User, UserRole, Worker, Shift, ShiftReport, Incident } from './types';
import { LayoutDashboard, Users, ShieldAlert, FileWarning, Menu, LogOut, HardHat, Activity, ClipboardCheck, UserCog, Loader2 } from 'lucide-react';

type View = 'dashboard' | 'monitoring' | 'deployment' | 'incidents' | 'users' | 'portal';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  const [globalWorkers, setGlobalWorkers] = useState<Worker[]>([]);
  const [globalUsers, setGlobalUsers] = useState<User[]>([]);
  const [shiftReports, setShiftReports] = useState<ShiftReport[]>([]);
  const [incidents, setIncidents] = useState<Incident[]>([]);

  // Initial Data Fetch from MySQL via API
  useEffect(() => {
    const loadData = async () => {
      try {
        const [usersData, workersData, reportsData, incidentsData] = await Promise.all([
          api.getUsers(),
          api.getWorkers(),
          api.getReports(),
          api.getIncidents()
        ]);
        setGlobalUsers(usersData);
        setGlobalWorkers(workersData);
        setShiftReports(reportsData);
        setIncidents(incidentsData);
      } catch (error) {
        console.error("Database connection failed. Ensure backend is running.", error);
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    if (loggedInUser.role === 'Staff') setCurrentView('portal');
    else if (loggedInUser.role === 'SafetyOfficer') setCurrentView('deployment');
    else setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setUser(null);
    setCurrentView('dashboard');
  };

  const handleUpdateWorkers = async (updatedWorkers: Worker[]) => {
    setGlobalWorkers(updatedWorkers);
    // In a real app, we'd sync the specific changed worker to the DB
    const changed = updatedWorkers.find((w, i) => JSON.stringify(w) !== JSON.stringify(globalWorkers[i]));
    if (changed) {
      await api.updateWorker(changed.id, changed);
    }
  };

  const handleAddWorker = async (newWorker: Worker) => {
    setGlobalWorkers([...globalWorkers, newWorker]);
    // Backend creates worker via user creation trigger or direct call
  };

  const handleAddUser = async (newUser: User) => {
    const savedUser = await api.createUser(newUser);
    setGlobalUsers([...globalUsers, savedUser]);
  };

  const handleAddReport = async (report: ShiftReport) => {
    const savedReport = await api.createReport(report);
    setShiftReports(prev => [savedReport, ...prev]);
  };

  const handleEditUser = async (updatedUser: User) => {
    // API call for updating user
    setGlobalUsers(globalUsers.map(u => u.id === updatedUser.id ? updatedUser : u));
  };

  const handleDeleteUser = async (userId: string) => {
    setGlobalUsers(globalUsers.filter(u => u.id !== userId));
    // API call for delete
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-900 flex flex-col items-center justify-center text-white">
        <Loader2 className="animate-spin text-green-500 mb-4" size={48} />
        <p className="font-black uppercase tracking-widest text-sm">Initializing SafetyNet Database...</p>
      </div>
    );
  }

  const renderContent = () => {
    if (!user) return <Login onLogin={handleLogin} users={globalUsers} />;

    switch (currentView) {
      case 'dashboard':
        return <Dashboard workers={globalWorkers} incidents={incidents} user={user} setView={setCurrentView} />;
      case 'monitoring':
        return <SafetyMonitoring initialWorkers={globalWorkers} />;
      case 'deployment':
        return (
          <WorkforceDeployment 
            workers={globalWorkers} 
            onUpdateWorkers={handleUpdateWorkers}
            shifts={[]} // Shifts can be fetched from API similarly
            userRole={user.role} 
            reports={shiftReports}
          />
        );
      case 'incidents':
        return <IncidentAnalysis incidents={incidents} />;
      case 'users':
        return (
          <UserManagement 
            users={globalUsers} 
            onAddUser={handleAddUser}
            onEditUser={handleEditUser}
            onAddWorker={handleAddWorker}
            onDeleteUser={handleDeleteUser}
          />
        );
      case 'portal':
        return (
          <TechnicianPortal 
            user={user} 
            workers={globalWorkers} 
            shifts={[] as Shift[]} 
            onAddReport={handleAddReport}
            onUpdateWorkers={handleUpdateWorkers}
          />
        );
      default:
        return <Dashboard workers={globalWorkers} incidents={incidents} user={user} setView={setCurrentView} />;
    }
  };

  const NavItem = ({ view, label, icon: Icon, allowedRoles }: { view: View; label: string; icon: any; allowedRoles?: UserRole[] }) => {
    if (allowedRoles && user && !allowedRoles.includes(user.role)) return null;

    return (
      <button
        onClick={() => {
          setCurrentView(view);
          setIsSidebarOpen(false);
        }}
        className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all duration-200 ${
          currentView === view 
            ? 'bg-white text-green-700 shadow-lg shadow-green-900/20 font-bold scale-[1.02]' 
            : 'text-green-50 hover:bg-green-600/50 hover:text-white'
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </button>
    );
  };

  if (!user) return <Login onLogin={handleLogin} users={globalUsers} />;

  return (
    <div className="min-h-screen bg-slate-50 flex font-sans text-slate-900">
      {isSidebarOpen && <div className="fixed inset-0 bg-black/50 z-20 lg:hidden" onClick={() => setIsSidebarOpen(false)} />}

      <aside className={`
        fixed inset-y-0 left-0 z-30 w-72 bg-gradient-to-b from-green-700 to-green-800 text-white transform transition-transform duration-300 ease-in-out lg:translate-x-0 lg:static lg:h-screen flex flex-col shadow-2xl
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-8 border-b border-green-600/50">
          <div className="flex items-center space-x-4 mb-3">
            <div className="w-12 h-12 bg-white rounded-2xl p-1.5 flex items-center justify-center shadow-lg transform -rotate-3">
               <Logo />
            </div>
            <div>
              <span className="text-xl font-black tracking-tighter leading-none block">OLFU</span>
              <span className="text-sm font-bold tracking-widest text-green-100 block opacity-70">SAFETYNET</span>
            </div>
          </div>
          <p className="text-[10px] font-bold text-green-200/60 uppercase tracking-widest">Valenzuela Main Campus</p>
        </div>

        <nav className="flex-1 p-6 space-y-3 overflow-y-auto">
          <NavItem view="dashboard" label="Overview" icon={LayoutDashboard} allowedRoles={['Admin', 'Supervisor', 'SafetyOfficer']} />
          <NavItem view="deployment" label="Deployment" icon={ClipboardCheck} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />
          <NavItem view="monitoring" label="Real-Time Protection" icon={Activity} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />
          <NavItem view="incidents" label="Incident Logs" icon={FileWarning} allowedRoles={['Admin', 'SafetyOfficer']} />
          <NavItem view="users" label="User Management" icon={UserCog} allowedRoles={['Admin']} />
          <NavItem view="portal" label="My Assignment" icon={HardHat} allowedRoles={['Staff']} />
        </nav>

        <div className="p-6 border-t border-green-600/50 bg-green-900/20">
          <div className="flex items-center gap-3 mb-6 px-2">
             <div className="w-10 h-10 rounded-xl bg-white/10 backdrop-blur-md border border-white/20 flex items-center justify-center text-sm font-black text-white">
               {user.name.charAt(0)}
             </div>
             <div className="flex-1 overflow-hidden">
               <p className="text-sm font-bold text-white truncate">{user.name}</p>
               <p className="text-[10px] font-bold text-green-300 uppercase truncate tracking-wider">{user.role}</p>
             </div>
          </div>
          <button onClick={handleLogout} className="w-full bg-red-500/10 hover:bg-red-500/20 text-red-200 border border-red-500/20 py-2.5 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-2">
            <LogOut size={14} /> Log Out
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden bg-slate-50">
        <div className="lg:hidden bg-white border-b border-slate-200 p-4 flex items-center justify-between shadow-sm">
          <div className="flex items-center space-x-3">
             <div className="w-8 h-8"><Logo /></div>
            <span className="font-black text-green-700 tracking-tighter">OLFU SAFETYNET</span>
          </div>
          <button onClick={() => setIsSidebarOpen(true)} className="text-slate-600"><Menu size={24} /></button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-10">
          <div className="max-w-6xl mx-auto">{renderContent()}</div>
        </div>
      </main>
    </div>
  );
};

export default App;

