            <span className={`px-2 py-1 rounded-md text-[10px] font-black flex items-center gap-1.5 shadow-sm border ${workerProfile.ppeCompliant ? 'bg-indigo-50 text-indigo-700 border-indigo-100' : 'bg-red-50 text-red-700 border-red-100 animate-pulse'}`}>
