                    <MapPin size={24} className="text-green-400" /> {workerProfile.currentLocation}
                  </p>
                </div>
                {!workerProfile.ppeCompliant && (
                   <div className="bg-amber-500/20 border border-amber-500/40 p-5 rounded-2xl flex items-center gap-4">
                      <div className="bg-amber-500 p-2 rounded-xl text-white">
                        <AlertTriangle size={20} />
                      </div>
                      <div className="flex-1">
                         <p className="text-sm font-black text-amber-50 uppercase tracking-tight">PPE Scan Pending</p>
                         <p className="text-xs text-amber-200/80">Safety protocol requires AI visual verification.</p>
                      </div>
                      <button onClick={() => handleStartCamera('ppe')} className="bg-white text-amber-700 text-xs font-black px-4 py-2 rounded-xl shadow-lg active:scale-95 transition-transform">
