                <button 
                  onClick={() => handleStartCamera('completion')}
                  disabled={isLoadingSummary || !workerProfile.ppeCompliant}
                  className="w-full bg-white text-green-700 font-black py-4 rounded-2xl mt-4 hover:bg-green-50 transition-all shadow-2xl flex items-center justify-center gap-3 text-lg uppercase tracking-tight active:scale-95 disabled:opacity-50"
                >
                  <Camera size={24} />
                  CAPTURE EVIDENCE & LOG OUT
                </button>
              </div>
            ) : workerProfile.safetyStatus === 'Pending' ? (
              <div className="text-center py-20">
                <div className="bg-white/10 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-6 backdrop-blur-sm border border-white/10">
                  <Clock className="opacity-80 text-white animate-pulse" size={48} />
                </div>
                <p className="font-black text-2xl tracking-tight">Clearance Requested</p>
                <p className="text-sm text-slate-400 mt-2 px-10 font-medium">Safety Officer is currently reviewing your profile.</p>
              </div>
            ) : (
              <div className="text-center py-10 space-y-6">
                <div className="bg-white/10 w-24 h-24 rounded-full flex items-center justify-center mx-auto backdrop-blur-sm border border-white/10">
                  <ShieldCheck className="opacity-80 text-white" size={48} />
