                 </div>
              </div>
            </div>
            <button 
              onClick={handleHardwareSync}
              disabled={isSyncing}
              className="w-full mt-4 bg-slate-50 hover:bg-slate-100 border border-slate-200 py-3 rounded-xl text-[10px] font-black uppercase text-slate-600 flex items-center justify-center gap-2"
