              {isSyncing ? <RefreshCw className="animate-spin" size={14} /> : <Cpu size={14} />}
              {isSyncing ? 'SYNCING DATA...' : 'REFRESH VITALS'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

