import React, { useState, useEffect } from 'react';
import Dashboard from './components/Dashboard';
import IncidentAnalysis from './components/IncidentAnalysis';
import SafetyMonitoring from './components/SafetyMonitoring';
import WorkforceDeployment from './components/WorkforceDeployment';
import Login from './components/Login';
import UserManagement from './components/UserManagement';
import TechnicianPortal from './components/TechnicianPortal';
import Logo from './components/Logo';
import { api } from './api';
import { User, UserRole, Worker, Shift, ShiftReport, Incident } from './types';
import { LayoutDashboard, Users, ShieldAlert, FileWarning, Menu, LogOut, HardHat, Activity, ClipboardCheck, UserCog, Loader2 } from 'lucide-react';

type View = 'dashboard' | 'monitoring' | 'deployment' | 'incidents' | 'users' | 'portal';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [globalWorkers, setGlobalWorkers] = useState<Worker[]>([]);
  const [globalUsers, setGlobalUsers] = useState<User[]>([]);
  const [shiftReports, setShiftReports] = useState<ShiftReport[]>([]);
  const [incidents, setIncidents] = useState<Incident[]>([]);

  // Initial Data Fetch from Simulated DB
  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      setError(null);
      try {
        const [usersData, workersData, reportsData, incidentsData] = await Promise.all([
          api.getUsers(),
          api.getWorkers(),
          api.getReports(),
          api.getIncidents()
        ]);
        setGlobalUsers(usersData || []);
        setGlobalWorkers(workersData || []);
        setShiftReports(reportsData || []);
        setIncidents(incidentsData || []);
      } catch (err) {
        console.error("Data load failed:", err);
        setError("Critical error initializing database. Please refresh.");
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    if (loggedInUser.role === 'Staff') setCurrentView('portal');
    else if (loggedInUser.role === 'SafetyOfficer') setCurrentView('deployment');
    else setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setUser(null);
    setCurrentView('dashboard');
  };

  const handleUpdateWorkers = async (updatedWorkers: Worker[]) => {
    setGlobalWorkers(updatedWorkers);
    // Find the specific changed worker and sync to simulated DB
    try {
      const changed = updatedWorkers.find((w, i) => {
        const original = globalWorkers[i];
        if (!original) return true; // Newly added worker
        return JSON.stringify(w) !== JSON.stringify(original);
      });

      if (changed && changed.id) {
        await api.updateWorker(changed.id, changed);
      }
    } catch (e) {
      console.error("Sync failed:", e);
    }
  };

  const handleAddWorker = async (newWorker: Worker) => {
    setGlobalWorkers([...globalWorkers, newWorker]);
    // Backend logic handled via User creation usually
  };

  const handleAddUser = async (newUser: User) => {
    try {
      const savedUser = await api.createUser(newUser);
      setGlobalUsers([...globalUsers, savedUser]);
    } catch (e) {
      alert("Failed to create user.");
    }
  };

  const handleAddReport = async (report: ShiftReport) => {
    try {
      const savedReport = await api.createReport(report);
      setShiftReports(prev => [savedReport, ...prev]);
    } catch (e) {
      console.error("Report save failed");
    }
  };

  const handleEditUser = async (updatedUser: User) => {
    setGlobalUsers(globalUsers.map(u => u && u.id === updatedUser.id ? updatedUser : u));
    // Simulated DB update would go here
  };

  const handleDeleteUser = async (userId: string) => {
    setGlobalUsers(globalUsers.filter(u => u && u.id !== userId));
    // Simulated DB delete would go here
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-900 flex flex-col items-center justify-center text-white">
        <div className="relative mb-8">
           <div className="w-24 h-24 border-4 border-green-500/20 border-t-green-500 rounded-full animate-spin"></div>
           <Activity className="absolute inset-0 m-auto text-green-500 animate-pulse" size={32} />
        </div>
        <h2 className="text-xl font-black uppercase tracking-[0.3em] text-green-500 mb-2">SafetyNet</h2>
        <p className="font-bold text-slate-400 uppercase tracking-widest text-[10px] animate-pulse">Initializing Persistence Layer...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 text-center">
        <ShieldAlert className="text-red-500 mb-4" size={64} />
        <h1 className="text-2xl font-black text-slate-800 uppercase">System Error</h1>
        <p className="text-slate-500 mt-2 max-w-md">{error}</p>
        <button 
          onClick={() => window.location.reload()}
          className="mt-6 bg-slate-900 text-white px-8 py-3 rounded-xl font-bold uppercase tracking-widest text-xs hover:bg-slate-800 transition-all"
        >
          Reload Interface
        </button>
      </div>
    );
  }

  const renderContent = () => {
    if (!user) return <Login onLogin={handleLogin} users={globalUsers} />;

    switch (currentView) {
      case 'dashboard':
        return <Dashboard workers={globalWorkers} incidents={incidents} user={user} setView={setCurrentView} />;
      case 'monitoring':
        return <SafetyMonitoring initialWorkers={globalWorkers} />;
      case 'deployment':
        return (
          <WorkforceDeployment 
            workers={globalWorkers} 
            onUpdateWorkers={handleUpdateWorkers}
            shifts={[]} 
            userRole={user.role} 
            reports={shiftReports}
          />
        );
      case 'incidents':
        return <IncidentAnalysis incidents={incidents} />;
      case 'users':
        return (
          <UserManagement 
            users={globalUsers} 
            onAddUser={handleAddUser}
            onEditUser={handleEditUser}
            onAddWorker={handleAddWorker}
            onDeleteUser={handleDeleteUser}
          />
        );
      case 'portal':
        return (
          <TechnicianPortal 
            user={user} 
            workers={globalWorkers} 
            shifts={[] as Shift[]} 
            onAddReport={handleAddReport}
            onUpdateWorkers={handleUpdateWorkers}
          />
        );
      default:
        return <Dashboard workers={globalWorkers} incidents={incidents} user={user} setView={setCurrentView} />;
    }
  };

  const NavItem = ({ view, label, icon: Icon, allowedRoles }: { view: View; label: string; icon: any; allowedRoles?: UserRole[] }) => {
    if (allowedRoles && user && !allowedRoles.includes(user.role)) return null;

    return (
      <button
        onClick={() => {
          setCurrentView(view);
          setIsSidebarOpen(false);
        }}
        className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all duration-200 ${
          currentView === view 
            ? 'bg-white text-green-700 shadow-lg shadow-green-900/20 font-bold scale-[1.02]' 
            : 'text-green-50 hover:bg-green-600/50 hover:text-white'
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </button>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 flex font-sans text-slate-900">
      {isSidebarOpen && <div className="fixed inset-0 bg-black/50 z-20 lg:hidden" onClick={() => setIsSidebarOpen(false)} />}

      <aside className={`
        fixed inset-y-0 left-0 z-30 w-72 bg-gradient-to-b from-green-700 to-green-800 text-white transform transition-transform duration-300 ease-in-out lg:translate-x-0 lg:static lg:h-screen flex flex-col shadow-2xl
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-8 border-b border-green-600/50">
          <div className="flex items-center space-x-4 mb-3">
            <div className="w-12 h-12 bg-white rounded-2xl p-1.5 flex items-center justify-center shadow-lg transform -rotate-3">
               <Logo />
            </div>
            <div>
              <span className="text-xl font-black tracking-tighter leading-none block">OLFU</span>
              <span className="text-sm font-bold tracking-widest text-green-100 block opacity-70">SAFETYNET</span>
            </div>
          </div>
          <p className="text-[10px] font-bold text-green-200/60 uppercase tracking-widest">Valenzuela Main Campus</p>
        </div>

        <nav className="flex-1 p-6 space-y-3 overflow-y-auto">
          <NavItem view="dashboard" label="Overview" icon={LayoutDashboard} allowedRoles={['Admin', 'Supervisor', 'SafetyOfficer']} />
          <NavItem view="deployment" label="Deployment" icon={ClipboardCheck} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />
          <NavItem view="monitoring" label="Real-Time Protection" icon={Activity} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />
          <NavItem view="incidents" label="Incident Logs" icon={FileWarning} allowedRoles={['Admin', 'SafetyOfficer']} />
          <NavItem view="users" label="User Management" icon={UserCog} allowedRoles={['Admin']} />
          <NavItem view="portal" label="My Assignment" icon={HardHat} allowedRoles={['Staff']} />
        </nav>

        <div className="p-6 border-t border-green-600/50 bg-green-900/20">
          <div className="flex items-center gap-3 mb-6 px-2">
             <div className="w-10 h-10 rounded-xl bg-white/10 backdrop-blur-md border border-white/20 flex items-center justify-center text-sm font-black text-white">
               {user && user.name ? user.name.charAt(0) : '?'}
             </div>
             <div className="flex-1 overflow-hidden">
               <p className="text-sm font-bold text-white truncate">{user && user.name ? user.name : 'Unknown'}</p>
               <p className="text-[10px] font-bold text-green-300 uppercase truncate tracking-wider">{user && user.role ? user.role : 'Guest'}</p>
             </div>
          </div>
          <button onClick={handleLogout} className="w-full bg-red-500/10 hover:bg-red-500/20 text-red-200 border border-red-500/20 py-2.5 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-2">
            <LogOut size={14} /> Log Out
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden bg-slate-50">
        <div className="lg:hidden bg-white border-b border-slate-200 p-4 flex items-center justify-between shadow-sm">
          <div className="flex items-center space-x-3">
             <div className="w-8 h-8"><Logo /></div>
            <span className="font-black text-green-700 tracking-tighter">OLFU SAFETYNET</span>
          </div>
          <button onClick={() => setIsSidebarOpen(true)} className="text-slate-600"><Menu size={24} /></button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-10">
          <div className="max-w-6xl mx-auto">{renderContent()}</div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { User } from '../types';
import { Lock, User as UserIcon, ArrowRight, ShieldCheck, HelpCircle } from 'lucide-react';
import Logo from './Logo';

interface Props {
  onLogin: (user: User) => void;
  users: User[];
}

const Login: React.FC<Props> = ({ onLogin, users }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    // Simulate network delay for professional feel
    setTimeout(() => {
      const user = users.find(u => u.username.toLowerCase() === username.toLowerCase());

      if (user) {
        onLogin(user);
      } else {
        setError('Unauthorized access. Please verify credentials.');
        setIsLoading(false);
      }
    }, 800);
  };

  return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-6 relative overflow-hidden">
      {/* Decorative Background Elements */}
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none opacity-20">
        <div className="absolute -top-[10%] -left-[10%] w-[40%] h-[40%] bg-green-500/20 blur-[120px] rounded-full"></div>
        <div className="absolute -bottom-[10%] -right-[10%] w-[40%] h-[40%] bg-green-700/20 blur-[120px] rounded-full"></div>
      </div>

      <div className="w-full max-w-[420px] z-10 animate-fade-in">
        <div className="bg-white rounded-[2.5rem] shadow-2xl overflow-hidden border border-white/20">
          {/* Header */}
          <div className="pt-12 pb-8 px-8 text-center bg-gradient-to-b from-green-50/50 to-transparent">
            <div className="mx-auto w-20 h-20 mb-6 transform transition-transform hover:scale-110 duration-500">
               <Logo />
            </div>
            <h1 className="text-3xl font-black text-slate-900 tracking-tighter uppercase leading-none">SafetyNet</h1>
            <p className="text-slate-500 text-xs font-bold uppercase tracking-[0.2em] mt-3 opacity-60">OLFU Valenzuela Campus</p>
          </div>

          {/* Form */}
          <div className="px-10 pb-12">
            <form onSubmit={handleLogin} className="space-y-5">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Authentication ID</label>
                <div className="relative group">
                  <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-slate-400 group-focus-within:text-green-600 transition-colors">
                    <UserIcon size={18} />
                  </div>
                  <input
                    type="text"
                    required
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    className="block w-full pl-11 pr-4 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:ring-4 focus:ring-green-500/10 focus:border-green-500/50 text-slate-900 placeholder-slate-400 transition-all outline-none font-medium"
                    placeholder="Enter Staff ID"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <div className="flex justify-between items-center ml-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Security Pin</label>
                </div>
                <div className="relative group">
                  <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-slate-400 group-focus-within:text-green-600 transition-colors">
                    <Lock size={18} />
                  </div>
                  <input
                    type="password"
                    required
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="block w-full pl-11 pr-4 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:ring-4 focus:ring-green-500/10 focus:border-green-500/50 text-slate-900 placeholder-slate-400 transition-all outline-none"
                    placeholder="••••••••"
                  />
                </div>
              </div>

              {error && (
                <div className="bg-red-50 text-red-600 p-4 rounded-2xl border border-red-100 text-xs font-bold flex items-center gap-2 animate-shake">
                   <ShieldCheck size={16} className="shrink-0" />
                   {error}
                </div>
              )}

              <button
                type="submit"
                disabled={isLoading}
                className="w-full relative group overflow-hidden bg-slate-900 text-white font-black py-4 rounded-2xl transition-all shadow-xl shadow-slate-900/20 active:scale-95 disabled:opacity-70 mt-4"
              >
                <div className="absolute inset-0 bg-green-600 translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
                <span className="relative flex items-center justify-center gap-2 uppercase tracking-widest text-xs">
                  {isLoading ? 'Verifying...' : 'Access Terminal'}
                  {!isLoading && <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform" />}
                </span>
              </button>
            </form>

            <div className="mt-8 flex items-center justify-center gap-2">
              <HelpCircle size={14} className="text-slate-300" />
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">
                Support: helpdesk.valenzuela@olfu.edu.ph
              </p>
            </div>
          </div>
        </div>

        <p className="mt-8 text-center text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] opacity-40">
          © 2025 OUR LADY OF FATIMA UNIVERSITY
        </p>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import Dashboard from './components/Dashboard';
import IncidentAnalysis from './components/IncidentAnalysis';
import SafetyMonitoring from './components/SafetyMonitoring';
import WorkforceDeployment from './components/WorkforceDeployment';
import Login from './components/Login';
import UserManagement from './components/UserManagement';
import TechnicianPortal from './components/TechnicianPortal';
import Logo from './components/Logo';
import { api } from './api';
import { User, UserRole, Worker, Shift, ShiftReport, Incident } from './types';
import { LayoutDashboard, Users, ShieldAlert, FileWarning, Menu, LogOut, HardHat, Activity, ClipboardCheck, UserCog, Loader2 } from 'lucide-react';

type View = 'dashboard' | 'monitoring' | 'deployment' | 'incidents' | 'users' | 'portal';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [globalWorkers, setGlobalWorkers] = useState<Worker[]>([]);
  const [globalUsers, setGlobalUsers] = useState<User[]>([]);
  const [shiftReports, setShiftReports] = useState<ShiftReport[]>([]);
  const [incidents, setIncidents] = useState<Incident[]>([]);

  // Initial Data Fetch from Simulated DB
  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      setError(null);
      try {
        const [usersData, workersData, reportsData, incidentsData] = await Promise.all([
          api.getUsers(),
          api.getWorkers(),
          api.getReports(),
          api.getIncidents()
        ]);
        setGlobalUsers(usersData || []);
        setGlobalWorkers(workersData || []);
        setShiftReports(reportsData || []);
        setIncidents(incidentsData || []);
      } catch (err) {
        console.error("Data load failed:", err);
        setError("Critical error initializing database. Please refresh.");
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    if (loggedInUser.role === 'Staff') setCurrentView('portal');
    else if (loggedInUser.role === 'SafetyOfficer') setCurrentView('deployment');
    else setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setUser(null);
    setCurrentView('dashboard');
  };

  const handleUpdateWorkers = async (updatedWorkers: Worker[]) => {
    setGlobalWorkers(updatedWorkers);
    try {
      const changed = updatedWorkers.find((w, i) => {
        const original = globalWorkers[i];
        if (!original) return true;
        return JSON.stringify(w) !== JSON.stringify(original);
      });

      if (changed && changed.id) {
        await api.updateWorker(changed.id, changed);
      }
    } catch (e) {
      console.error("Sync failed:", e);
    }
  };

  const handleAddWorker = async (newWorker: Worker) => {
    setGlobalWorkers([...globalWorkers, newWorker]);
  };

  const handleAddUser = async (newUser: User) => {
    try {
      const savedUser = await api.createUser(newUser);
      setGlobalUsers([...globalUsers, savedUser]);
    } catch (e) {
      alert("Failed to create user.");
    }
  };

  const handleAddReport = async (report: ShiftReport) => {
    try {
      const savedReport = await api.createReport(report);
      setShiftReports(prev => [savedReport, ...prev]);
    } catch (e) {
      console.error("Report save failed");
    }
  };

  const handleEditUser = async (updatedUser: User) => {
    setGlobalUsers(globalUsers.map(u => u && u.id === updatedUser.id ? updatedUser : u));
  };

  const handleDeleteUser = async (userId: string) => {
    setGlobalUsers(globalUsers.filter(u => u && u.id !== userId));
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-900 flex flex-col items-center justify-center text-white">
        <div className="relative mb-8">
           <div className="w-24 h-24 border-4 border-green-500/20 border-t-green-500 rounded-full animate-spin"></div>
           <Activity className="absolute inset-0 m-auto text-green-500 animate-pulse" size={32} />
        </div>
        <h2 className="text-xl font-black uppercase tracking-[0.3em] text-green-500 mb-2">SafetyNet</h2>
        <p className="font-bold text-slate-400 uppercase tracking-widest text-[10px] animate-pulse">Initializing Persistence Layer...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 text-center">
        <ShieldAlert className="text-red-500 mb-4" size={64} />
        <h1 className="text-2xl font-black text-slate-800 uppercase">System Error</h1>
        <p className="text-slate-500 mt-2 max-w-md">{error}</p>
        <button onClick={() => window.location.reload()} className="mt-6 bg-slate-900 text-white px-8 py-3 rounded-xl font-bold uppercase tracking-widest text-xs hover:bg-slate-800 transition-all">
          Reload Interface
        </button>
      </div>
    );
  }

  // --- LOGIN ISOLATION ---
  if (!user) {
    return <Login onLogin={handleLogin} users={globalUsers} />;
  }

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return <Dashboard workers={globalWorkers} incidents={incidents} user={user} setView={setCurrentView} />;
      case 'monitoring':
        return <SafetyMonitoring initialWorkers={globalWorkers} />;
      case 'deployment':
        return (
          <WorkforceDeployment 
            workers={globalWorkers} 
            onUpdateWorkers={handleUpdateWorkers}
            shifts={[]} 
            userRole={user.role} 
            reports={shiftReports}
          />
        );
      case 'incidents':
        return <IncidentAnalysis incidents={incidents} />;
      case 'users':
        return (
          <UserManagement 
            users={globalUsers} 
            onAddUser={handleAddUser}
            onEditUser={handleEditUser}
            onAddWorker={handleAddWorker}
            onDeleteUser={handleDeleteUser}
          />
        );
      case 'portal':
        return (
          <TechnicianPortal 
            user={user} 
            workers={globalWorkers} 
            shifts={[] as Shift[]} 
            onAddReport={handleAddReport}
            onUpdateWorkers={handleUpdateWorkers}
          />
        );
      default:
        return <Dashboard workers={globalWorkers} incidents={incidents} user={user} setView={setCurrentView} />;
    }
  };

  const NavItem = ({ view, label, icon: Icon, allowedRoles }: { view: View; label: string; icon: any; allowedRoles?: UserRole[] }) => {
    if (allowedRoles && !allowedRoles.includes(user.role)) return null;

    return (
      <button
        onClick={() => {
          setCurrentView(view);
          setIsSidebarOpen(false);
        }}
        className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all duration-200 ${
          currentView === view 
            ? 'bg-white text-green-700 shadow-lg shadow-green-900/20 font-bold scale-[1.02]' 
            : 'text-green-50 hover:bg-green-600/50 hover:text-white'
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </button>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 flex font-sans text-slate-900">
      {isSidebarOpen && <div className="fixed inset-0 bg-black/50 z-20 lg:hidden" onClick={() => setIsSidebarOpen(false)} />}

      <aside className={`
        fixed inset-y-0 left-0 z-30 w-72 bg-gradient-to-b from-green-700 to-green-800 text-white transform transition-transform duration-300 ease-in-out lg:translate-x-0 lg:static lg:h-screen flex flex-col shadow-2xl
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-8 border-b border-green-600/50">
          <div className="flex items-center space-x-4 mb-3">
            <div className="w-12 h-12 bg-white rounded-2xl p-1.5 flex items-center justify-center shadow-lg transform -rotate-3">
               <Logo />
            </div>
            <div>
              <span className="text-xl font-black tracking-tighter leading-none block">OLFU</span>
              <span className="text-sm font-bold tracking-widest text-green-100 block opacity-70">SAFETYNET</span>
            </div>
          </div>
          <p className="text-[10px] font-bold text-green-200/60 uppercase tracking-widest">Valenzuela Main Campus</p>
        </div>

        <nav className="flex-1 p-6 space-y-3 overflow-y-auto">
          <NavItem view="dashboard" label="Overview" icon={LayoutDashboard} allowedRoles={['Admin', 'Supervisor', 'SafetyOfficer']} />
          <NavItem view="deployment" label="Deployment" icon={ClipboardCheck} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />
          <NavItem view="monitoring" label="Real-Time Protection" icon={Activity} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />
          <NavItem view="incidents" label="Incident Logs" icon={FileWarning} allowedRoles={['Admin', 'SafetyOfficer']} />
          <NavItem view="users" label="User Management" icon={UserCog} allowedRoles={['Admin']} />
          <NavItem view="portal" label="My Assignment" icon={HardHat} allowedRoles={['Staff']} />
        </nav>

        <div className="p-6 border-t border-green-600/50 bg-green-900/20">
          <div className="flex items-center gap-3 mb-6 px-2">
             <div className="w-10 h-10 rounded-xl bg-white/10 backdrop-blur-md border border-white/20 flex items-center justify-center text-sm font-black text-white">
               {user.name.charAt(0)}
             </div>
             <div className="flex-1 overflow-hidden">
               <p className="text-sm font-bold text-white truncate">{user.name}</p>
               <p className="text-[10px] font-bold text-green-300 uppercase truncate tracking-wider">{user.role}</p>
             </div>
          </div>
          <button onClick={handleLogout} className="w-full bg-red-500/10 hover:bg-red-500/20 text-red-200 border border-red-500/20 py-2.5 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-2">
            <LogOut size={14} /> Log Out
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden bg-slate-50">
        <div className="lg:hidden bg-white border-b border-slate-200 p-4 flex items-center justify-between shadow-sm">
          <div className="flex items-center space-x-3">
             <div className="w-8 h-8"><Logo /></div>
            <span className="font-black text-green-700 tracking-tighter">OLFU SAFETYNET</span>
          </div>
          <button onClick={() => setIsSidebarOpen(true)} className="text-slate-600"><Menu size={24} /></button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-10">
          <div className="max-w-6xl mx-auto">{renderContent()}</div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { User, UserRole } from '../types';
import { Lock, User as UserIcon, ArrowRight, ShieldCheck, HelpCircle, Zap } from 'lucide-react';
import Logo from './Logo';

interface Props {
  onLogin: (user: User) => void;
  users: User[];
}

const Login: React.FC<Props> = ({ onLogin, users }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    processLogin(username);
  };

  const processLogin = (uname: string) => {
    setIsLoading(true);
    setError('');

    setTimeout(() => {
      const user = users.find(u => u.username.toLowerCase() === uname.toLowerCase());
      if (user) {
        onLogin(user);
      } else {
        setError('Unauthorized access. Please verify credentials.');
        setIsLoading(false);
      }
    }, 600);
  };

  const roles: UserRole[] = ['Admin', 'SafetyOfficer', 'Supervisor', 'Staff'];

  return (
    <div className="min-h-screen bg-emerald-950 flex items-center justify-center p-6 relative overflow-hidden">
      {/* Decorative Background Elements */}
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none">
        <div className="absolute top-[-10%] left-[-5%] w-[50%] h-[50%] bg-green-500/10 blur-[150px] rounded-full"></div>
        <div className="absolute bottom-[-10%] right-[-5%] w-[50%] h-[50%] bg-green-400/10 blur-[150px] rounded-full"></div>
        <div className="absolute inset-0 opacity-[0.03]" style={{ backgroundImage: 'radial-gradient(#ffffff 1px, transparent 1px)', backgroundSize: '40px 40px' }}></div>
      </div>

      <div className="w-full max-w-5xl z-10 flex flex-col lg:flex-row gap-8 items-stretch animate-fade-in">

        {/* Left Side: Manual Login Form */}
        <div className="lg:w-[400px] shrink-0">
          <div className="bg-white rounded-[2.5rem] shadow-2xl overflow-hidden border border-white/20 h-full flex flex-col">
            <div className="pt-10 pb-6 px-8 text-center bg-gradient-to-b from-green-50 to-transparent">
              <div className="mx-auto w-16 h-16 mb-4 transform transition-transform hover:scale-110 duration-500">
                 <Logo />
              </div>
              <h1 className="text-2xl font-black text-slate-900 tracking-tighter uppercase leading-none">SafetyNet</h1>
              <p className="text-green-700 text-[10px] font-black uppercase tracking-[0.2em] mt-2">Valenzuela Terminal</p>
            </div>

            <div className="px-8 pb-10 flex-1">
              <form onSubmit={handleLogin} className="space-y-4">
                <div className="space-y-1.5">
                  <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Personnel ID</label>
                  <div className="relative group">
                    <UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-green-600 transition-colors" size={16} />
                    <input
                      type="text"
                      required
                      value={username}
                      onChange={(e) => setUsername(e.target.value)}
                      className="block w-full pl-11 pr-4 py-3.5 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:ring-4 focus:ring-green-500/10 focus:border-green-500/50 text-slate-900 placeholder-slate-400 transition-all outline-none text-sm font-medium"
                      placeholder="Username"
                    />
                  </div>
                </div>

                <div className="space-y-1.5">
                  <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Security PIN</label>
                  <div className="relative group">
                    <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-green-600 transition-colors" size={16} />
                    <input
                      type="password"
                      required
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      className="block w-full pl-11 pr-4 py-3.5 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:ring-4 focus:ring-green-500/10 focus:border-green-500/50 text-slate-900 placeholder-slate-400 transition-all outline-none text-sm"
                      placeholder="••••••••"
                    />
                  </div>
                </div>

                {error && (
                  <div className="bg-red-50 text-red-600 p-3 rounded-xl border border-red-100 text-[10px] font-bold flex items-center gap-2 animate-shake">
                     <ShieldCheck size={14} className="shrink-0" />
                     {error}
                  </div>
                )}

                <button
                  type="submit"
                  disabled={isLoading}
                  className="w-full relative group overflow-hidden bg-green-700 text-white font-black py-4 rounded-2xl transition-all shadow-xl shadow-green-900/20 active:scale-95 disabled:opacity-70 mt-2"
                >
                  <div className="absolute inset-0 bg-green-600 translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
                  <span className="relative flex items-center justify-center gap-2 uppercase tracking-widest text-[10px]">
                    {isLoading ? 'Authenticating...' : 'Access Terminal'}
                    {!isLoading && <ArrowRight size={16} className="group-hover:translate-x-1 transition-transform" />}
                  </span>
                </button>
              </form>

              <div className="mt-8 flex items-center justify-center gap-2">
                <HelpCircle size={12} className="text-slate-300" />
                <p className="text-[9px] font-bold text-slate-400 uppercase tracking-wider">
                  Contact GS IT Support
                </p>
              </div>
            </div>
          </div>
        </div>

        {/* Right Side: Quick Access Users */}
        <div className="flex-1 flex flex-col">
          <div className="bg-white/5 backdrop-blur-md rounded-[2.5rem] p-8 border border-white/10 flex flex-col h-full">
            <div className="flex items-center gap-3 mb-8">
              <Zap className="text-green-400" size={24} />
              <div>
                <h2 className="text-white text-xl font-black uppercase tracking-tight">Quick Access Portal</h2>
                <p className="text-green-400/60 text-[10px] font-bold uppercase tracking-widest">Select an identity for rapid testing</p>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar space-y-8">
              {roles.map(role => {
                const roleUsers = users.filter(u => u.role === role);
                if (roleUsers.length === 0) return null;

                return (
                  <div key={role} className="space-y-4">
                    <h3 className="text-[10px] font-black text-green-400/40 uppercase tracking-[0.3em] pl-1 border-l-2 border-green-500/20">
                      {role === 'Staff' ? 'OPERATIONAL STAFF' : role.toUpperCase() + 'S'}
                    </h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                      {roleUsers.map(u => (
                        <button
                          key={u.id}
                          onClick={() => processLogin(u.username)}
                          disabled={isLoading}
                          className="flex items-center gap-3 p-3 bg-white/5 hover:bg-white/10 border border-white/5 hover:border-green-500/30 rounded-2xl transition-all text-left group active:scale-95"
                        >
                          <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-sm transition-all group-hover:scale-110 ${
                            role === 'Admin' ? 'bg-purple-500/20 text-purple-300' :
                            role === 'SafetyOfficer' ? 'bg-blue-500/20 text-blue-300' :
                            role === 'Supervisor' ? 'bg-amber-500/20 text-amber-300' :
                            'bg-green-500/20 text-green-300'
                          }`}>
                            {u.name.charAt(0)}
                          </div>
                          <div>
                            <p className="text-white text-xs font-black group-hover:text-green-400 transition-colors">{u.name}</p>
                            <p className="text-[9px] text-white/40 font-bold font-mono tracking-tighter">@{u.username}</p>
                          </div>
                        </button>
                      ))}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>

