import React, { useMemo } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ScatterChart, Scatter, ZAxis, Legend } from 'recharts';
import { Worker, Incident, User } from '../types';
import { AlertTriangle, TrendingUp, Users, Activity, Calendar, ShieldCheck } from 'lucide-react';

interface DashboardProps {
  workers: Worker[];
  incidents: Incident[];
  user: User;
  setView: (view: any) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ workers, incidents, user, setView }) => {

  const stats = useMemo(() => {
    const avgProd = workers.length > 0 ? workers.reduce((acc, w) => acc + w.productivityScore, 0) / workers.length : 0;
    const avgFatigue = workers.length > 0 ? workers.reduce((acc, w) => acc + w.fatigueLevel, 0) / workers.length : 0;
    const openRisks = incidents.filter(i => i.severity === 'High' || i.severity === 'Critical').length;
    const deployedCount = workers.filter(w => w.safetyStatus === 'Deployed').length;

    return {
      avgProd: Math.round(avgProd),
      avgFatigue: Math.round(avgFatigue),
      openRisks,
      totalWorkers: workers.length,
      deployedCount
    };
  }, [workers, incidents]);

  const weeklyPerformanceData = useMemo(() => {
    const data = [];
    const today = new Date();
    for (let i = 6; i >= 0; i--) {
      const d = new Date(today);
      d.setDate(today.getDate() - i);
      const dateLabel = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      const isToday = i === 0;
      data.push({
        date: dateLabel,
        productivity: isToday ? stats.avgProd : Math.max(0, Math.min(100, stats.avgProd + (Math.floor(Math.random() * 12) - 6))),
        fatigue: isToday ? stats.avgFatigue : Math.max(0, Math.min(100, stats.avgFatigue + (Math.floor(Math.random() * 10) - 5))),
      });
    }
    return data;
  }, [stats]);

  const productivityVsFatigue = useMemo(() => {
    return workers.map(w => ({
      name: w.name,
      productivity: w.productivityScore,
      fatigue: w.fatigueLevel,
      score: (w.productivityScore - (w.fatigueLevel * 0.5)).toFixed(1)
    }));
  }, [workers]);

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight uppercase">Operational Command Center</h2>
          <p className="text-slate-500 text-sm font-medium">OLFU Valenzuela Campus • Strategic Workforce Intelligence</p>
        </div>
        <div className="text-[10px] bg-green-600 text-white px-4 py-2 rounded-xl font-black flex items-center gap-2 shadow-lg shadow-green-600/20 tracking-widest uppercase">
          <Activity size={14} className="animate-pulse" /> LIVE TELEMETRY
        </div>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex items-center space-x-4 hover:shadow-md transition-shadow">
          <div className="p-4 bg-green-50 rounded-2xl text-green-600">
            <TrendingUp size={24} />
          </div>
          <div>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Efficiency</p>
            <p className="text-2xl font-black text-slate-800">{stats.avgProd}%</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex items-center space-x-4 hover:shadow-md transition-shadow">
          <div className="p-4 bg-green-100/30 rounded-2xl text-green-600">
            <Activity size={24} />
          </div>
          <div>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Avg Fatigue</p>
            <p className={`text-2xl font-black ${stats.avgFatigue > 40 ? 'text-orange-600' : 'text-green-600'}`}>
              {stats.avgFatigue}%
            </p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex items-center space-x-4 hover:shadow-md transition-shadow">
          <div className="p-4 bg-red-50 rounded-2xl text-red-600">
            <AlertTriangle size={24} />
          </div>
          <div>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">High Risks</p>
            <p className="text-2xl font-black text-slate-800">{stats.openRisks}</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex items-center space-x-4 hover:shadow-md transition-shadow">
          <div className="p-4 bg-green-600 text-white rounded-2xl shadow-lg shadow-green-600/20">
            <Users size={24} />
          </div>
          <div>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Deployed</p>
            <p className="text-2xl font-black text-slate-800">{stats.deployedCount}/{stats.totalWorkers}</p>
          </div>
        </div>
      </div>

      {/* Analytics Rows */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-lg font-black text-slate-800 flex items-center gap-3 uppercase tracking-tighter">
              <Calendar size={22} className="text-green-600"/> Weekly Performance Status
            </h3>
            <span className="text-[9px] uppercase font-black text-slate-400 tracking-[0.2em]">7-Day Operational Trend</span>
          </div>
          <div className="h-72">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={weeklyPerformanceData}>
                <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
                <XAxis 
                  dataKey="date" 
                  style={{ fontSize: '10px', fontWeight: 800, fill: '#64748b' }}
                  axisLine={false}
                  tickLine={false}
                />
                <YAxis 
                  domain={[0, 100]} 
                  style={{ fontSize: '10px', fill: '#94a3b8' }}
                  axisLine={false}
                  tickLine={false}
                />
                <Tooltip 
                  cursor={{ fill: '#f8fafc' }}
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)', fontSize: '12px', fontWeight: 700 }}
                />
                <Legend 
                  verticalAlign="top" 
                  align="right" 
                  iconType="circle"
                  wrapperStyle={{ fontSize: '9px', fontWeight: 900, paddingBottom: '30px', textTransform: 'uppercase', letterSpacing: '1px' }}
                />
                <Bar dataKey="productivity" fill="#16a34a" name="Productivity %" radius={[6, 6, 0, 0]} barSize={14} />
                <Bar dataKey="fatigue" fill="#4ade80" name="Fatigue %" radius={[6, 6, 0, 0]} barSize={14} opacity={0.3} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-lg font-black text-slate-800 flex items-center gap-3 uppercase tracking-tighter">
              <ShieldCheck size={22} className="text-green-600"/> Safety-Output Heatmap
            </h3>
            <span className="text-[9px] uppercase font-black text-slate-400 tracking-[0.2em]">Bio-Metric Heatmap</span>
          </div>
          <div className="h-72">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
                <XAxis type="number" dataKey="fatigue" name="Fatigue" unit="%" label={{ value: 'Fatigue', position: 'bottom', fontSize: 10, fontWeight: 800, fill: '#64748b' }} />
                <YAxis type="number" dataKey="productivity" name="Productivity" unit="%" label={{ value: 'Efficiency', angle: -90, position: 'left', fontSize: 10, fontWeight: 800, fill: '#64748b' }} />
                <ZAxis type="number" range={[150, 600]} />
                <Tooltip cursor={{ strokeDasharray: '3 3' }} />
                <Scatter name="Workers" data={productivityVsFatigue} fill="#16a34a" />
              </ScatterChart>
            </ResponsiveContainer>
          </div>
          <div className="bg-green-50 p-4 rounded-2xl mt-4 border border-green-100 text-center">
             <p className="text-[10px] text-green-700 font-black uppercase tracking-widest">
               High Efficiency Zone Detected
             </p>
             <p className="text-[9px] text-green-600/70 font-bold italic mt-1">
               Upper left quadrant represents optimal deployment candidates with low risk.
             </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { User } from '../types';
import { Lock, User as UserIcon, ArrowRight, ShieldCheck } from 'lucide-react';
import Logo from './Logo';

interface Props {
  onLogin: (user: User) => void;
  users: User[];
}

const Login: React.FC<Props> = ({ onLogin, users }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    processLogin(username);
  };

  const processLogin = (uname: string) => {
    setIsLoading(true);
    setError('');

    setTimeout(() => {
      const user = users.find(u => u.username.toLowerCase() === uname.toLowerCase());
      if (user) {
        onLogin(user);
      } else {
        setError('Unauthorized access. Please verify credentials.');
        setIsLoading(false);
      }
    }, 600);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-emerald-700 via-emerald-800 to-emerald-900 flex items-center justify-center p-6 relative overflow-hidden">
      {/* Decorative Background Elements */}
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none">
        <div className="absolute top-[-5%] left-[-5%] w-[40%] h-[40%] bg-white/5 blur-[120px] rounded-full"></div>
        <div className="absolute bottom-[-5%] right-[-5%] w-[40%] h-[40%] bg-emerald-400/10 blur-[120px] rounded-full"></div>
        <div className="absolute inset-0 opacity-[0.03]" style={{ backgroundImage: 'radial-gradient(#ffffff 1px, transparent 1px)', backgroundSize: '40px 40px' }}></div>
      </div>

      <div className="w-full max-w-[420px] z-10 animate-fade-in">
        <div className="bg-white rounded-[2.5rem] shadow-2xl overflow-hidden border border-white/40 shadow-emerald-950/20">
          <div className="pt-12 pb-8 px-8 text-center bg-gradient-to-b from-emerald-50/50 to-transparent">
            <div className="mx-auto w-20 h-20 mb-6 transform transition-transform hover:scale-110 duration-500 drop-shadow-sm">
               <Logo />
            </div>
            <h1 className="text-3xl font-black text-slate-900 tracking-tighter uppercase leading-none">SafetyNet</h1>
            <p className="text-emerald-700 text-xs font-black uppercase tracking-[0.2em] mt-3 opacity-90">Valenzuela Main Campus</p>
          </div>

          <div className="px-10 pb-12">
            <form onSubmit={handleLogin} className="space-y-5">
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Authentication ID</label>
                <div className="relative group">
                  <UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-emerald-600 transition-colors" size={18} />
                  <input
                    type="text"
                    required
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    className="block w-full pl-11 pr-4 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500/50 text-slate-900 placeholder-slate-400 transition-all outline-none font-medium"
                    placeholder="Username"
                  />
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Security PIN</label>
                <div className="relative group">
                  <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-emerald-600 transition-colors" size={18} />
                  <input
                    type="password"
                    required
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="block w-full pl-11 pr-4 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500/50 text-slate-900 placeholder-slate-400 transition-all outline-none"
                    placeholder="••••••••"
                  />
                </div>
              </div>

              {error && (
                <div className="bg-red-50 text-red-600 p-4 rounded-2xl border border-red-100 text-xs font-bold flex items-center gap-3 animate-shake">
                   <ShieldCheck size={18} className="shrink-0" />
                   {error}
                </div>
              )}

              <button
                type="submit"
                disabled={isLoading}
                className="w-full relative group overflow-hidden bg-emerald-700 text-white font-black py-4.5 rounded-2xl transition-all shadow-xl shadow-emerald-700/20 active:scale-95 disabled:opacity-70 mt-4 h-16"
              >
                <div className="absolute inset-0 bg-emerald-600 translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
                <span className="relative flex items-center justify-center gap-2 uppercase tracking-widest text-xs">
                  {isLoading ? 'Verifying Identity...' : 'Access Terminal'}
                  {!isLoading && <ArrowRight size={20} className="group-hover:translate-x-1 transition-transform" />}
                </span>
              </button>
            </form>
          </div>
        </div>

        <p className="mt-8 text-center text-[10px] font-black text-white/40 uppercase tracking-[0.4em]">
          Our Lady of Fatima University • © 2025
        </p>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import Dashboard from './components/Dashboard';
import IncidentAnalysis from './components/IncidentAnalysis';
import SafetyMonitoring from './components/SafetyMonitoring';
import WorkforceDeployment from './components/WorkforceDeployment';
import Login from './components/Login';
import UserManagement from './components/UserManagement';
import TechnicianPortal from './components/TechnicianPortal';
import Logo from './components/Logo';
import { api } from './api';
import { User, UserRole, Worker, Shift, ShiftReport, Incident } from './types';
import { LayoutDashboard, Users, ShieldAlert, FileWarning, Menu, LogOut, HardHat, Activity, ClipboardCheck, UserCog, Loader2 } from 'lucide-react';

type View = 'dashboard' | 'monitoring' | 'deployment' | 'incidents' | 'users' | 'portal';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [globalWorkers, setGlobalWorkers] = useState<Worker[]>([]);
  const [globalUsers, setGlobalUsers] = useState<User[]>([]);
  const [shiftReports, setShiftReports] = useState<ShiftReport[]>([]);
  const [incidents, setIncidents] = useState<Incident[]>([]);

  // Initial Data Fetch from Simulated DB
  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      setError(null);
      try {
        const [usersData, workersData, reportsData, incidentsData] = await Promise.all([
          api.getUsers(),
          api.getWorkers(),
          api.getReports(),
          api.getIncidents()
        ]);
        setGlobalUsers(usersData || []);
        setGlobalWorkers(workersData || []);
        setShiftReports(reportsData || []);
        setIncidents(incidentsData || []);
      } catch (err) {
        console.error("Data load failed:", err);
        setError("Critical error initializing database. Please refresh.");
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    if (loggedInUser.role === 'Staff') setCurrentView('portal');
    else if (loggedInUser.role === 'SafetyOfficer') setCurrentView('deployment');
    else setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setUser(null);
    setCurrentView('dashboard');
  };

  const handleUpdateWorkers = async (updatedWorkers: Worker[]) => {
    setGlobalWorkers(updatedWorkers);
    try {
      const changed = updatedWorkers.find((w, i) => {
        const original = globalWorkers[i];
        if (!original) return true;
        return JSON.stringify(w) !== JSON.stringify(original);
      });

      if (changed && changed.id) {
        await api.updateWorker(changed.id, changed);
      }
    } catch (e) {
      console.error("Sync failed:", e);
    }
  };

  const handleAddWorker = async (newWorker: Worker) => {
    setGlobalWorkers([...globalWorkers, newWorker]);
  };

  const handleAddUser = async (newUser: User) => {
    try {
      const savedUser = await api.createUser(newUser);
      setGlobalUsers([...globalUsers, savedUser]);
    } catch (e) {
      alert("Failed to create user.");
    }
  };

  const handleAddReport = async (report: ShiftReport) => {
    try {
      const savedReport = await api.createReport(report);
      setShiftReports(prev => [savedReport, ...prev]);
    } catch (e) {
      console.error("Report save failed");
    }
  };

  const handleEditUser = async (updatedUser: User) => {
    setGlobalUsers(globalUsers.map(u => u && u.id === updatedUser.id ? updatedUser : u));
  };

  const handleDeleteUser = async (userId: string) => {
    setGlobalUsers(globalUsers.filter(u => u && u.id !== userId));
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center text-white">
        <div className="relative mb-8">
           <div className="w-24 h-24 border-4 border-emerald-500/20 border-t-emerald-500 rounded-full animate-spin"></div>
           <Activity className="absolute inset-0 m-auto text-emerald-500 animate-pulse" size={32} />
        </div>
        <h2 className="text-xl font-black uppercase tracking-[0.3em] text-emerald-500 mb-2">SafetyNet</h2>
        <p className="font-bold text-slate-400 uppercase tracking-widest text-[10px] animate-pulse">Synchronizing Fatima Grid...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 text-center">
        <ShieldAlert className="text-red-500 mb-4" size={64} />
        <h1 className="text-2xl font-black text-slate-800 uppercase">System Error</h1>
        <p className="text-slate-500 mt-2 max-w-md">{error}</p>
        <button onClick={() => window.location.reload()} className="mt-6 bg-slate-900 text-white px-8 py-3 rounded-xl font-bold uppercase tracking-widest text-xs hover:bg-slate-800 transition-all">
          Reload Interface
        </button>
      </div>
    );
  }

  // --- LOGIN ISOLATION ---
  if (!user) {
    return <Login onLogin={handleLogin} users={globalUsers} />;
  }

  const NavItem = ({ view, label, icon: Icon, allowedRoles }: { view: View; label: string; icon: any; allowedRoles?: UserRole[] }) => {
    if (allowedRoles && !allowedRoles.includes(user.role)) return null;

    return (
      <button
        onClick={() => {
          setCurrentView(view);
          setIsSidebarOpen(false);
        }}
        className={`w-full flex items-center space-x-3 px-4 py-3.5 rounded-2xl transition-all duration-200 ${
          currentView === view 
            ? 'bg-white text-emerald-800 shadow-xl shadow-emerald-950/20 font-bold scale-[1.02]' 
            : 'text-emerald-50 hover:bg-white/10 hover:text-white'
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </button>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 flex font-sans text-slate-900">
      {isSidebarOpen && <div className="fixed inset-0 bg-black/50 z-20 lg:hidden" onClick={() => setIsSidebarOpen(false)} />}

      <aside className={`
        fixed inset-y-0 left-0 z-30 w-72 bg-gradient-to-b from-emerald-700 to-emerald-900 text-white transform transition-transform duration-300 ease-in-out lg:translate-x-0 lg:static lg:h-screen flex flex-col shadow-2xl
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-8 border-b border-white/10">
          <div className="flex items-center space-x-4 mb-3">
            <div className="w-12 h-12 bg-white rounded-2xl p-1.5 flex items-center justify-center shadow-lg transform -rotate-3 transition-transform hover:rotate-0">
               <Logo />
            </div>
            <div>
              <span className="text-xl font-black tracking-tighter leading-none block">OLFU</span>
              <span className="text-sm font-bold tracking-widest text-emerald-50 block opacity-80 uppercase">SAFETYNET</span>
            </div>
          </div>
          <p className="text-[10px] font-bold text-emerald-100/60 uppercase tracking-widest">Valenzuela Main Campus</p>
        </div>

        <nav className="flex-1 p-6 space-y-3 overflow-y-auto">
          <NavItem view="dashboard" label="Command Center" icon={LayoutDashboard} allowedRoles={['Admin', 'Supervisor', 'SafetyOfficer']} />
          <NavItem view="deployment" label="Force Deployment" icon={ClipboardCheck} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />
          <NavItem view="monitoring" label="Real-Time Vitality" icon={Activity} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />
          <NavItem view="incidents" label="Security Logs" icon={FileWarning} allowedRoles={['Admin', 'SafetyOfficer']} />
          <NavItem view="users" label="System Access" icon={UserCog} allowedRoles={['Admin']} />
          <NavItem view="portal" label="Active Mission" icon={HardHat} allowedRoles={['Staff']} />
        </nav>

        <div className="p-6 border-t border-white/10 bg-black/20">
          <div className="flex items-center gap-3 mb-6 px-2">
             <div className="w-11 h-11 rounded-2xl bg-white/20 backdrop-blur-md border border-white/20 flex items-center justify-center text-base font-black text-white shadow-inner">
               {user.name.charAt(0)}
             </div>
             <div className="flex-1 overflow-hidden">
               <p className="text-sm font-bold text-white truncate">{user.name}</p>
               <p className="text-[10px] font-bold text-emerald-200 uppercase truncate tracking-wider opacity-80">{user.role}</p>
             </div>
