  const [globalWorkers, setGlobalWorkers] = useState<Worker[]>([]);
  const [globalUsers, setGlobalUsers] = useState<User[]>([]);
  const [shiftReports, setShiftReports] = useState<ShiftReport[]>([]);
  const [incidents, setIncidents] = useState<Incident[]>([]);

  // Initial Data Fetch from Simulated DB
  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      setError(null);
      try {
        const [usersData, workersData, reportsData, incidentsData] = await Promise.all([
          api.getUsers(),
          api.getWorkers(),
          api.getReports(),
          api.getIncidents()
        ]);
        setGlobalUsers(usersData || []);
        setGlobalWorkers(workersData || []);
        setShiftReports(reportsData || []);
        setIncidents(incidentsData || []);
      } catch (err) {
        console.error("Data load failed:", err);
        setError("Critical error initializing database. Please refresh.");
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    if (loggedInUser.role === 'Staff') setCurrentView('portal');
    else if (loggedInUser.role === 'SafetyOfficer') setCurrentView('deployment');
    else setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setUser(null);
    setCurrentView('dashboard');
  };

  const handleUpdateWorkers = async (updatedWorkers: Worker[]) => {
    setGlobalWorkers(updatedWorkers);
    try {
      const changed = updatedWorkers.find((w, i) => {
        const original = globalWorkers[i];
        if (!original) return true;
        return JSON.stringify(w) !== JSON.stringify(original);
      });

      if (changed && changed.id) {
        await api.updateWorker(changed.id, changed);
      }
    } catch (e) {
      console.error("Sync failed:", e);
    }
  };

  const handleAddWorker = async (newWorker: Worker) => {
    setGlobalWorkers([...globalWorkers, newWorker]);
  };

  const handleAddUser = async (newUser: User) => {
    try {
      const savedUser = await api.createUser(newUser);
      setGlobalUsers([...globalUsers, savedUser]);
    } catch (e) {
      alert("Failed to create user.");
    }
  };

  const handleAddReport = async (report: ShiftReport) => {
    try {
      const savedReport = await api.createReport(report);
      setShiftReports(prev => [savedReport, ...prev]);
    } catch (e) {
      console.error("Report save failed");
    }
  };

  const handleEditUser = async (updatedUser: User) => {
    setGlobalUsers(globalUsers.map(u => u && u.id === updatedUser.id ? updatedUser : u));
  };

  const handleDeleteUser = async (userId: string) => {
    setGlobalUsers(globalUsers.filter(u => u && u.id !== userId));
  };

  // Helper function to render specific component based on active view state
  const renderContent = () => {
    if (!user) return null;

    switch (currentView) {
      case 'dashboard':
        return <Dashboard workers={globalWorkers} incidents={incidents} user={user} setView={setCurrentView} />;
      case 'monitoring':
        return <SafetyMonitoring initialWorkers={globalWorkers} />;
      case 'deployment':
        return <WorkforceDeployment workers={globalWorkers} onUpdateWorkers={handleUpdateWorkers} shifts={mockShifts} userRole={user.role} reports={shiftReports} />;
      case 'incidents':
        return <IncidentAnalysis incidents={incidents} />;
      case 'users':
        return <UserManagement users={globalUsers} onAddUser={handleAddUser} onEditUser={handleEditUser} onAddWorker={handleAddWorker} onDeleteUser={handleDeleteUser} />;
      case 'portal':
        return <TechnicianPortal user={user} workers={globalWorkers} shifts={mockShifts as Shift[]} onAddReport={handleAddReport} onUpdateWorkers={handleUpdateWorkers} />;
      default:
        return <Dashboard workers={globalWorkers} incidents={incidents} user={user} setView={setCurrentView} />;
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center text-white">
        <div className="relative mb-8">
           <div className="w-24 h-24 border-4 border-emerald-500/20 border-t-emerald-500 rounded-full animate-spin"></div>
           <Activity className="absolute inset-0 m-auto text-emerald-500 animate-pulse" size={32} />
        </div>
        <h2 className="text-xl font-black uppercase tracking-[0.3em] text-emerald-500 mb-2">SafetyNet</h2>
        <p className="font-bold text-slate-400 uppercase tracking-widest text-[10px] animate-pulse">Synchronizing Fatima Grid...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 text-center">
        <ShieldAlert className="text-red-500 mb-4" size={64} />
        <h1 className="text-2xl font-black text-slate-800 uppercase">System Error</h1>
        <p className="text-slate-500 mt-2 max-w-md">{error}</p>
        <button onClick={() => window.location.reload()} className="mt-6 bg-slate-900 text-white px-8 py-3 rounded-xl font-bold uppercase tracking-widest text-xs hover:bg-slate-800 transition-all">
          Reload Interface
        </button>
      </div>
    );
  }

  // --- LOGIN ISOLATION ---
  if (!user) {
    return <Login onLogin={handleLogin} users={globalUsers} />;
  }

  const NavItem = ({ view, label, icon: Icon, allowedRoles }: { view: View; label: string; icon: any; allowedRoles?: UserRole[] }) => {
    if (allowedRoles && !allowedRoles.includes(user.role)) return null;

    return (
      <button
        onClick={() => {
          setCurrentView(view);
          setIsSidebarOpen(false);
        }}
        className={`w-full flex items-center space-x-3 px-4 py-3.5 rounded-2xl transition-all duration-200 ${
          currentView === view 
            ? 'bg-white text-emerald-800 shadow-xl shadow-emerald-950/20 font-bold scale-[1.02]' 
            : 'text-emerald-50 hover:bg-white/10 hover:text-white'
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </button>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 flex font-sans text-slate-900">
      {isSidebarOpen && <div className="fixed inset-0 bg-black/50 z-20 lg:hidden" onClick={() => setIsSidebarOpen(false)} />}

      <aside className={`
        fixed inset-y-0 left-0 z-30 w-72 bg-gradient-to-b from-emerald-700 to-emerald-900 text-white transform transition-transform duration-300 ease-in-out lg:translate-x-0 lg:static lg:h-screen flex flex-col shadow-2xl
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-8 border-b border-white/10">
          <div className="flex items-center space-x-4 mb-3">
            <div className="w-12 h-12 bg-white rounded-2xl p-1.5 flex items-center justify-center shadow-lg transform -rotate-3 transition-transform hover:rotate-0">
               <Logo />
            </div>
            <div>
              <span className="text-xl font-black tracking-tighter leading-none block">OLFU</span>
              <span className="text-sm font-bold tracking-widest text-emerald-50 block opacity-80 uppercase">SAFETYNET</span>
            </div>
          </div>
          <p className="text-[10px] font-bold text-emerald-100/60 uppercase tracking-widest">Valenzuela Main Campus</p>
        </div>

        <nav className="flex-1 p-6 space-y-3 overflow-y-auto">
          <NavItem view="dashboard" label="Command Center" icon={LayoutDashboard} allowedRoles={['Admin', 'Supervisor', 'SafetyOfficer']} />
          <NavItem view="deployment" label="Force Deployment" icon={ClipboardCheck} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />
          <NavItem view="monitoring" label="Real-Time Vitality" icon={Activity} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />
          <NavItem view="incidents" label="Security Logs" icon={FileWarning} allowedRoles={['Admin', 'SafetyOfficer']} />
          <NavItem view="users" label="System Access" icon={UserCog} allowedRoles={['Admin']} />
          <NavItem view="portal" label="Active Mission" icon={HardHat} allowedRoles={['Staff']} />
        </nav>

        <div className="p-6 border-t border-white/10 bg-black/20">
          <div className="flex items-center gap-3 mb-6 px-2">
             <div className="w-11 h-11 rounded-2xl bg-white/20 backdrop-blur-md border border-white/20 flex items-center justify-center text-base font-black text-white shadow-inner">
