             </div>
             <table className="w-full text-sm">
                <tbody className="divide-y divide-slate-100">
                  <tr className="py-2">
                    <td className="py-2 text-slate-400 font-bold uppercase text-[9px]">Heart Rate</td>
                    <td className="py-2 text-right font-black text-slate-800">{localVitals.hr} <span className="text-[9px] text-slate-400">BPM</span></td>
                  </tr>
                  <tr className="py-2">
                    <td className="py-2 text-slate-400 font-bold uppercase text-[9px]">Body Temperature</td>
                    <td className="py-2 text-right font-black text-slate-800">{localVitals.temp} <span className="text-[9px] text-slate-400">°C</span></td>
                  </tr>
