    try {
      const [usersData, workersData, reportsData, incidentsData] = await Promise.all([
        api.getUsers(),
        api.getWorkers(),
        api.getReports(),
        api.getIncidents()
      ]);
      setGlobalUsers(usersData || []);
      setGlobalWorkers(workersData || []);
      setShiftReports(reportsData || []);
      setIncidents(incidentsData || []);
    } catch (err) {
      console.error("Database sync failed:", err);
      setError("Critical error synchronizing with Fatima database.");
    }
  }, []);

  // Initial Data Fetch
