import { User, Worker, Shift, ShiftReport, Incident } from './types';
import { mockUsers, mockWorkers, mockIncidents } from './mockData';

// Simulated delay to mimic Database/Network latency
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Local Storage Keys
const DB_KEYS = {
  USERS: 'safetynet_users',
  WORKERS: 'safetynet_workers',
  REPORTS: 'safetynet_reports',
  INCIDENTS: 'safetynet_incidents'
};

const storage = {
  get: <T>(key: string, fallback: T): T => {
    try {
      const data = localStorage.getItem(key);
      if (!data) return fallback;
      const parsed = JSON.parse(data);
      return (parsed === null || parsed === undefined) ? fallback : parsed;
    } catch (e) {
      console.error(`Error reading key "${key}":`, e);
      return fallback;
    }
  },
  set: (key: string, data: any): boolean => {
    try {
      localStorage.setItem(key, JSON.stringify(data));
      return true;
    } catch (e) {
      return false;
    }
  },
  clear: () => {
    localStorage.clear();
    window.location.reload();
  }
};

export const api = {
  async clearAllData() {
    storage.clear();
  },

  async getUsers(): Promise<User[]> {
    await delay(100);
    return storage.get(DB_KEYS.USERS, mockUsers);
  },

  async createUser(user: Partial<User>): Promise<User> {
    const users = await this.getUsers();
    const newUser = { ...user, id: `u${Date.now()}` } as User;
    storage.set(DB_KEYS.USERS, [...users, newUser]);
    return newUser;
  },

  async getWorkers(): Promise<Worker[]> {
    await delay(100);
    const workers = storage.get<Worker[]>(DB_KEYS.WORKERS, mockWorkers);
    return workers.filter(w => w !== null && w !== undefined);
  },

  async updateWorker(id: string, updates: Partial<Worker>): Promise<Worker> {
    const workers = await this.getWorkers();
    const updated = workers.map(w => w && w.id === id ? { ...w, ...updates } : w);
    storage.set(DB_KEYS.WORKERS, updated);
    return updated.find(w => w && w.id === id)!;
  },

  async getReports(): Promise<ShiftReport[]> {
    await delay(100);
    const reports = storage.get<ShiftReport[]>(DB_KEYS.REPORTS, []);
    return reports.filter(r => r !== null && r !== undefined);
  },

  async createReport(report: ShiftReport): Promise<ShiftReport> {
    let reports = await this.getReports();
    let updatedReports = [report, ...reports];

    let success = storage.set(DB_KEYS.REPORTS, updatedReports);

    if (!success) {
      // AGGRESSIVE PURGE: If still failing, strip ALL photos from ALL old reports
      console.warn("Storage Full. Purging all historical images...");
      updatedReports = updatedReports.map(r => ({ ...r, completionPhoto: undefined }));
      success = storage.set(DB_KEYS.REPORTS, updatedReports);
    }

    if (!success) {
      throw new Error("Local Storage is physically full. Please clear browser cache.");
    }

    return report;
  },

  async getIncidents(): Promise<Incident[]> {
    await delay(100);
    const incidents = storage.get(DB_KEYS.INCIDENTS, mockIncidents);
    return incidents.filter(i => i !== null && i !== undefined);
  }
};

