import { User, Worker, Shift, ShiftReport } from '../types';
import { generateShiftSummary, analyzePPECompliance } from '../services/gemini';
import { 
  HardHat, MapPin, CheckCircle, Clock, FileText, 
  CalendarCheck, Printer, ArrowLeft, ShieldCheck, 
  TrendingUp, AlertTriangle, Loader2, Sparkles, 
  Download, Award, BookmarkCheck, Camera, Scan, X,
  Bluetooth, Cpu, RefreshCw, Activity, Calendar, Image as ImageIcon, Send, LogOut
} from 'lucide-react';
import Logo from './Logo';

interface Props {
  user: User;
  workers: Worker[];
  shifts: Shift[];
  onAddReport: (report: ShiftReport) => Promise<void>;
  onUpdateWorkers: (workers: Worker[]) => void;
  onLogout: () => void;
}

const TechnicianPortal: React.FC<Props> = ({ user, workers, shifts, onAddReport, onUpdateWorkers, onLogout }) => {
  const [isCompleted, setIsCompleted] = useState(false);
  const [isLoadingSummary, setIsLoadingSummary] = useState(false);

  // Hardware Sync State
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSync, setLastSync] = useState<string | null>(null);
  const [localVitals, setLocalVitals] = useState({ hr: 0, temp: 0 });

  // Camera State
  const [showCamera, setShowCamera] = useState(false);
  const [cameraMode, setCameraMode] = useState<'ppe' | 'completion'>('ppe');
  const [isScanning, setIsScanning] = useState(false);
  const [completionPhoto, setCompletionPhoto] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const [reportGeneratedAt, setReportGeneratedAt] = useState<string>('');
  const [reportDate, setReportDate] = useState<string>('');

  const workerProfile = workers?.find(w => w && w.id === user.workerId) || (workers && workers.length > 0 ? workers[0] : null);
  const assignedShift = shifts?.find(s => s && s.name === workerProfile?.currentLocation) || (shifts && shifts.length > 0 ? shifts[0] : null);

  useEffect(() => {
    if (workerProfile) {
      setLocalVitals({ hr: workerProfile.vitals.heartRate, temp: workerProfile.vitals.bodyTemp });
    }
  }, [workerProfile]);

  if (!workerProfile) {
    return (
      <div className="flex flex-col items-center justify-center p-12 text-center bg-white rounded-3xl border-2 border-dashed border-slate-200">
        <ShieldCheck size={64} className="text-slate-200 mb-4" />
        <h2 className="text-xl font-black text-slate-800 uppercase tracking-tight">Worker Profile Missing</h2>
        <p className="text-slate-500 mt-2 text-sm max-w-xs">Your user account is not correctly linked to an operational staff profile.</p>
        <button onClick={onLogout} className="mt-6 bg-slate-900 text-white px-6 py-2 rounded-xl text-xs font-bold uppercase tracking-widest">Return to Login</button>
      </div>
    );
  }

  const handleHardwareSync = () => {
    setIsSyncing(true);
    setTimeout(() => {
      const newHr = 72 + Math.floor(Math.random() * 10);
      const newTemp = 36.5 + (Math.random() * 0.5);
      setLocalVitals({ hr: newHr, temp: Number(newTemp.toFixed(1)) });
      setLastSync(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }));
      setIsSyncing(false);
    }, 1500);
  };

  const handleRequestClearance = () => {
    const updatedWorkers = workers.map(w => 
      w && w.id === workerProfile.id ? { ...w, safetyStatus: 'Pending' } as Worker : w
    );
    onUpdateWorkers(updatedWorkers);
  };

  const handleStartCamera = async (mode: 'ppe' | 'completion') => {
    setCameraMode(mode);
    setShowCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: mode === 'ppe' ? 'user' : 'environment' } 
      });
      if (videoRef.current) videoRef.current.srcObject = stream;
    } catch (err) {
      alert("Please allow camera access.");
    }
  };

  const captureImage = async () => {
    if (!videoRef.current || !canvasRef.current) return;
    setIsScanning(true);

    const context = canvasRef.current.getContext('2d');

    // EXTREME COMPRESSION: 250px is plenty for evidence thumbnails
    const maxWidth = 250; 
    const scale = Math.min(1, maxWidth / videoRef.current.videoWidth);
    const targetWidth = videoRef.current.videoWidth * scale;
    const targetHeight = videoRef.current.videoHeight * scale;

    canvasRef.current.width = targetWidth;
    canvasRef.current.height = targetHeight;
    context?.drawImage(videoRef.current, 0, 0, targetWidth, targetHeight);

    // 0.2 Quality JPEG (~8KB)
    const compressedBase64 = canvasRef.current.toDataURL('image/jpeg', 0.2);
    const base64DataOnly = compressedBase64.split(',')[1];

    if (cameraMode === 'ppe') {
      try {
        const result = await analyzePPECompliance(base64DataOnly);
        if (result.hasHardHat && result.hasHighVisVest) {
          const updatedWorkers = workers.map(w => 
            w && w.id === workerProfile.id ? { ...w, ppeCompliant: true } as Worker : w
