            <video ref={videoRef} autoPlay playsInline className="w-full aspect-[3/4] object-cover" />
            <canvas ref={canvasRef} className="hidden" />
            <div className="absolute inset-0 border-[40px] border-black/40 pointer-events-none">
              <div className="w-full h-full border-2 border-dashed border-white/30 rounded-2xl"></div>
            </div>
            <div className="p-6 flex flex-col items-center gap-4 bg-slate-900/90 backdrop-blur-md">
              <h3 className="text-white font-black uppercase tracking-widest text-sm flex items-center gap-2">
                {cameraMode === 'ppe' ? <Scan className="text-green-400" size={16} /> : <ImageIcon className="text-blue-400" size={16} />}
                {cameraMode === 'ppe' ? 'AI SAFETY SCAN' : 'WORK EVIDENCE PHOTO'}
              </h3>
              <div className="flex gap-4 w-full">
                 <button onClick={closeCamera} className="flex-1 py-4 bg-slate-800 text-white rounded-2xl font-bold flex items-center justify-center gap-2">
                  <X size={20} /> Cancel
                </button>
                <button onClick={captureImage} disabled={isScanning} className={`flex-[2] py-4 text-white rounded-2xl font-black flex items-center justify-center gap-2 shadow-lg active:scale-95 disabled:opacity-50 ${cameraMode === 'ppe' ? 'bg-green-600' : 'bg-blue-600'}`}>
                  {isScanning ? <Loader2 className="animate-spin" size={20} /> : <Camera size={20} />}
                  {isScanning ? 'OPTIMIZING...' : cameraMode === 'ppe' ? 'VERIFY PPE' : 'CAPTURE PHOTO'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Official Printable Document */}
