      {/* Official Printable Document */}
      <div className="hidden print:block p-12 bg-white text-slate-900 min-h-screen relative overflow-hidden font-sans">
        <div className="flex justify-between items-start border-b-4 border-green-800 pb-6 mb-8 relative">
