      );
      onUpdateWorkers(updatedWorkers);

      setIsCompleted(true);
    } catch (e) {
      console.error("Shift finalization error:", e);
      alert("SYSTEM STORAGE BUSY: Optimization in progress. Please try finishing shift again in a moment.");
    } finally {
      setIsLoadingSummary(false);
    }
  };

