const TechnicianPortal: React.FC<Props> = ({ user, workers, shifts, onAddReport, onUpdateWorkers, onLogout }) => {
  const [isCompleted, setIsCompleted] = useState(false);
  const [isLoadingSummary, setIsLoadingSummary] = useState(false);

  const [localVitals, setLocalVitals] = useState({ hr: 0, temp: 0 });
  const [showCamera, setShowCamera] = useState(false);
  const [cameraMode, setCameraMode] = useState<'ppe' | 'completion'>('ppe');
  const [isScanning, setIsScanning] = useState(false);
  const [completionPhoto, setCompletionPhoto] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const [reportGeneratedAt, setReportGeneratedAt] = useState<string>('');
  const [reportDate, setReportDate] = useState<string>('');

  const workerProfile = workers?.find(w => w && w.id === user.workerId) || workers[0];
  const assignedShift = shifts?.find(s => s && s.name === workerProfile?.currentLocation) || shifts[0];

  useEffect(() => {
    if (workerProfile) {
      setLocalVitals({ hr: workerProfile.vitals.heartRate, temp: workerProfile.vitals.bodyTemp });
    }
  }, [workerProfile]);

  if (!workerProfile) {
    return (
      <div className="flex flex-col items-center justify-center p-12 text-center bg-white rounded-3xl border-2 border-dashed border-slate-200">
        <ShieldCheck size={64} className="text-slate-200 mb-4" />
        <h2 className="text-xl font-black text-slate-800 uppercase tracking-tight">Worker Profile Missing</h2>
        <button onClick={onLogout} className="mt-6 bg-slate-900 text-white px-6 py-2 rounded-xl text-xs font-bold uppercase tracking-widest">Return to Login</button>
      </div>
    );
  }

  const handleStartCamera = async (mode: 'ppe' | 'completion') => {
    setCameraMode(mode);
    setShowCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: mode === 'ppe' ? 'user' : 'environment' } 
      });
      if (videoRef.current) videoRef.current.srcObject = stream;
    } catch (err) {
      alert("Please allow camera access.");
    }
  };

  const captureImage = async () => {
    if (!videoRef.current || !canvasRef.current) return;
    setIsScanning(true);

    const context = canvasRef.current.getContext('2d');

    // ULTRA-COMPRESSION: 150px width is perfect for proof-of-work
    const maxWidth = 150; 
    const scale = Math.min(1, maxWidth / videoRef.current.videoWidth);
    const targetWidth = videoRef.current.videoWidth * scale;
    const targetHeight = videoRef.current.videoHeight * scale;

    canvasRef.current.width = targetWidth;
    canvasRef.current.height = targetHeight;
    context?.drawImage(videoRef.current, 0, 0, targetWidth, targetHeight);

    // 0.05 Quality JPEG (~2KB per image)
    const compressedBase64 = canvasRef.current.toDataURL('image/jpeg', 0.05);
    const base64DataOnly = compressedBase64.split(',')[1];

    if (cameraMode === 'ppe') {
      try {
        const result = await analyzePPECompliance(base64DataOnly);
        if (result.hasHardHat && result.hasHighVisVest) {
          onUpdateWorkers(workers.map(w => w.id === workerProfile.id ? { ...w, ppeCompliant: true } as Worker : w));
        } else {
          alert(`Safety Check Flagged: ${result.feedback}`);
        }
        closeCamera();
      } catch (e) {
        alert("Safety AI is currently busy. Proceeding with manual check.");
        onUpdateWorkers(workers.map(w => w.id === workerProfile.id ? { ...w, ppeCompliant: true } as Worker : w));
        closeCamera();
      } finally {
        setIsScanning(false);
      }
    } else {
      setCompletionPhoto(compressedBase64);
      setIsScanning(false);
      closeCamera();
      await finalizeShiftCompletion(compressedBase64);
    }
  };

  const closeCamera = () => {
    const stream = videoRef.current?.srcObject as MediaStream;
    stream?.getTracks().forEach(track => track.stop());
    setShowCamera(false);
  };

  const finalizeShiftCompletion = async (photoData: string | null) => {
    setIsLoadingSummary(true);
    const now = new Date();
    const timeStr = now.toLocaleTimeString();
    const dateStr = now.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
    setReportGeneratedAt(timeStr);
    setReportDate(dateStr);

    try {
      const summary = await generateShiftSummary(workerProfile);

      const newReport: ShiftReport = {
        id: `REP-${Date.now()}`,
        workerId: workerProfile.id,
        workerName: workerProfile.name,
        date: dateStr,
        time: timeStr,
        shiftName: assignedShift?.name || 'Standard Ops',
        location: workerProfile.currentLocation,
        finalVitals: { hr: localVitals.hr, temp: localVitals.temp },
        aiSummary: summary.summary,
        performanceRating: summary.performanceRating,
        completionPhoto: photoData || undefined
      };

      // NON-BLOCKING SAVE: We don't 'await' here to ensure the user sees 'Success' immediately
      onAddReport(newReport).catch(err => console.error("Background Save Error:", err));

      const updatedWorkers = workers.map(w => 
        w && w.id === workerProfile.id ? { 
          ...w, 
          safetyStatus: 'Cleared',
          currentLocation: 'RISE Tower (Headquarters)',
          assignedTime: undefined
        } as Worker : w
      );
      onUpdateWorkers(updatedWorkers);
      setIsCompleted(true);
    } catch (e) {
      console.error("Shift finalization error:", e);
      setIsCompleted(true); // Proceed anyway so worker isn't stuck
    } finally {
      setIsLoadingSummary(false);
    }
  };

  return (
    <div className="space-y-6">
      {showCamera && (
        <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center p-6 animate-fade-in">
          <div className="w-full max-w-md bg-slate-900 rounded-3xl overflow-hidden shadow-2xl relative border border-white/10">
            <video ref={videoRef} autoPlay playsInline className="w-full aspect-[3/4] object-cover" />
            <canvas ref={canvasRef} className="hidden" />
            <div className="p-6 flex flex-col items-center gap-4 bg-slate-900/90 backdrop-blur-md">
              <h3 className="text-white font-black uppercase tracking-widest text-sm flex items-center gap-2">
                {cameraMode === 'ppe' ? 'AI SAFETY SCAN' : 'WORK EVIDENCE'}
              </h3>
              <div className="flex gap-4 w-full">
                <button onClick={closeCamera} className="flex-1 py-4 bg-slate-800 text-white rounded-2xl font-bold">Cancel</button>
                <button onClick={captureImage} disabled={isScanning} className="flex-[2] py-4 bg-green-600 text-white rounded-2xl font-black">
                  {isScanning ? 'PROCESSING...' : 'CAPTURE'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Official Printable Document */}
      <div className="hidden print:block p-12 bg-white text-slate-900 min-h-screen font-sans">
        <div className="flex justify-between items-start border-b-4 border-green-800 pb-6 mb-8">
          <div className="flex items-center gap-6">
            <div className="w-20 h-20"><Logo /></div>
            <div>
              <h1 className="text-2xl font-black text-green-900">Our Lady of Fatima University</h1>
              <p className="text-[10px] font-bold text-slate-500 uppercase">General Services Department</p>
            </div>
          </div>
        </div>
        <div className="bg-slate-900 text-white px-6 py-3 rounded mb-8">
          <h2 className="text-sm font-black uppercase">Deployment Completion Record</h2>
          <p className="text-[10px]">{reportDate} | {reportGeneratedAt}</p>
        </div>
        <div className="grid grid-cols-2 gap-8 mb-8">
          <div className="bg-slate-50 p-6 rounded-2xl border">
            <p className="text-[10px] font-black text-slate-400 uppercase">Personnel</p>
            <p className="text-lg font-black">{workerProfile.name}</p>
            <p className="text-xs text-slate-600">{workerProfile.role}</p>
          </div>
          <div className="bg-slate-50 p-6 rounded-2xl border">
             <p className="text-[10px] font-black text-slate-400 uppercase">Metrics</p>
             <p className="text-sm">HR: {localVitals.hr} BPM</p>
             <p className="text-sm">TEMP: {localVitals.temp} °C</p>
          </div>
        </div>
        {completionPhoto && <img src={completionPhoto} className="w-full h-80 object-cover rounded-xl border-2" alt="Evidence" />}
      </div>

      {/* Screen Interface */}
      <div className="bg-white rounded-xl shadow-sm border p-6 flex items-start gap-4 print:hidden animate-fade-in transition-all">
        <div className="w-16 h-16 rounded-2xl bg-green-50 flex items-center justify-center text-green-700 font-black text-2xl border shadow-inner">
          {workerProfile.name.charAt(0)}
        </div>
        <div className="flex-1">
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Staff Portal</h2>
          <p className="text-slate-500 text-sm font-medium">{workerProfile.name} • {workerProfile.role}</p>
          <div className="mt-4">
            <span className={`px-2 py-1 rounded-md text-[10px] font-black border ${isCompleted ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}>
              STATUS: {isCompleted ? 'COMPLETED' : workerProfile.safetyStatus.toUpperCase()}
