    const base64DataOnly = compressedBase64.split(',')[1];

    if (cameraMode === 'ppe') {
      try {
        const result = await analyzePPECompliance(base64DataOnly);
        if (result.hasHardHat && result.hasHighVisVest) {
          onUpdateWorkers(workers.map(w => w.id === workerProfile.id ? { ...w, ppeCompliant: true } as Worker : w));
        } else {
          alert(`Safety Check Flagged: ${result.feedback}`);
        }
        closeCamera();
      } catch (e) {
        alert("Safety AI is currently busy. Proceeding with manual check.");
        onUpdateWorkers(workers.map(w => w.id === workerProfile.id ? { ...w, ppeCompliant: true } as Worker : w));
        closeCamera();
      } finally {
        setIsScanning(false);
      }
    } else {
      setCompletionPhoto(compressedBase64);
      setIsScanning(false);
      closeCamera();
      await finalizeShiftCompletion(compressedBase64);
    }
  };

  const closeCamera = () => {
    const stream = videoRef.current?.srcObject as MediaStream;
    stream?.getTracks().forEach(track => track.stop());
    setShowCamera(false);
  };

  // Fix: Add handleRequestClearance to update worker safety status to pending
  const handleRequestClearance = () => {
    if (!workerProfile) return;
    const updatedWorkers = workers.map(w => 
      w.id === workerProfile.id ? { ...w, safetyStatus: 'Pending' } as Worker : w
    );
    onUpdateWorkers(updatedWorkers);
    alert("Clearance request has been sent to the Safety Officer for verification.");
  };

  const finalizeShiftCompletion = async (photoData: string | null) => {
    setIsLoadingSummary(true);
    const now = new Date();
    const timeStr = now.toLocaleTimeString();
    const dateStr = now.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
    setReportGeneratedAt(timeStr);
    setReportDate(dateStr);

    try {
