import { User, Worker, Shift, ShiftReport, Incident } from './types';
import { mockUsers, mockWorkers, mockIncidents } from './mockData';

// Simulated delay
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const DB_KEYS = {
  USERS: 'safetynet_users',
  WORKERS: 'safetynet_workers',
  INCIDENTS: 'safetynet_incidents'
};

// IndexedDB implementation for High-Capacity Report Storage
const DB_NAME = 'OLFU_SafetyNet_DB';
const STORE_NAME = 'reports';

const getIDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

const storage = {
  get: <T>(key: string, fallback: T): T => {
    try {
      const data = localStorage.getItem(key);
      if (!data) return fallback;
      return JSON.parse(data) ?? fallback;
    } catch (e) {
      return fallback;
    }
  },
  set: (key: string, data: any): boolean => {
    try {
      localStorage.setItem(key, JSON.stringify(data));
      return true;
    } catch (e) {
      return false;
    }
  },
  clear: async () => {
    localStorage.clear();
    const db = await getIDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).clear();
    window.location.reload();
  }
};

export const api = {
  async clearAllData() {
    await storage.clear();
  },

  async getUsers(): Promise<User[]> {
    return storage.get(DB_KEYS.USERS, mockUsers);
  },

  async createUser(user: Partial<User>): Promise<User> {
    const users = await this.getUsers();
    const newUser = { ...user, id: `u${Date.now()}` } as User;
    storage.set(DB_KEYS.USERS, [...users, newUser]);
    return newUser;
  },

  async getWorkers(): Promise<Worker[]> {
    const workers = storage.get<Worker[]>(DB_KEYS.WORKERS, mockWorkers);
    return workers.filter(Boolean);
  },

  async updateWorker(id: string, updates: Partial<Worker>): Promise<Worker> {
    const workers = await this.getWorkers();
    const updated = workers.map(w => w.id === id ? { ...w, ...updates } : w);
    storage.set(DB_KEYS.WORKERS, updated);
    return updated.find(w => w.id === id)!;
  },

  async getReports(): Promise<ShiftReport[]> {
    const db = await getIDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const request = store.getAll();
      request.onsuccess = () => {
        // Return sorted by date/time (newest first)
        const reports = (request.result as ShiftReport[]).sort((a, b) => 
          new Date(b.date + ' ' + b.time).getTime() - new Date(a.date + ' ' + a.time).getTime()
        );
        resolve(reports);
      };
    });
  },

  async createReport(report: ShiftReport): Promise<ShiftReport> {
    const db = await getIDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, 'readwrite');
      const store = tx.objectStore(STORE_NAME);
      const request = store.add(report);
      request.onsuccess = () => resolve(report);
      request.onerror = () => reject(request.error);
    });
  },

  async getIncidents(): Promise<Incident[]> {
    return storage.get(DB_KEYS.INCIDENTS, mockIncidents);
  }
};

