        skillLevel: SkillLevel.Junior,
        certifications: [],
        productivityScore: 100,
        fatigueLevel: 0,
        currentLocation: 'General Assembly',
        vitals: { heartRate: 75, bodyTemp: 36.5, oxygenLevel: 98 },
        ppeCompliant: true,
        status: 'Active',
