          <div className="space-y-4">
            <div className="flex items-center justify-between p-3 bg-white/5 rounded-xl border border-white/10">
              <span className="text-xs font-bold text-slate-300">SSL/HTTPS</span>
              {readiness.https ? <CheckCircle2 size={16} className="text-green-500" /> : <AlertTriangle size={16} className="text-orange-500" />}
            </div>
            <div className="flex items-center justify-between p-3 bg-white/5 rounded-xl border border-white/10">
              <span className="text-xs font-bold text-slate-300">PWA Manifest</span>
              {readiness.pwa ? <CheckCircle2 size={16} className="text-green-500" /> : <AlertTriangle size={16} className="text-orange-500" />}
            </div>
            <div className="flex items-center justify-between p-3 bg-white/5 rounded-xl border border-white/10">
