type View = 'dashboard' | 'monitoring' | 'deployment' | 'incidents' | 'users' | 'portal';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [batteryLevel, setBatteryLevel] = useState<number>(100);

  const [globalWorkers, setGlobalWorkers] = useState<Worker[]>([]);
  const [globalUsers, setGlobalUsers] = useState<User[]>([]);
  const [shiftReports, setShiftReports] = useState<ShiftReport[]>([]);
  const [incidents, setIncidents] = useState<Incident[]>([]);

  // Simulation for battery level in PWA mode
  useEffect(() => {
    const interval = setInterval(() => {
      setBatteryLevel(prev => Math.max(1, prev - 1));
    }, 60000);
    return () => clearInterval(interval);
  }, []);

  // Database Synchronization Function
  const syncDatabase = useCallback(async () => {
    try {
      const [usersData, workersData, reportsData, incidentsData] = await Promise.all([
        api.getUsers(),
        api.getWorkers(),
        api.getReports(),
        api.getIncidents()
      ]);
      setGlobalUsers(usersData || []);
      setGlobalWorkers(workersData || []);
      setShiftReports(reportsData || []);
      setIncidents(incidentsData || []);
    } catch (err) {
      console.error("Database sync failed:", err);
      setError("Critical error synchronizing with Fatima database.");
    }
  }, []);

  // Initial Data Fetch
  useEffect(() => {
    const init = async () => {
      setIsLoading(true);
      await syncDatabase();
      // Artificial delay for splash aesthetic
      setTimeout(() => setIsLoading(false), 1200);
    };
    init();
  }, [syncDatabase]);

  const handleLogin = async (loggedInUser: User) => {
    setIsLoading(true);
    await syncDatabase();
    setUser(loggedInUser);
    setIsLoading(false);

    if (loggedInUser.role === 'Staff') setCurrentView('portal');
    else if (loggedInUser.role === 'SafetyOfficer') setCurrentView('deployment');
    else setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setUser(null);
    setCurrentView('dashboard');
  };

  const handleUpdateWorkers = async (updatedWorkers: Worker[]) => {
    setGlobalWorkers(updatedWorkers);
    try {
      const changed = updatedWorkers.find((w, i) => {
        const original = globalWorkers[i];
        if (!original) return true;
        return JSON.stringify(w) !== JSON.stringify(original);
      });

      if (changed && changed.id) {
        await api.updateWorker(changed.id, changed);
      }
    } catch (e) {
      console.error("Sync failed:", e);
    }
  };

  const handleAddWorker = async (newWorker: Worker) => {
    setGlobalWorkers([...globalWorkers, newWorker]);
  };

  const handleAddUser = async (newUser: User) => {
    try {
      const savedUser = await api.createUser(newUser);
      setGlobalUsers([...globalUsers, savedUser]);
    } catch (e) {
      alert("Failed to create user.");
    }
  };

  const handleAddReport = async (report: ShiftReport): Promise<void> => {
    try {
      const savedReport = await api.createReport(report);
      setShiftReports(prev => [savedReport, ...prev]);
    } catch (e) {
      console.error("Report save failed:", e);
      throw e;
    }
  };

  const handleEditUser = async (updatedUser: User) => {
    setGlobalUsers(globalUsers.map(u => u && u.id === updatedUser.id ? updatedUser : u));
  };

  const handleDeleteUser = async (userId: string) => {
    setGlobalUsers(globalUsers.filter(u => u && u.id !== userId));
  };

  const renderContent = () => {
    if (!user) return null;

    switch (currentView) {
      case 'dashboard':
        return <Dashboard workers={globalWorkers} incidents={incidents} user={user} setView={setCurrentView} />;
      case 'monitoring':
        return <SafetyMonitoring initialWorkers={globalWorkers} />;
      case 'deployment':
        return <WorkforceDeployment workers={globalWorkers} onUpdateWorkers={handleUpdateWorkers} shifts={mockShifts} userRole={user.role} reports={shiftReports} />;
      case 'incidents':
        return <IncidentAnalysis incidents={incidents} />;
      case 'users':
        return <UserManagement users={globalUsers} onAddUser={handleAddUser} onEditUser={handleEditUser} onAddWorker={handleAddWorker} onDeleteUser={handleDeleteUser} />;
      case 'portal':
        return <TechnicianPortal user={user} workers={globalWorkers} shifts={mockShifts as Shift[]} onAddReport={handleAddReport} onUpdateWorkers={handleUpdateWorkers} onLogout={handleLogout} />;
      default:
        return <Dashboard workers={globalWorkers} incidents={incidents} user={user} setView={setCurrentView} />;
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center text-white">
        <div className="relative mb-8">
           <div className="w-24 h-24 border-4 border-green-500/10 border-t-green-500 rounded-full animate-spin"></div>
           <div className="absolute inset-0 m-auto w-12 h-12">
             <Logo />
           </div>
        </div>
        <h2 className="text-xl font-black uppercase tracking-[0.4em] text-white mb-2">SafetyNet</h2>
        <div className="flex items-center gap-2 mt-4">
           <div className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></div>
           <p className="font-bold text-slate-500 uppercase tracking-widest text-[8px]">INITIALIZING OLFU CLOUD NODE...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 text-center">
        <ShieldAlert className="text-red-500 mb-4" size={64} />
        <h1 className="text-2xl font-black text-slate-800 uppercase">System Error</h1>
        <p className="text-slate-500 mt-2 max-w-md">{error}</p>
        <button onClick={() => window.location.reload()} className="mt-6 bg-slate-900 text-white px-8 py-3 rounded-xl font-bold uppercase tracking-widest text-xs hover:bg-slate-800 transition-all">
          Reload Interface
        </button>
      </div>
    );
  }

  if (!user) {
    return <Login onLogin={handleLogin} users={globalUsers} />;
  }

  const NavItem = ({ view, label, icon: Icon, allowedRoles }: { view: View; label: string; icon: any; allowedRoles?: UserRole[] }) => {
    if (allowedRoles && !allowedRoles.includes(user.role)) return null;

    return (
      <button
        onClick={() => {
          setCurrentView(view);
          setIsSidebarOpen(false);
        }}
        className={`w-full flex items-center space-x-3 px-4 py-3.5 rounded-2xl transition-all duration-200 ${
          currentView === view 
            ? 'bg-white text-green-800 shadow-xl shadow-green-950/20 font-bold scale-[1.02]' 
            : 'text-green-50 hover:bg-white/10 hover:text-white'
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </button>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 flex font-sans text-slate-900">
      {isSidebarOpen && <div className="fixed inset-0 bg-black/50 z-20 lg:hidden" onClick={() => setIsSidebarOpen(false)} />}

      <aside className={`
        fixed inset-y-0 left-0 z-30 w-72 bg-gradient-to-b from-green-700 to-green-900 text-white transform transition-transform duration-300 ease-in-out lg:translate-x-0 lg:static lg:h-screen flex flex-col shadow-2xl
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-8 border-b border-white/10">
          <div className="flex items-center space-x-4 mb-3">
            <div className="w-12 h-12 bg-white rounded-2xl p-1.5 flex items-center justify-center shadow-lg transform -rotate-3 transition-transform hover:rotate-0">
               <Logo />
            </div>
            <div>
              <span className="text-xl font-black tracking-tighter leading-none block">OLFU</span>
              <span className="text-sm font-bold tracking-widest text-green-50 block opacity-80 uppercase">SAFETYNET</span>
            </div>
          </div>
          <p className="text-[10px] font-bold text-green-100/60 uppercase tracking-widest">Valenzuela Main Campus</p>
        </div>

        <nav className="flex-1 p-6 space-y-3 overflow-y-auto">
          <NavItem view="dashboard" label="Command Center" icon={LayoutDashboard} allowedRoles={['Admin', 'Supervisor', 'SafetyOfficer']} />
          <NavItem view="deployment" label="Force Deployment" icon={ClipboardCheck} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />
          <NavItem view="monitoring" label="Real-Time Vitality" icon={Activity} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />
          <NavItem view="incidents" label="Security Logs" icon={FileWarning} allowedRoles={['Admin', 'SafetyOfficer']} />
          <NavItem view="users" label="System Access" icon={UserCog} allowedRoles={['Admin']} />
          <NavItem view="portal" label="Active Mission" icon={HardHat} allowedRoles={['Staff']} />
        </nav>

        <div className="p-6 border-t border-white/10 bg-black/20">
          <div className="flex items-center gap-3 mb-6 px-2">
             <div className="w-11 h-11 rounded-2xl bg-white/20 backdrop-blur-md border border-white/20 flex items-center justify-center text-base font-black text-white shadow-inner">
               {user.name.charAt(0)}
             </div>
             <div className="flex-1 overflow-hidden">
               <p className="text-sm font-bold text-white truncate">{user.name}</p>
               <p className="text-[10px] font-bold text-green-200 uppercase truncate tracking-wider opacity-80">{user.role}</p>
             </div>
          </div>
          <button onClick={handleLogout} className="w-full bg-white/10 hover:bg-white/20 text-white border border-white/10 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2">
            <LogOut size={14} /> Log Out
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden bg-slate-50">
        <div className="lg:hidden bg-white border-b border-slate-200 p-4 flex items-center justify-between shadow-sm">
          <div className="flex items-center space-x-3">
             <div className="w-8 h-8"><Logo /></div>
            <span className="font-black text-green-700 tracking-tighter">OLFU SAFETYNET</span>
          </div>
          <button onClick={() => setIsSidebarOpen(true)} className="text-slate-600"><Menu size={24} /></button>
        </div>

        {/* Mobile App Status Bar Emulation */}
        <div className="hidden lg:flex bg-white px-10 py-2 border-b justify-between items-center text-[10px] font-black text-slate-400 uppercase tracking-widest">
           <div className="flex gap-4">
              <span className="flex items-center gap-1.5"><Wifi size={12} className="text-green-600"/> Network: Secure OLFU-V</span>
              <span className="flex items-center gap-1.5"><ShieldCheck size={12} className="text-green-600"/> AES-256 Encrypted</span>
           </div>
           <div className="flex gap-4">
              <span className="flex items-center gap-1.5">System Load: 12% <Activity size={12} className="text-green-600"/></span>
              <span className="flex items-center gap-1.5">Internal Battery: {batteryLevel}% <Battery size={12} className={batteryLevel < 20 ? "text-red-500" : "text-green-600"}/></span>
           </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-10">
          <div className="max-w-6xl mx-auto">{renderContent()}</div>
        </div>
      </main>
    </div>
  );
};

export default App;

const CACHE_NAME = 'safetynet-offline-v2';
const ASSETS_TO_CACHE = [
  '/',
  '/index.html',
  '/manifest.json',
  '/logo.png',
  'https://cdn.tailwindcss.com',
  'https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap'
];

self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME).then(cache => {
      console.log('App is caching for offline use...');
      return cache.addAll(ASSETS_TO_CACHE);
    })
  );
  self.skipWaiting();
});

self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys().then(keys => Promise.all(
      keys.map(key => key !== CACHE_NAME ? caches.delete(key) : null)
    ))
  );
});

// Cache-First Strategy for Offline availability
self.addEventListener('fetch', event => {
  // Skip API calls to Gemini (they require internet)
  if (event.request.url.includes('generativelanguage.googleapis.com')) {
    return;
  }

  event.respondWith(
    caches.match(event.request).then(cachedResponse => {
      if (cachedResponse) return cachedResponse;

      return fetch(event.request).then(response => {
        // Cache external scripts like esm.sh on the fly
        if (event.request.url.includes('esm.sh')) {
          const clone = response.clone();
          caches.open(CACHE_NAME).then(cache => cache.put(event.request, clone));
        }
        return response;
      }).catch(() => {
        // If everything fails, return index.html for navigation
        if (event.request.mode === 'navigate') {
          return caches.match('/index.html');
        }
      });
    })
  );
});

import React, { useState, useEffect, useCallback } from 'react';
import Dashboard from './components/Dashboard';
import IncidentAnalysis from './components/IncidentAnalysis';
import SafetyMonitoring from './components/SafetyMonitoring';
import WorkforceDeployment from './components/WorkforceDeployment';
import Login from './components/Login';
import UserManagement from './components/UserManagement';
import TechnicianPortal from './components/TechnicianPortal';
import Logo from './components/Logo';
import { api } from './api';
import { mockShifts } from './mockData';
import { User, UserRole, Worker, Shift, ShiftReport, Incident } from './types';
import { 
  LayoutDashboard, Users, ShieldAlert, FileWarning, 
  Menu, LogOut, HardHat, Activity, ClipboardCheck, 
  UserCog, Wifi, WifiOff, Battery, ShieldCheck 
