  const [globalWorkers, setGlobalWorkers] = useState<Worker[]>([]);
  const [globalUsers, setGlobalUsers] = useState<User[]>([]);
  const [shiftReports, setShiftReports] = useState<ShiftReport[]>([]);
  const [incidents, setIncidents] = useState<Incident[]>([]);

  // Monitor network status
  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  const syncDatabase = useCallback(async () => {
    try {
      const [usersData, workersData, reportsData, incidentsData] = await Promise.all([
        api.getUsers(),
        api.getWorkers(),
        api.getReports(),
        api.getIncidents()
      ]);
      setGlobalUsers(usersData || []);
      setGlobalWorkers(workersData || []);
      setShiftReports(reportsData || []);
      setIncidents(incidentsData || []);
    } catch (err) {
      setError("Storage sync failed.");
    }
  }, []);

  useEffect(() => {
    const init = async () => {
      setIsLoading(true);
      await syncDatabase();
      setTimeout(() => setIsLoading(false), 800);
    };
    init();
  }, [syncDatabase]);

  const handleLogin = async (loggedInUser: User) => {
    setIsLoading(true);
    await syncDatabase();
    setUser(loggedInUser);
    setIsLoading(false);
    if (loggedInUser.role === 'Staff') setCurrentView('portal');
    else if (loggedInUser.role === 'SafetyOfficer') setCurrentView('deployment');
