                               <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{assign.role}</p>
                             </div>
                          </div>
                          <div className="text-right flex-1 max-w-sm">
                             <p className="text-[11px] text-slate-600 leading-tight italic font-medium">
                               "{assign.reason}"
                             </p>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

