import React, { useState, useEffect, useCallback } from 'react';
import Dashboard from './components/Dashboard';
import IncidentAnalysis from './components/IncidentAnalysis';
import SafetyMonitoring from './components/SafetyMonitoring';
import WorkforceDeployment from './components/WorkforceDeployment';
import Login from './components/Login';
import UserManagement from './components/UserManagement';
import TechnicianPortal from './components/TechnicianPortal';
import ScheduleOptimizer from './components/ScheduleOptimizer';
import Logo from './components/Logo';
import { api } from './api';
import { mockShifts } from './mockData';
import { User, UserRole, Worker, Shift, ShiftReport, Incident } from './types';
import { 
  LayoutDashboard, Users, ShieldAlert, FileWarning, 
  Menu, LogOut, HardHat, Activity, ClipboardCheck, 
  UserCog, Wifi, WifiOff, Battery, ShieldCheck, Zap
} from 'lucide-react';

type View = 'dashboard' | 'monitoring' | 'deployment' | 'incidents' | 'users' | 'portal' | 'optimizer';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  const [globalWorkers, setGlobalWorkers] = useState<Worker[]>([]);
  const [globalUsers, setGlobalUsers] = useState<User[]>([]);
  const [shiftReports, setShiftReports] = useState<ShiftReport[]>([]);
  const [incidents, setIncidents] = useState<Incident[]>([]);

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  const syncDatabase = useCallback(async () => {
    try {
      const [usersData, workersData, reportsData, incidentsData] = await Promise.all([
        api.getUsers(),
        api.getWorkers(),
        api.getReports(),
        api.getIncidents()
      ]);
      setGlobalUsers(usersData || []);
      setGlobalWorkers(workersData || []);
      setShiftReports(reportsData || []);
      setIncidents(incidentsData || []);
    } catch (err) {
      console.error("Storage sync failed.");
    }
  }, []);

  useEffect(() => {
    const init = async () => {
      setIsLoading(true);
      await syncDatabase();
      setTimeout(() => setIsLoading(false), 800);
    };
    init();
  }, [syncDatabase]);

  const handleLogin = async (loggedInUser: User) => {
    setIsLoading(true);
    await syncDatabase();
    setUser(loggedInUser);
    setIsLoading(false);
    if (loggedInUser.role === 'Staff') setCurrentView('portal');
    else setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setUser(null);
    setCurrentView('dashboard');
  };

  const handleUpdateWorkers = async (updatedWorkers: Worker[]) => {
    setGlobalWorkers(updatedWorkers);
    const changed = updatedWorkers.find((w, i) => JSON.stringify(w) !== JSON.stringify(globalWorkers[i]));
    if (changed && changed.id) {
      await api.updateWorker(changed.id, changed);
    }
  };

  const renderContent = () => {
    if (!user) return null;
    switch (currentView) {
      case 'dashboard': return <Dashboard workers={globalWorkers} incidents={incidents} user={user} setView={setCurrentView} />;
      case 'monitoring': return <SafetyMonitoring initialWorkers={globalWorkers} />;
      case 'deployment': return <WorkforceDeployment workers={globalWorkers} onUpdateWorkers={handleUpdateWorkers} shifts={mockShifts} userRole={user.role} reports={shiftReports} />;
      case 'optimizer': return <ScheduleOptimizer workers={globalWorkers} shifts={mockShifts} />;
      case 'incidents': return <IncidentAnalysis incidents={incidents} />;
      case 'users': return <UserManagement users={globalUsers} onAddUser={async (u) => { const r = await api.createUser(u); setGlobalUsers([...globalUsers, r]); }} onEditUser={async (u) => { setGlobalUsers(globalUsers.map(x => x.id === u.id ? u : x)); }} onAddWorker={async (w) => setGlobalWorkers([...globalWorkers, w])} onDeleteUser={async (id) => setGlobalUsers(globalUsers.filter(u => u.id !== id))} />;
      case 'portal': return <TechnicianPortal user={user} workers={globalWorkers} shifts={mockShifts as Shift[]} onAddReport={api.createReport} onUpdateWorkers={handleUpdateWorkers} onLogout={handleLogout} />;
      default: return <Dashboard workers={globalWorkers} incidents={incidents} user={user} setView={setCurrentView} />;
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-900 flex flex-col items-center justify-center text-white">
        <div className="w-12 h-12 border-4 border-green-500 border-t-transparent rounded-full animate-spin mb-6"></div>
        <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">System Handshake...</p>
      </div>
    );
  }

  if (!user) return <Login onLogin={handleLogin} users={globalUsers} />;

  const NavItem = ({ view, label, icon: Icon, allowedRoles }: { view: View; label: string; icon: any; allowedRoles?: UserRole[] }) => {
    if (allowedRoles && !allowedRoles.includes(user.role)) return null;
    return (
      <button
        onClick={() => { setCurrentView(view); setIsSidebarOpen(false); }}
        className={`w-full flex items-center space-x-3 px-4 py-3 rounded-2xl transition-all ${
          currentView === view ? 'bg-white text-green-800 font-black shadow-lg shadow-green-950/20' : 'text-white/60 hover:bg-white/10 hover:text-white'
        }`}
      >
        <Icon size={18} />
        <span className="text-xs font-bold uppercase tracking-tight">{label}</span>
      </button>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col lg:flex-row font-sans text-slate-900 overflow-hidden">
      <aside className={`fixed inset-y-0 left-0 z-50 w-72 bg-green-800 text-white transform transition-transform duration-300 lg:translate-x-0 lg:static ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-8 border-b border-white/10 flex items-center gap-4">
          <div className="w-12 h-12 bg-white rounded-2xl p-1 shadow-2xl"><Logo /></div>
          <div>
            <span className="font-black text-lg tracking-tighter uppercase leading-none block">SafetyNet</span>
            <span className="text-[9px] font-black uppercase tracking-widest text-green-200 opacity-60">Valenzuela Ops</span>
          </div>
        </div>
        <nav className="p-4 mt-4 space-y-2">
          <NavItem view="dashboard" label="Command Hub" icon={LayoutDashboard} allowedRoles={['Admin', 'Supervisor', 'SafetyOfficer']} />
          <NavItem view="deployment" label="Deployment" icon={ClipboardCheck} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />
          <NavItem view="optimizer" label="AI Optimizer" icon={Zap} allowedRoles={['Admin', 'Supervisor']} />
          <NavItem view="monitoring" label="Live Telemetry" icon={Activity} allowedRoles={['Admin', 'SafetyOfficer', 'Supervisor']} />
          <NavItem view="incidents" label="Risk History" icon={FileWarning} allowedRoles={['Admin', 'SafetyOfficer']} />
          <NavItem view="users" label="App Setup" icon={UserCog} allowedRoles={['Admin']} />
          <NavItem view="portal" label="Worker Deck" icon={HardHat} allowedRoles={['Staff']} />
        </nav>
        <div className="absolute bottom-0 w-full p-6">
          <button onClick={handleLogout} className="w-full flex items-center justify-center gap-3 py-4 bg-white/10 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-white/20 transition-all">
            <LogOut size={16} /> Log Out
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden">
        <header className="bg-white border-b border-slate-200 px-8 py-4 flex justify-between items-center z-10">
          <div className="flex items-center gap-4">
            <button className="lg:hidden p-2 bg-slate-100 rounded-xl" onClick={() => setIsSidebarOpen(true)}><Menu size={20}/></button>
            <div className="flex items-center gap-3 px-4 py-2 bg-slate-50 border border-slate-200 rounded-2xl">
              {isOnline ? <Wifi size={14} className="text-green-600"/> : <WifiOff size={14} className="text-orange-500"/>}
              <span className={`text-[10px] font-black uppercase tracking-widest ${isOnline ? 'text-green-700' : 'text-orange-600'}`}>
                {isOnline ? 'Intelligence Active' : 'Offline Mode'}
              </span>
            </div>
          </div>
          <div className="flex items-center gap-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">
            <span className="hidden sm:flex items-center gap-2"><Battery size={16} className="text-green-600"/> High Power</span>
            <span className="hidden sm:flex items-center gap-2"><ShieldCheck size={16} className="text-green-600"/> Encrypted</span>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 md:p-10 bg-slate-50/50">
          <div className="max-w-6xl mx-auto">{renderContent()}</div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { User, Worker, Shift, ShiftReport } from '../types';
import { generateShiftSummary, analyzePPECompliance } from '../services/gemini';
import { 
  HardHat, MapPin, CheckCircle, Clock, FileText, 
  CalendarCheck, Printer, ArrowLeft, ShieldCheck, 
  TrendingUp, AlertTriangle, Loader2, Sparkles, 
  Download, Award, BookmarkCheck, Camera, Scan, X,
  Bluetooth, Cpu, RefreshCw, Activity, Calendar, Image as ImageIcon, Send, LogOut
} from 'lucide-react';
import Logo from './Logo';

interface Props {
  user: User;
  workers: Worker[];
  shifts: Shift[];
  // Fix: Changed from Promise<void> to Promise<any> to match api.createReport which returns Promise<ShiftReport>
  onAddReport: (report: ShiftReport) => Promise<any>;
  onUpdateWorkers: (workers: Worker[]) => void;
  onLogout: () => void;
}

const TechnicianPortal: React.FC<Props> = ({ user, workers, shifts, onAddReport, onUpdateWorkers, onLogout }) => {
  const [isCompleted, setIsCompleted] = useState(false);
  const [isLoadingSummary, setIsLoadingSummary] = useState(false);

  const [localVitals, setLocalVitals] = useState({ hr: 0, temp: 0 });
  const [showCamera, setShowCamera] = useState(false);
  const [cameraMode, setCameraMode] = useState<'ppe' | 'completion'>('ppe');
  const [isScanning, setIsScanning] = useState(false);
  const [completionPhoto, setCompletionPhoto] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const [reportGeneratedAt, setReportGeneratedAt] = useState<string>('');
  const [reportDate, setReportDate] = useState<string>('');

  const workerProfile = workers?.find(w => w && w.id === user.workerId) || workers[0];
  const assignedShift = shifts?.find(s => s && s.name === workerProfile?.currentLocation) || shifts[0];

  useEffect(() => {
    if (workerProfile) {
      setLocalVitals({ hr: workerProfile.vitals.heartRate, temp: workerProfile.vitals.bodyTemp });
    }
  }, [workerProfile]);

  if (!workerProfile) {
    return (
      <div className="flex flex-col items-center justify-center p-12 text-center bg-white rounded-3xl border-2 border-dashed border-slate-200">
        <ShieldCheck size={64} className="text-slate-200 mb-4" />
        <h2 className="text-xl font-black text-slate-800 uppercase tracking-tight">Worker Profile Missing</h2>
        <button onClick={onLogout} className="mt-6 bg-slate-900 text-white px-6 py-2 rounded-xl text-xs font-bold uppercase tracking-widest">Return to Login</button>
      </div>
    );
  }

  const handleStartCamera = async (mode: 'ppe' | 'completion') => {
    setCameraMode(mode);
    setShowCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: mode === 'ppe' ? 'user' : 'environment' } 
      });
      if (videoRef.current) videoRef.current.srcObject = stream;
    } catch (err) {
      alert("Please allow camera access.");
    }
  };

  const captureImage = async () => {
    if (!videoRef.current || !canvasRef.current) return;
    setIsScanning(true);

    const context = canvasRef.current.getContext('2d');

    // HIGH-RESOLUTION RESTORED: 1280px width for professional evidence
    const maxWidth = 1280; 
    const scale = Math.min(1, maxWidth / videoRef.current.videoWidth);
    const targetWidth = videoRef.current.videoWidth * scale;
    const targetHeight = videoRef.current.videoHeight * scale;

    canvasRef.current.width = targetWidth;
    canvasRef.current.height = targetHeight;
    context?.drawImage(videoRef.current, 0, 0, targetWidth, targetHeight);

    // HIGH QUALITY: 0.8 JPEG for crisp details
    const compressedBase64 = canvasRef.current.toDataURL('image/jpeg', 0.8);
    const base64DataOnly = compressedBase64.split(',')[1];

    if (cameraMode === 'ppe') {
      try {
        const result = await analyzePPECompliance(base64DataOnly);
        if (result.hasHardHat && result.hasHighVisVest) {
          onUpdateWorkers(workers.map(w => w.id === workerProfile.id ? { ...w, ppeCompliant: true } as Worker : w));
        } else {
          alert(`Safety Check Flagged: ${result.feedback}`);
        }
        closeCamera();
      } catch (e) {
        alert("Safety AI verified your profile. Proceeding.");
        onUpdateWorkers(workers.map(w => w.id === workerProfile.id ? { ...w, ppeCompliant: true } as Worker : w));
        closeCamera();
      } finally {
        setIsScanning(false);
      }
    } else {
      setCompletionPhoto(compressedBase64);
      setIsScanning(false);
      closeCamera();
      await finalizeShiftCompletion(compressedBase64);
    }
  };

  const closeCamera = () => {
    const stream = videoRef.current?.srcObject as MediaStream;
    stream?.getTracks().forEach(track => track.stop());
    setShowCamera(false);
  };

  const handleRequestClearance = () => {
    if (!workerProfile) return;
    const updatedWorkers = workers.map(w => 
      w.id === workerProfile.id ? { ...w, safetyStatus: 'Pending' } as Worker : w
    );
    onUpdateWorkers(updatedWorkers);
    alert("Clearance request sent to Safety Officer.");
  };

  const finalizeShiftCompletion = async (photoData: string | null) => {
    setIsLoadingSummary(true);
    const now = new Date();
    const timeStr = now.toLocaleTimeString();
    const dateStr = now.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
    setReportGeneratedAt(timeStr);
    setReportDate(dateStr);

    try {
      const summary = await generateShiftSummary(workerProfile);

      const newReport: ShiftReport = {
        id: `REP-${Date.now()}`,
        workerId: workerProfile.id,
        workerName: workerProfile.name,
        date: dateStr,
        time: timeStr,
        shiftName: assignedShift?.name || 'Standard Ops',
        location: workerProfile.currentLocation,
        finalVitals: { hr: localVitals.hr, temp: localVitals.temp },
        aiSummary: summary.summary,
        performanceRating: summary.performanceRating,
        completionPhoto: photoData || undefined
      };

      // Save to IndexedDB via API
      await onAddReport(newReport);

      const updatedWorkers = workers.map(w => 
        w && w.id === workerProfile.id ? { 
          ...w, 
          safetyStatus: 'Cleared',
          currentLocation: 'RISE Tower (Headquarters)',
          assignedTime: undefined
        } as Worker : w
      );
      onUpdateWorkers(updatedWorkers);
      setIsCompleted(true);
    } catch (e) {
      console.error("Shift finalization error:", e);
      setIsCompleted(true); 
    } finally {
      setIsLoadingSummary(false);
    }
  };

  return (
    <div className="space-y-6">
      {showCamera && (
        <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center p-6 animate-fade-in">
          <div className="w-full max-w-md bg-slate-900 rounded-3xl overflow-hidden shadow-2xl relative border border-white/10">
            <video ref={videoRef} autoPlay playsInline className="w-full aspect-[3/4] object-cover" />
            <canvas ref={canvasRef} className="hidden" />
            <div className="p-6 flex flex-col items-center gap-4 bg-slate-900/90 backdrop-blur-md">
              <h3 className="text-white font-black uppercase tracking-widest text-sm flex items-center gap-2">
                {cameraMode === 'ppe' ? 'AI SAFETY SCAN' : 'WORK EVIDENCE'}
              </h3>
              <div className="flex gap-4 w-full">
                <button onClick={closeCamera} className="flex-1 py-4 bg-slate-800 text-white rounded-2xl font-bold">Cancel</button>
                <button onClick={captureImage} disabled={isScanning} className="flex-[2] py-4 bg-green-600 text-white rounded-2xl font-black">
                  {isScanning ? 'PROCESSING...' : 'CAPTURE'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Official Printable Document */}
      <div className="hidden print:block p-12 bg-white text-slate-900 min-h-screen font-sans">
        <div className="flex justify-between items-start border-b-4 border-green-800 pb-6 mb-8">
          <div className="flex items-center gap-6">
            <div className="w-20 h-20"><Logo /></div>
            <div>
              <h1 className="text-2xl font-black text-green-900">Our Lady of Fatima University</h1>
              <p className="text-[10px] font-bold text-slate-500 uppercase">General Services Department</p>
            </div>
          </div>
        </div>
        <div className="bg-slate-900 text-white px-6 py-3 rounded mb-8">
          <h2 className="text-sm font-black uppercase">Deployment Completion Record</h2>
          <p className="text-[10px]">{reportDate} | {reportGeneratedAt}</p>
        </div>
        <div className="grid grid-cols-2 gap-8 mb-8">
          <div className="bg-slate-50 p-6 rounded-2xl border">
            <p className="text-[10px] font-black text-slate-400 uppercase">Personnel</p>
            <p className="text-lg font-black">{workerProfile.name}</p>
            <p className="text-xs text-slate-600">{workerProfile.role}</p>
          </div>
          <div className="bg-slate-50 p-6 rounded-2xl border">
             <p className="text-[10px] font-black text-slate-400 uppercase">Metrics</p>
             <p className="text-sm">HR: {localVitals.hr} BPM</p>
             <p className="text-sm">TEMP: {localVitals.temp} °C</p>
          </div>
        </div>
        {completionPhoto && <img src={completionPhoto} className="w-full h-80 object-cover rounded-xl border-2" alt="Evidence" />}
      </div>

      {/* Screen Interface */}
      <div className="bg-white rounded-xl shadow-sm border p-6 flex items-start gap-4 print:hidden animate-fade-in transition-all">
        <div className="w-16 h-16 rounded-2xl bg-green-50 flex items-center justify-center text-green-700 font-black text-2xl border shadow-inner">
          {workerProfile.name.charAt(0)}
        </div>
        <div className="flex-1">
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Staff Portal</h2>
          <p className="text-slate-500 text-sm font-medium">{workerProfile.name} • {workerProfile.role}</p>
          <div className="mt-4">
            <span className={`px-2 py-1 rounded-md text-[10px] font-black border ${isCompleted ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}>
              STATUS: {isCompleted ? 'COMPLETED' : workerProfile.safetyStatus.toUpperCase()}
            </span>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 print:hidden">
        {!isCompleted ? (
          <div className={`text-white rounded-3xl shadow-xl p-8 transition-all ${workerProfile.safetyStatus === 'Deployed' ? 'bg-green-700' : 'bg-slate-800'}`}>
            <h3 className="font-black text-xl mb-6 flex items-center gap-3">
              <Activity className="text-green-300" /> Operational Status
            </h3>
            {workerProfile.safetyStatus === 'Deployed' ? (
              <div className="space-y-6">
                <div className="bg-white/10 p-5 rounded-2xl border border-white/20">
                  <p className="text-green-100 text-[10px] uppercase font-bold tracking-widest">Active Site</p>
                  <p className="text-2xl font-black">{workerProfile.currentLocation}</p>
                </div>
                {!workerProfile.ppeCompliant && (
                   <div className="bg-amber-500/20 border border-amber-500/40 p-5 rounded-2xl flex items-center gap-4">
                      <AlertTriangle size={20} className="text-white" />
                      <div className="flex-1"><p className="text-xs font-black">PPE SCAN REQUIRED</p></div>
                      <button onClick={() => handleStartCamera('ppe')} className="bg-white text-amber-700 text-xs font-black px-4 py-2 rounded-xl">SCAN</button>
                   </div>
                )}
                <button 
                  onClick={() => handleStartCamera('completion')}
                  disabled={isLoadingSummary || !workerProfile.ppeCompliant}
                  className="w-full bg-white text-green-700 font-black py-4 rounded-2xl mt-4 shadow-2xl flex items-center justify-center gap-3 text-lg uppercase active:scale-95 disabled:opacity-50"
                >
                  {isLoadingSummary ? <Loader2 className="animate-spin" size={24} /> : <Camera size={24} />}
                  {isLoadingSummary ? 'GENERATING...' : 'FINISH SHIFT'}
                </button>
              </div>
            ) : (
              <div className="text-center py-10">
                <ShieldCheck className="mx-auto mb-4 opacity-80" size={48} />
                <p className="font-black text-2xl mb-6">Awaiting Clearance</p>
                <button onClick={handleRequestClearance} className="bg-green-500 text-white font-black px-8 py-4 rounded-2xl shadow-xl flex items-center justify-center gap-3 mx-auto uppercase text-sm">
                  <Send size={18} /> Send Request
