             <h3 className="text-3xl font-black text-slate-800 tracking-tighter">Shift Successful</h3>
             <button onClick={() => window.print()} className="w-full bg-green-700 text-white font-black py-4 rounded-2xl flex items-center justify-center gap-3 shadow-xl transition-all">
