            </div>
            <div className="p-5 bg-slate-50 rounded-2xl border text-center">
               <p className="text-[10px] font-black text-slate-400 uppercase">Body Temp</p>
               <p className="text-3xl font-black text-slate-800">{localVitals.temp} <span className="text-[10px]">°C</span></p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

