        </div>
      );
    }

    // Default state: Pending or Rejected (allow request)
    return (
      <div className="bg-slate-800 text-white rounded-3xl shadow-xl p-8 animate-fade-in text-center flex flex-col items-center justify-center space-y-6 min-h-[300px]">
