      case 'incidents': return <IncidentAnalysis incidents={incidents} />;
      case 'users': return <UserManagement users={globalUsers} onAddUser={async (u) => { const r = await api.createUser(u); setGlobalUsers([...globalUsers, r]); }} onEditUser={async (u) => { setGlobalUsers(globalUsers.map(x => x.id === u.id ? u : x)); }} onAddWorker={async (w) => { const newWorkers = [...globalWorkers, w]; setGlobalWorkers(newWorkers); await api.saveWorkers(newWorkers); }} onDeleteUser={async (id) => setGlobalUsers(globalUsers.filter(u => u.id !== id))} />;
      case 'portal': return <TechnicianPortal user={user} workers={globalWorkers} shifts={mockShifts as Shift[]} onAddReport={handleAddReport} onUpdateWorkers={handleUpdateWorkers} onLogout={handleLogout} />;
      default: return <Dashboard workers={globalWorkers} incidents={incidents} user={user} setView={setCurrentView} />;
